import _fastgcm


class Solver:
    def solve(self, problem, **kwargs):
        key = problem["key"]
        nonce = problem["nonce"]
        plaintext = problem["plaintext"]
        aad = problem["associated_data"]
        if aad is None:
            aad = b""
        ciphertext, tag = _fastgcm.encrypt(key, nonce, aad, plaintext)
        return {"ciphertext": ciphertext, "tag": tag}

