#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/evp.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t n = 60000 * 1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n + 16);
    unsigned char key[16], iv[12], aad[32], tag[16];
    memset(key, 1, 16); memset(iv, 2, 12); memset(aad, 3, 32); memset(pt, 4, n);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    const EVP_CIPHER *cipher = EVP_aes_128_gcm();

    // warmup
    int outl = 0, outl2 = 0;
    EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
    EVP_EncryptUpdate(ctx, NULL, &outl, aad, 32);
    EVP_EncryptUpdate(ctx, ct, &outl, pt, (int)n);
    EVP_EncryptFinal_ex(ctx, ct + outl, &outl2);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);

    int reps = 3;
    double t0 = now();
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        EVP_EncryptUpdate(ctx, NULL, &outl, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &outl, pt, (int)n);
        EVP_EncryptFinal_ex(ctx, ct + outl, &outl2);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    double t1 = now();
    printf("EVP reused ctx: %.4f s  %.1f MB/s  outl=%d\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps), outl);

    // fresh ctx each time
    t0 = now();
    for (int i = 0; i < reps; i++) {
        EVP_CIPHER_CTX *c = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(c, cipher, NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(c, NULL, NULL, key, iv);
        EVP_EncryptUpdate(c, NULL, &outl, aad, 32);
        EVP_EncryptUpdate(c, ct, &outl, pt, (int)n);
        EVP_EncryptFinal_ex(c, ct + outl, &outl2);
        EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_GCM_GET_TAG, 16, tag);
        EVP_CIPHER_CTX_free(c);
    }
    t1 = now();
    printf("EVP fresh ctx: %.4f s  %.1f MB/s\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));

    // EVP_CIPHER_fetch
    EVP_CIPHER *fc = EVP_CIPHER_fetch(NULL, "AES-128-GCM", NULL);
    printf("fetched %p\n", (void*)fc);
    t0 = now();
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, fc, NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        EVP_EncryptUpdate(ctx, NULL, &outl, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &outl, pt, (int)n);
        EVP_EncryptFinal_ex(ctx, ct + outl, &outl2);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    t1 = now();
    printf("EVP fetch cipher reused: %.4f s  %.1f MB/s\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));

    EVP_CIPHER_CTX_free(ctx);
    free(pt); free(ct);
    return 0;
}
EOF
