    double t0=now();
    for(int i=0;i<reps;i++){
        EVP_EncryptInit_ex(ctx, NULL, NULL, NULL, iv); // re-set iv only?
        EVP_EncryptUpdate(ctx, ct, &outl, pt, (int)n);
        EVP_EncryptFinal_ex(ctx, ct, &outl2);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    double t1=now();
    printf("reinit iv only: %.4f s %.1f MB/s\n",(t1-t0)/reps,(n/1e6)/((t1-t0)/reps));

    t0=now();
    for(int i=0;i<reps;i++){
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        EVP_EncryptUpdate(ctx, ct, &outl, pt, (int)n);
        EVP_EncryptFinal_ex(ctx, ct, &outl2);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    t1=now();
    printf("reinit key+iv: %.4f s %.1f MB/s\n",(t1-t0)/reps,(n/1e6)/((t1-t0)/reps));

    // with aad
    unsigned char aad[32]; memset(aad,3,32);
    t0=now();
    for(int i=0;i<reps;i++){
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        int dummy;
        EVP_EncryptUpdate(ctx, NULL, &dummy, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &outl, pt, (int)n);
        EVP_EncryptFinal_ex(ctx, ct, &outl2);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    t1=now();
    printf("reinit key+iv+aad: %.4f s %.1f MB/s\n",(t1-t0)/reps,(n/1e6)/((t1-t0)/reps));

    // one shot via EVP_Cipher? 
    // chunked to see overhead
    t0=now();
    for(int i=0;i<reps;i++){
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        size_t off=0; int chunk=1<<20;
        while(off<n){
            int len = (int)((n-off)>chunk?chunk:(n-off));
