{"command":"cat > bench_threads.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <openssl/evp.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

typedef struct {
    unsigned char *pt, *ct;
    size_t n;
    unsigned char key[32];
    int keylen;
    unsigned char iv[16];
    int ivlen;
    unsigned char *aad;
    int aadlen;
    unsigned char tag[16];
    int threads;
    int tid;
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    size_t chunk = j->n / j->threads;
    size_t start = j->tid * chunk;
    size_t len = (j->tid == j->threads-1) ? (j->n - start) : chunk;
    // align to 16? GCM counter is per-block; for parallel CTR we must set the right counter.
    // Simpler approach: split plaintext into independent... no, GCM counter is sequential, GHASH is sequential.
    // Parallel CTR is possible but GHASH needs all ciphertext. For a fair test of CTR+GHASH split,
    // just encrypt the slice with its own IV to measure raw throughput scaling.
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    const char *name = j->keylen==16?"AES-128-GCM": j->keylen==24?"AES-192-GCM":"AES-256-GCM";
    EVP_CIPHER *fc = EVP_CIPHER_fetch(NULL, name, NULL);
    int outl=0, outl2=0;
    EVP_EncryptInit_ex(ctx, fc, NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, j->ivlen, NULL);
    unsigned char iv[16]; memcpy(iv, j->iv, j->ivlen); iv[11] = (unsigned char)j->tid; // distinct
    EVP_EncryptInit_ex(ctx, NULL, NULL, j->key, iv);
    EVP_EncryptUpdate(ctx, j->ct+start, &outl, j->pt+start, (int)len);
    EVP_EncryptFinal_ex(ctx, j->ct+start, &outl2);
    EVP_CIPHER_CTX_free(ctx);
    EVP_CIPHER_free(fc);
    return NULL;
}

int main() {
    size_t n = 60000*1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n);
    memset(pt, 4, n);
    for (int th = 1; th <= 6; th++) {
        job_t jobs[8];
        pthread_t tids[8];
        for (int i=0;i<th;i++) {
            jobs[i].pt=pt; jobs[i].ct=ct; jobs[i].n=n;
            memset(jobs[i].key, 1, 16); jobs[i].keylen=16;
            memset(jobs[i].iv, 2, 12); jobs[i].ivlen=12;
            jobs[i].threads=th; jobs[i].tid=i;
        }
        double t0=now();
        int reps=2;
        for (int r=0;r<reps;r++) {
            for (int i=0;i<th;i++) pthread_create(&tids[i], NULL, worker, &jobs[i]);
            for (int i=0;i<th;i++) pthread_join(tids[i], NULL);
        }
        double t1=now();
        printf("threads %d: %.4f s  %.1f MB/s\n", th, (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));
    }
    return 0;
}
EOF
cc -O3 -I/usr/local/include -L/usr/local/lib -o bench_threads bench_threads.c -lcrypto -lpthread && ./bench_threads"}

