{"command":"cat > pgcm.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>
#include <openssl/evp.h>

#define MAX_THREADS 6

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

/* ---------- GHASH (byte-reflected, standard GCM) ---------- */
typedef struct {
    uint64_t hi, lo;
} u128;

static u128 H;          /* hash subkey, reflected */
static u128 Hpow[MAX_THREADS+1]; /* H^1 .. not used directly */

static inline u128 xor128(u128 a, u128 b) {
    u128 r = {a.hi ^ b.hi, a.lo ^ b.lo};
    return r;
}

/* multiply in GF(2^128) with reflected representation (GCM) */
static u128 gmul(u128 x, u128 y) {
    u128 z = {0, 0};
    u128 v = y;
    /* process x bits from MSB of reflected? 
       In the reflected representation used by many impls (Intel whitepaper):
       multiplication is done bit by bit from the low bit.
       We'll use the standard non-reflected algorithm on unreflected values instead.
    */
    (void)x; (void)v; (void)z;
    return z;
}

/* Non-reflected GHASH multiply: treat blocks as big-endian 128-bit, 
   reduction polynomial x^128 + x^7 + x^2 + x + 1. */
static void mul_block(const uint8_t x[16], const uint8_t y[16], uint8_t out[16]) {
    uint8_t z[16] = {0};
    uint8_t v[16];
    memcpy(v, y, 16);
    for (int i = 0; i < 16; i++) {
        uint8_t xb = x[i];
        for (int bit = 7; bit >= 0; bit--) {
            if (xb & (1 << bit)) {
                for (int k = 0; k < 16; k++) z[k] ^= v[k];
            }
            /* v = v >> 1, if lsb then xor R */
            int lsb = v[15] & 1;
            for (int k = 15; k > 0; k--) v[k] = (v[k] >> 1) | (v[k-1] << 7);
            v[0] >>= 1;
            if (lsb) v[0] ^= 0xe1;
        }
    }
    memcpy(out, z, 16);
}

static void xor_block(uint8_t *a, const uint8_t *b) {
    for (int i = 0; i < 16; i++) a[i] ^= b[i];
}

/* GHASH over an array of blocks, starting from Xi (in/out). */
static void ghash_blocks(uint8_t Xi[16], const uint8_t *data, size_t nblocks, const uint8_t H[16]) {
    for (size_t i = 0; i < nblocks; i++) {
        xor_block(Xi, data + 16*i);
        uint8_t tmp[16];
        mul_block(Xi, H, tmp);
        memcpy(Xi, tmp, 16);
    }
}

/* ---------- parallel CTR via EVP ---------- */
typedef struct {
    const unsigned char *pt;
    unsigned char *ct;
    size_t start;   /* byte offset, multiple of 16 */
    size_t len;
    const unsigned char *key;
    int keylen;
    unsigned char iv[16]; /* 16-byte counter block J0+start/16 */
    unsigned char partial_hash[16]; /* GHASH of this chunk = (C1*H^n + ... + Cn*H) */
    const unsigned char *H;
} task_t;

static void *worker(void *arg) {
    task_t *t = arg;
    /* Encrypt with AES-CTR starting at counter = iv (16 bytes).
       Use EVP AES-CTR. */
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    const EVP_CIPHER *ciph = t->keylen==16 ? EVP_aes_128_ctr() :
                             t->keylen==24 ? EVP_aes_192_ctr() : EVP_aes_256_ctr();
    int outl=0;
    EVP_EncryptInit_ex(ctx, ciph, NULL, t->key, t->iv);
    EVP_EncryptUpdate(ctx, t->ct + t->start, &outl, t->pt + t->start, (int)t->len);
    int outl2=0;
    EVP_EncryptFinal_ex(ctx, t->ct + t->start + outl, &outl2);
    EVP_CIPHER_CTX_free(ctx);

    /* GHASH this chunk (must be multiple of 16) */
    memset(t->partial_hash, 0, 16);
    ghash_blocks(t->partial_hash, t->ct + t->start, t->len/16, t->H);
    return NULL;
}

static void compute_H(const unsigned char *key, int keylen, unsigned char H[16]) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    const EVP_CIPHER *ciph = keylen==16 ? EVP_aes_128_ecb() :
                             keylen==24 ? EVP_aes_192_ecb() : EVP_aes_256_ecb();
    unsigned char zero[16] = {0};
    int outl=0;
    EVP_EncryptInit_ex(ctx, ciph, NULL, key, NULL);
    EVP_CIPHER_CTX_set_padding(ctx, 0);
    EVP_EncryptUpdate(ctx, H, &outl, zero, 16);
    EVP_CIPHER_CTX_free(ctx);
}

/* J0 for 96-bit IV: IV || 0x00000001 */
static void make_j0(const unsigned char *iv, int ivlen, unsigned char J0[16]) {
    if (ivlen == 12) {
        memcpy(J0, iv, 12);
        J0[12]=0; J0[13]=0; J0[14]=0; J0[15]=1;
    } else {
        fprintf(stderr, "only 12-byte iv supported in this bench\n");
        exit(1);
    }
}

static void inc32(unsigned char ctr[16], uint32_t add) {
    uint32_t c = ((uint32_t)ctr[12]<<24)|((uint32_t)ctr[13]<<16)|((uint32_t)ctr[14]<<8)|ctr[15];
    c += add;
    ctr[12]=c>>24; ctr[13]=c>>16; ctr[14]=c>>8; ctr[15]=c;
}

static void gcm_encrypt_parallel(const unsigned char *key, int keylen,
                                 const unsigned char *iv, int ivlen,
                                 const unsigned char *aad, int aadlen,
                                 const unsigned char *pt, unsigned char *ct, size_t n,
                                 unsigned char tag[16], int nthreads) {
    unsigned char H[16];
    compute_H(key, keylen, H);
    unsigned char J0[16];
    make_j0(iv, ivlen, J0);

    /* split plaintext into nthreads chunks, each multiple of 16 (last may have tail handled by thread 0? 
       for bench n is multiple of 16). */
    size_t blocks = n / 16;
    size_t tail = n % 16;

    task_t tasks[MAX_THREADS];
    pthread_t tids[MAX_THREADS];
    size_t blocks_per = blocks / nthreads;
    size_t bstart = 0;
    int actual = nthreads;
    for (int i = 0; i < nthreads; i++) {
        size_t bcount = (i == nthreads-1) ? (blocks - bstart) : blocks_per;
        tasks[i].pt = pt;
        tasks[i].ct = ct;
        tasks[i].start = bstart * 16;
        tasks[i].len = bcount * 16;
        tasks[i].key = key;
        tasks[i].keylen = keylen;
        memcpy(tasks[i].iv, J0, 16);
        inc32(tasks[i].iv, (uint32_t)(bstart + 1)); /* counter for first block of chunk: J0+1+bstart */
        tasks[i].H = H;
        bstart += bcount;
    }
    for (int i = 0; i < actual; i++) pthread_create(&tids[i], NULL, worker, &tasks[i]);
    for (int i = 0; i < actual; i++) pthread_join(tids[i], NULL);

    /* handle tail with single-thread CTR if any (skip for bench) */
    (void)tail;

    /* Combine partial hashes.
       partial_i = GHASH(Ci) = C_i1*H^{ni} + ... + C_ini*H
       Total GHASH(C) = p0 * H^{n1+...} + p1 * H^{n2+...} + ... 
       = (...((p0 * H^{n1}) xor p1) * H^{n2} xor p2) ...
       Wait: p0 = C01*H^{n0} + ... + C0n0*H
       We need p0 * H^{rest} where rest = total_blocks - n0.
       Yes: Xi = (...((p0 * H^{n1}) xor p1) * H^{n2} ...) 
    */
    /* Precompute H^{n_i} for each subsequent chunk length — slow if done naively.
       For correctness test, do it naively with repeated mul (only for small test). */
    uint8_t Xi[16] = {0};
    /* AAD GHASH first */
    if (aadlen) {
        /* pad aad to 16 */
        size_t alen = (aadlen + 15) & ~15;
        uint8_t *abuf = calloc(1, alen);
        memcpy(abuf, aad, aadlen);
        ghash_blocks(Xi, abuf, alen/16, H);
        free(abuf);
    }
    for (int i = 0; i < actual; i++) {
        size_t ni = tasks[i].len / 16;
        if (ni == 0) continue;
        /* Xi = (Xi xor partial_i) then multiply by H^{blocks_after_i}? 
           Let's redo.
           Standard sequential: after chunk i, Xi_i = (Xi_{i-1} * H^{ni}) xor partial_i? 
           partial_i = C1*H^{ni} + C2*H^{ni-1} + ... + Cni*H
           Sequential GHASH of chunk given incoming Xi:
             Xi' = (...((Xi * H xor C1) * H xor C2) ... ) * H xor Cni) * H
                 = Xi * H^{ni} xor (C1*H^{ni} + ... + Cni*H)
                 = Xi * H^{ni} xor partial_i
           Yes. */
        /* multiply Xi by H^{ni} */
        for (size_t k = 0; k < ni; k++) {
            uint8_t tmp[16];
            mul_block(Xi, H, tmp);
            memcpy(Xi, tmp, 16);
        }
        xor_block(Xi, tasks[i].partial_hash);
    }

    /* lengths block */
    uint8_t lenblock[16] = {0};
    uint64_t aad_bits = (uint64_t)aadlen * 8;
    uint64_t pt_bits = (uint64_t)n * 8;
    for (int i = 0; i < 8; i++) lenblock[i] = (aad_bits >> (56-8*i)) & 0xff;
    for (int i = 0; i < 8; i++) lenblock[8+i] = (pt_bits >> (56-8*i)) & 0xff;
    xor_block(Xi, lenblock);
    uint8_t tmp[16];
    mul_block(Xi, H, tmp);
    memcpy(Xi, tmp, 16);

    /* tag = Xi xor E(K, J0) */
    unsigned char EKJ0[16];
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    const EVP_CIPHER *ciph = keylen==16 ? EVP_aes_128_ecb() :
                             keylen==24 ? EVP_aes_192_ecb() : EVP_aes_256_ecb();
    int outl=0;
    EVP_EncryptInit_ex(ctx, ciph, NULL, key, NULL);
    EVP_CIPHER_CTX_set_padding(ctx, 0);
    EVP_EncryptUpdate(ctx, EKJ0, &outl, J0, 16);
    EVP_CIPHER_CTX_free(ctx);
    for (int i = 0; i < 16; i++) tag[i] = Xi[i] ^ EKJ0[i];
}

static int ref_encrypt(const unsigned char *key, int keylen,
                       const unsigned char *iv, int ivlen,
                       const unsigned char *aad, int aadlen,
                       const unsigned char *pt, unsigned char *ct, size_t n,
                       unsigned char tag[16]) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    const EVP_CIPHER *ciph = keylen==16 ? EVP_aes_128_gcm() :
                             keylen==24 ? EVP_aes_192_gcm() : EVP_aes_256_gcm();
    EVP_EncryptInit_ex(ctx, ciph, NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, ivlen, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
    int outl=0;
    if (aad && aadlen) EVP_EncryptUpdate(ctx, NULL, &outl, aad, aadlen);
    EVP_EncryptUpdate(ctx, ct, &outl, pt, (int)n);
    int outl2=0;
    EVP_EncryptFinal_ex(ctx, ct+outl, &outl2);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    EVP_CIPHER_CTX_free(ctx);
    return 1;
}

int main() {
    /* correctness on small */
    unsigned char key[16], iv[12], aad[32], tag1[16], tag2[16];
    memset(key, 0x11, 16); memset(iv, 0x22, 12); memset(aad, 0x33, 32);
    size_t n = 64;
    unsigned char *pt = malloc(n), *ct1 = malloc(n), *ct2 = malloc(n);
    for (size_t i=0;i<n;i++) pt[i]=i;
    ref_encrypt(key,16,iv,12,aad,32,pt,ct1,n,tag1);
    gcm_encrypt_parallel(key,16,iv,12,aad,32,pt,ct2,n,tag2,2);
    printf("small ct match %d tag match %d\n", memcmp(ct1,ct2,n)==0, memcmp(tag1,tag2,16)==0);
    if (memcmp(ct1,ct2,n)) {
        printf("ct1 "); for(int i=0;i<32;i++) printf("%02x",ct1[i]); printf("\n");
        printf("ct2 "); for(int i=0;i<32;i++) printf("%02x",ct2[i]); printf("\n");
    }
    if (memcmp(tag1,tag2,16)) {
        printf("tag1 "); for(int i=0;i<16;i++) printf("%02x",tag1[i]); printf("\n");
        printf("tag2 "); for(int i=0;i<16;i++) printf("%02x",tag2[i]); printf("\n");
    }

    /* also no aad, larger multiple */
    n = 4096;
    pt=realloc(pt,n); ct1=realloc(ct1,n); ct2=realloc(ct2,n);
    memset(pt, 0x5a, n);
    ref_encrypt(key,16,iv,12,NULL,0,pt,ct1,n,tag1);
    gcm_encrypt_parallel(key,16,iv,12,NULL,0,pt,ct2,n,tag2,4);
    printf("4k ct match %d tag match %d\n", memcmp(ct1,ct2,n)==0, memcmp(tag1,tag2,16)==0);

    /* throughput: skip slow ghash, time only CTR parallel vs full ref on 8MB to keep runtime down,
       and time our full function too (ghash will dominate). */
    n = 2*1024*1024;
    pt=realloc(pt,n); ct1=realloc(ct1,n); ct2=realloc(ct2,n);
    double t0=now();
    ref_encrypt(key,16,iv,12,aad,32,pt,ct1,n,tag1);
    double t1=now();
    printf("ref 2MB: %.4f s %.1f MB/s\n", t1-t0, (n/1e6)/(t1-t0));
    t0=now();
    gcm_encrypt_parallel(key,16,iv,12,aad,32,pt,ct2,n,tag2,4);
    t1=now();
    printf("par 2MB: %.4f s %.1f MB/s match ct %d tag %d\n", t1-t0, (n/1e6)/(t1-t0),
           memcmp(ct1,ct2,n)==0, memcmp(tag1,tag2,16)==0);
    return 0;
}
