#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>
#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/modes.h>

extern void gcm_ghash_avx(unsigned char *Xi, const unsigned char *Htable, const unsigned char *in, size_t len);

#define MAX_THREADS 4

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

typedef struct {
    const unsigned char *pt;
    unsigned char *ct;
    size_t start, len;
    const unsigned char *key;
    int keylen;
    unsigned char iv[16];
    unsigned char Xi[16];
    const unsigned char *Htable;
} task_t;

static const EVP_CIPHER *ctr_cipher(int keylen) {
    if (keylen == 16) return EVP_aes_128_ctr();
    if (keylen == 24) return EVP_aes_192_ctr();
    return EVP_aes_256_ctr();
}
static const EVP_CIPHER *gcm_cipher(int keylen) {
    if (keylen == 16) return EVP_aes_128_gcm();
    if (keylen == 24) return EVP_aes_192_gcm();
    return EVP_aes_256_gcm();
}
static const EVP_CIPHER *ecb_cipher(int keylen) {
    if (keylen == 16) return EVP_aes_128_ecb();
    if (keylen == 24) return EVP_aes_192_ecb();
    return EVP_aes_256_ecb();
}

static void *worker(void *arg) {
    task_t *t = arg;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outl = 0, outl2 = 0;
    EVP_EncryptInit_ex(ctx, ctr_cipher(t->keylen), NULL, t->key, t->iv);
    EVP_EncryptUpdate(ctx, t->ct + t->start, &outl, t->pt + t->start, (int)t->len);
    EVP_EncryptFinal_ex(ctx, t->ct + t->start + outl, &outl2);
    EVP_CIPHER_CTX_free(ctx);
    memset(t->Xi, 0, 16);
    if (t->len)
        gcm_ghash_avx(t->Xi, t->Htable, t->ct + t->start, t->len);
    return NULL;
}

static void xor16(unsigned char *a, const unsigned char *b) {
    for (int i = 0; i < 16; i++) a[i] ^= b[i];
}

/* Xi = Xi * H^k, using ghash over k blocks: [Xi, 0, 0, ...] */
static void mul_H_pow(unsigned char Xi[16], const unsigned char *Htable, size_t k) {
    if (k == 0) return;
    /* For large k, do it in chunks of zeros to avoid huge alloc: 
       process using a reusable zero buffer. */
    static unsigned char zeros[4096] = {0};
    unsigned char first[16];
    memcpy(first, Xi, 16);
    /* first block is Xi, then k-1 zeros */
    size_t done = 0;
    /* We need exactly k blocks. Feed first separately by ghash of a 16-byte block = Xi,
       which multiplies by H once, then ghash zeros for the rest. */
    gcm_ghash_avx(Xi, Htable, first, 16); /* now Xi_old * H, and Xi buffer was used as both — WAIT.
       ghash reads Xi then xors with input. Input is a copy of old Xi, so result = (oldXi xor oldXi)*H = 0. BUG. */
    (void)done; (void)zeros;
}

/* Correct: GHASH starting from 0 over the block sequence [Xi_old, 0, 0, ..., 0] (k blocks)
   equals Xi_old * H^k. */
static void mul_H_pow_correct(unsigned char Xi[16], const unsigned char *Htable, size_t k) {
    if (k == 0) return;
    unsigned char acc[16] = {0};
    unsigned char blk[16];
    memcpy(blk, Xi, 16);
    gcm_ghash_avx(acc, Htable, blk, 16); /* acc = Xi * H */
    k -= 1;
    static unsigned char zeros[1 << 16] = {0};
    while (k) {
        size_t nb = k > (sizeof(zeros)/16) ? (sizeof(zeros)/16) : k;
        gcm_ghash_avx(acc, Htable, zeros, nb * 16);
        k -= nb;
    }
    memcpy(Xi, acc, 16);
}

static void inc32(unsigned char ctr[16], uint32_t add) {
    uint32_t c = ((uint32_t)ctr[12] << 24) | ((uint32_t)ctr[13] << 16) |
                 ((uint32_t)ctr[14] << 8) | ctr[15];
    c += add;
    ctr[12] = c >> 24; ctr[13] = c >> 16; ctr[14] = c >> 8; ctr[15] = c;
}

static void ecb_encrypt_block(const unsigned char *key, int keylen, const unsigned char in[16], unsigned char out[16]) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outl = 0;
    EVP_EncryptInit_ex(ctx, ecb_cipher(keylen), NULL, key, NULL);
    EVP_CIPHER_CTX_set_padding(ctx, 0);
    EVP_EncryptUpdate(ctx, out, &outl, in, 16);
    EVP_CIPHER_CTX_free(ctx);
}

/* Build Htable by letting OpenSSL's CRYPTO_gcm128_init do it (uses AES_encrypt, fine for one block). */
static void build_htable(const unsigned char *key, int keylen, unsigned char Htable[256], unsigned char H_out[16]) {
    AES_KEY aes;
    AES_set_encrypt_key(key, keylen * 8, &aes);
    GCM128_CONTEXT *g = CRYPTO_gcm128_new(&aes, (block128_f)AES_encrypt);
    unsigned char *raw = (unsigned char *)g;
    memcpy(Htable, raw + 0x60, 256);
    /* H in standard byte order is bswap of the two u64s at 0x50 */
    unsigned char *hb = raw + 0x50;
    for (int i = 0; i < 8; i++) { H_out[i] = hb[7 - i]; H_out[8 + i] = hb[15 - i]; }
    CRYPTO_gcm128_release(g);
}

static int gcm_parallel(const unsigned char *key, int keylen,
                        const unsigned char *iv, int ivlen,
                        const unsigned char *aad, int aadlen,
                        const unsigned char *pt, unsigned char *ct, size_t n,
                        unsigned char tag[16], int nthreads) {
    if (ivlen != 12) return 0;
    unsigned char Htable[256], H[16];
    build_htable(key, keylen, Htable, H);

    unsigned char J0[16];
    memcpy(J0, iv, 12);
    J0[12] = 0; J0[13] = 0; J0[14] = 0; J0[15] = 1;

    size_t blocks = n / 16;
    size_t tail = n % 16;

    if (nthreads < 1) nthreads = 1;
    if (nthreads > MAX_THREADS) nthreads = MAX_THREADS;
    if ((size_t)nthreads > blocks && blocks > 0) nthreads = (int)blocks;
    if (blocks == 0) nthreads = 1;

    task_t tasks[MAX_THREADS];
    pthread_t tids[MAX_THREADS];
    size_t bstart = 0;
    size_t per = blocks / nthreads;
    for (int i = 0; i < nthreads; i++) {
        size_t bc = (i == nthreads - 1) ? (blocks - bstart) : per;
        tasks[i].pt = pt; tasks[i].ct = ct;
        tasks[i].start = bstart * 16;
        tasks[i].len = bc * 16;
        tasks[i].key = key; tasks[i].keylen = keylen;
        memcpy(tasks[i].iv, J0, 16);
        inc32(tasks[i].iv, (uint32_t)(bstart + 1));
        tasks[i].Htable = Htable;
        bstart += bc;
    }
    for (int i = 0; i < nthreads; i++) pthread_create(&tids[i], NULL, worker, &tasks[i]);
    for (int i = 0; i < nthreads; i++) pthread_join(tids[i], NULL);

    /* tail */
    if (tail) {
        unsigned char ctr[16];
        memcpy(ctr, J0, 16);
        inc32(ctr, (uint32_t)(blocks + 1));
        unsigned char ks[16];
        ecb_encrypt_block(key, keylen, ctr, ks);
        for (size_t i = 0; i < tail; i++) ct[blocks * 16 + i] = pt[blocks * 16 + i] ^ ks[i];
    }

    /* GHASH combine */
    unsigned char Xi[16] = {0};
    if (aad && aadlen) {
        size_t alen = (aadlen + 15) & ~15u;
        unsigned char *abuf = calloc(1, alen ? alen : 1);
        memcpy(abuf, aad, aadlen);
        gcm_ghash_avx(Xi, Htable, abuf, alen);
        free(abuf);
    }
    for (int i = 0; i < nthreads; i++) {
        size_t ni = tasks[i].len / 16;
        if (ni == 0) continue;
        /* Xi = Xi * H^{ni} xor partial_i */
        if (Xi[0]|Xi[1]|Xi[2]|Xi[3]|Xi[4]|Xi[5]|Xi[6]|Xi[7]|Xi[8]|Xi[9]|Xi[10]|Xi[11]|Xi[12]|Xi[13]|Xi[14]|Xi[15])
            mul_H_pow_correct(Xi, Htable, ni);
        else
            memset(Xi, 0, 16);
        xor16(Xi, tasks[i].Xi);
    }
    if (tail) {
        unsigned char last[16] = {0};
        memcpy(last, ct + blocks * 16, tail);
        gcm_ghash_avx(Xi, Htable, last, 16);
    }
    unsigned char lenblock[16] = {0};
    uint64_t aad_bits = (uint64_t)aadlen * 8;
    uint64_t pt_bits = (uint64_t)n * 8;
    for (int i = 0; i < 8; i++) lenblock[i] = (aad_bits >> (56 - 8 * i)) & 0xff;
    for (int i = 0; i < 8; i++) lenblock[8 + i] = (pt_bits >> (56 - 8 * i)) & 0xff;
    gcm_ghash_avx(Xi, Htable, lenblock, 16);

    unsigned char EK[16];
    ecb_encrypt_block(key, keylen, J0, EK);
    for (int i = 0; i < 16; i++) tag[i] = Xi[i] ^ EK[i];
    return 1;
}

static int ref_encrypt(const unsigned char *key, int keylen, const unsigned char *iv, int ivlen,
                       const unsigned char *aad, int aadlen, const unsigned char *pt,
                       unsigned char *ct, size_t n, unsigned char tag[16]) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, gcm_cipher(keylen), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, ivlen, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
    int outl = 0, outl2 = 0;
    if (aad && aadlen) EVP_EncryptUpdate(ctx, NULL, &outl, aad, aadlen);
    EVP_EncryptUpdate(ctx, ct, &outl, pt, (int)n);
    EVP_EncryptFinal_ex(ctx, ct + outl, &outl2);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    EVP_CIPHER_CTX_free(ctx);
    return 1;
}

int main() {
    unsigned char key[16], iv[12], aad[32], tag1[16], tag2[16];
    memset(key, 0x11, 16); memset(iv, 0x22, 12); memset(aad, 0x33, 32);

    for (size_t n : (size_t[]){0, 1, 15, 16, 17, 31, 32, 64, 1000, 4096, 100000}) {
        unsigned char *pt = (unsigned char*)malloc(n ? n : 1);
        unsigned char *c1 = (unsigned char*)malloc(n ? n : 1);
        unsigned char *c2 = (unsigned char*)malloc(n ? n : 1);
        for (size_t i = 0; i < n; i++) pt[i] = (unsigned char)(i * 7 + 3);
        ref_encrypt(key, 16, iv, 12, aad, 32, pt, c1, n, tag1);
        gcm_parallel(key, 16, iv, 12, aad, 32, pt, c2, n, tag2, 4);
        int ok = (n == 0 || memcmp(c1, c2, n) == 0) && memcmp(tag1, tag2, 16) == 0;
        printf("n=%zu %s\n", n, ok ? "OK" : "FAIL");
        if (!ok && n <= 64) {
            printf(" tag1 "); for (int i=0;i<16;i++) printf("%02x", tag1[i]);
            printf("\n tag2 "); for (int i=0;i<16;i++) printf("%02x", tag2[i]); printf("\n");
        }
        /* no aad */
        ref_encrypt(key, 16, iv, 12, NULL, 0, pt, c1, n, tag1);
        gcm_parallel(key, 16, iv, 12, NULL, 0, pt, c2, n, tag2, 3);
        ok = (n == 0 || memcmp(c1, c2, n) == 0) && memcmp(tag1, tag2, 16) == 0;
        printf("n=%zu noaad %s\n", n, ok ? "OK" : "FAIL");
        free(pt); free(c1); free(c2);
    }

    size_t n = 60 * 1024 * 1024;
    unsigned char *pt = (unsigned char*)malloc(n);
    unsigned char *c1 = (unsigned char*)malloc(n);
    unsigned char *c2 = (unsigned char*)malloc(n);
    memset(pt, 0x5a, n);
    /* warmup */
    gcm_parallel(key, 16, iv, 12, aad, 32, pt, c2, n, tag2, 4);
    double t0 = now();
    int reps = 3;
    for (int i = 0; i < reps; i++)
        gcm_parallel(key, 16, iv, 12, aad, 32, pt, c2, n, tag2, 4);
    double t1 = now();
    printf("parallel 60MB: %.4f s  %.1f MB/s\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));
    t0 = now();
    for (int i = 0; i < reps; i++)
        ref_encrypt(key, 16, iv, 12, aad, 32, pt, c1, n, tag1);
    t1 = now();
    printf("ref 60MB: %.4f s  %.1f MB/s  match %d\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps),
           memcmp(c1, c2, n)==0 && memcmp(tag1, tag2, 16)==0);
    return 0;
}
EOF
