#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdatomic.h>
#include <openssl/aes.h>

extern void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out,
                                       size_t blocks, const void *key, const unsigned char ivec[16]);
extern void gcm_ghash_avx(unsigned char *Xi, const unsigned char *Htable, const unsigned char *in, size_t len);

#define NTH 4

typedef struct {
    const unsigned char *in;
    unsigned char *out;
    size_t blocks;
    const void *key;
    unsigned char iv[16];
    unsigned char *Htable;
    unsigned char Xi[16];
    int do_ghash;
    atomic_int *go;       /* epoch to run */
    atomic_int *done;     /* count of finished workers */
    atomic_int *stop;
    int tid;
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    int seen = 0;
    while (!atomic_load(j->stop)) {
        int g = atomic_load(j->go);
        if (g == seen) { continue; } /* spin */
        seen = g;
        aesni_ctr32_encrypt_blocks(j->in, j->out, j->blocks, j->key, j->iv);
        if (j->do_ghash) {
            memset(j->Xi, 0, 16);
            gcm_ghash_avx(j->Xi, j->Htable, j->out, j->blocks * 16);
        }
        atomic_fetch_add(j->done, 1);
    }
    return NULL;
}

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}
static void inc32(unsigned char ctr[16], uint32_t add) {
    uint32_t c = ((uint32_t)ctr[12]<<24)|((uint32_t)ctr[13]<<16)|((uint32_t)ctr[14]<<8)|ctr[15];
    c += add;
    ctr[12]=c>>24; ctr[13]=c>>16; ctr[14]=c>>8; ctr[15]=c;
}

int main() {
    size_t n = 60*1024*1024;
    size_t blocks = n/16;
    unsigned char *pt = malloc(n), *ct = malloc(n);
    memset(pt, 1, n);
    unsigned char keyb[16]; memset(keyb, 0x11, 16);
    AES_KEY key; AES_set_encrypt_key(keyb, 128, &key);
    unsigned char Htable[256]; memset(Htable, 1, 256);
    unsigned char J0[16]; memset(J0, 2, 16);

    atomic_int go = 0, done = 0, stop = 0;
    job_t jobs[NTH];
    pthread_t tids[NTH];
    size_t per = blocks / NTH;
    for (int i=0;i<NTH;i++) {
        jobs[i].in = pt + i*per*16;
        jobs[i].out = ct + i*per*16;
        jobs[i].blocks = (i==NTH-1)?(blocks - i*per):per;
        jobs[i].key = &key;
        memcpy(jobs[i].iv, J0, 16);
        inc32(jobs[i].iv, (uint32_t)(i*per));
        jobs[i].Htable = Htable;
        jobs[i].do_ghash = 1;
        jobs[i].go = &go; jobs[i].done = &done; jobs[i].stop = &stop;
        jobs[i].tid = i;
        pthread_create(&tids[i], NULL, worker, &jobs[i]);
    }
    /* warmup */
    atomic_store(&done, 0);
    atomic_store(&go, 1);
    while (atomic_load(&done) < NTH) {}

    int reps = 5;
    double t0 = now();
    for (int r = 0; r < reps; r++) {
        atomic_store(&done, 0);
        atomic_store(&go, r+2);
        while (atomic_load(&done) < NTH) {}
    }
    double t1 = now();
    printf("pool CTR+ghash x%d: %.4f s %.1f MB/s\n", NTH, (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));

    for (int i=0;i<NTH;i++) jobs[i].do_ghash = 0;
    t0 = now();
    int base = atomic_load(&go);
    for (int r = 0; r < reps; r++) {
        atomic_store(&done, 0);
        atomic_store(&go, base + 1 + r);
        while (atomic_load(&done) < NTH) {}
    }
    t1 = now();
    printf("pool CTR only x%d: %.4f s %.1f MB/s\n", NTH, (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));

    /* single thread reference */
    t0 = now();
    for (int r=0;r<reps;r++) aesni_ctr32_encrypt_blocks(pt, ct, blocks, &key, J0);
    t1 = now();
    printf("single CTR: %.4f s %.1f MB/s\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps));

    atomic_store(&stop, 1);
    atomic_store(&go, 100000);
    for (int i=0;i<NTH;i++) pthread_join(tids[i], NULL);
    return 0;
}
