static atomic_int g_go = 0, g_done = 0, g_stop = 0;
static int g_pool_ready = 0;
static pthread_once_t g_once = PTHREAD_ONCE_INIT;

static void *worker_main(void *arg) {
    worker_t *w = (worker_t *)arg;
    int seen = 0;
    while (!atomic_load_explicit(w->stop, memory_order_acquire)) {
        int g = atomic_load_explicit(w->go, memory_order_acquire);
        if (g == seen) {
            continue;
        }
        seen = g;
        if (w->blocks) {
            aesni_ctr32_encrypt_blocks(w->in, w->out, w->blocks, w->key, w->iv);
            memset(w->Xi, 0, 16);
            gcm_ghash_avx(w->Xi, w->Htable, w->out, w->blocks * 16);
        } else {
            memset(w->Xi, 0, 16);
        }
        atomic_fetch_add_explicit(w->done, 1, memory_order_release);
    }
    return NULL;
}

static void init_pool(void) {
    for (int i = 0; i < NTH; i++) {
        g_workers[i].go = &g_go;
        g_workers[i].done = &g_done;
        g_workers[i].stop = &g_stop;
        g_workers[i].epoch_seen = 0;
        pthread_create(&g_threads[i], NULL, worker_main, &g_workers[i]);
    }
    g_pool_ready = 1;
}

static void inc32(unsigned char ctr[16], uint32_t add) {
    uint32_t c = ((uint32_t)ctr[12] << 24) | ((uint32_t)ctr[13] << 16) |
                 ((uint32_t)ctr[14] << 8) | ctr[15];
    c += add;
    ctr[12] = (unsigned char)(c >> 24);
    ctr[13] = (unsigned char)(c >> 16);
    ctr[14] = (unsigned char)(c >> 8);
    ctr[15] = (unsigned char)c;
}

static void xor16(unsigned char *a, const unsigned char *b) {
    uint64_t *aa = (uint64_t *)a;
    const uint64_t *bb = (const uint64_t *)b;
    aa[0] ^= bb[0];
    aa[1] ^= bb[1];
}

/* Xi <- Xi * H^k   (k >= 1). GHASH(Xi || 0^{k-1}) = Xi * H^k. */
static void mul_pow(unsigned char Xi[16], const unsigned char *Htable, size_t k) {
    unsigned char acc[16] = {0};
    unsigned char first[16];
    memcpy(first, Xi, 16);
    gcm_ghash_avx(acc, Htable, first, 16);
    k -= 1;
    if (k) {
        /* zero pages, reused */
        static unsigned char zeros[65536] = {0};
        while (k) {
            size_t nb = k > (sizeof(zeros) / 16) ? (sizeof(zeros) / 16) : k;
            gcm_ghash_avx(acc, Htable, zeros, nb * 16);
            k -= nb;
        }
    }
    memcpy(Xi, acc, 16);
}

static int ghash_nonzero(const unsigned char Xi[16]) {
    const uint64_t *p = (const uint64_t *)Xi;
    return (p[0] | p[1]) != 0;
}

/*
 * Encrypt pt[0..n) under AES-GCM. keylen is 16/24/32. ivlen must be 12.
 * Writes ciphertext to ct (n bytes) and 16-byte tag.
 * Returns 0 on success, -1 if iv length unsupported.
 */
int fast_gcm_encrypt(const unsigned char *key, int keylen,
                     const unsigned char *iv, int ivlen,
                     const unsigned char *aad, int aadlen,
                     const unsigned char *pt, unsigned char *ct, size_t n,
                     unsigned char tag[16]) {
    if (ivlen != 12 || (keylen != 16 && keylen != 24 && keylen != 32))
        return -1;

    pthread_once(&g_once, init_pool);

    AES_KEY aes;
    if (AES_set_encrypt_key(key, keylen * 8, &aes) != 0)
        return -1;

    /* Htable from OpenSSL's own init so it matches gcm_ghash_avx's layout. */
    unsigned char htable_buf[HTABLE_BYTES + 64];
    GCM128_CONTEXT *gctx = CRYPTO_gcm128_new(&aes, (block128_f)AES_encrypt);
    if (!gctx) return -1;
    memcpy(htable_buf, (unsigned char *)gctx + 0x60, HTABLE_BYTES);
    CRYPTO_gcm128_release(gctx);
    unsigned char *Htable = htable_buf;

    unsigned char J0[16];
    memcpy(J0, iv, 12);
    J0[12] = 0; J0[13] = 0; J0[14] = 0; J0[15] = 1;

    size_t blocks = n / 16;
    size_t tail = n % 16;

    int nth = NTH;
    if ((size_t)nth > blocks) nth = (int)blocks;
    if (nth < 1) nth = 1;

    size_t per = blocks / nth;
    size_t bstart = 0;
    for (int i = 0; i < NTH; i++) {
        worker_t *w = &g_workers[i];
        if (i < nth && blocks) {
            size_t bc = (i == nth - 1) ? (blocks - bstart) : per;
            w->in = pt + bstart * 16;
            w->out = ct + bstart * 16;
            w->blocks = bc;
            w->key = &aes;
            memcpy(w->iv, J0, 16);
            inc32(w->iv, (uint32_t)(bstart + 1)); /* first counter is J0+1 */
            w->Htable = Htable;
            bstart += bc;
        } else {
            w->blocks = 0;
            w->in = pt;
            w->out = ct;
            w->key = &aes;
            w->Htable = Htable;
        }
    }

    atomic_store_explicit(&g_done, 0, memory_order_relaxed);
    atomic_fetch_add_explicit(&g_go, 1, memory_order_release);
    while (atomic_load_explicit(&g_done, memory_order_acquire) < NTH) {
    }

    if (tail) {
        unsigned char ctr[16], ks[16];
        memcpy(ctr, J0, 16);
        inc32(ctr, (uint32_t)(blocks + 1));
        aesni_encrypt(ctr, ks, &aes);
        for (size_t i = 0; i < tail; i++)
            ct[blocks * 16 + i] = pt[blocks * 16 + i] ^ ks[i];
    }

    /* Combine partial GHASH values.
       partial_i = C_i1*H^{ni} + ... + C_ini*H
       sequential: Xi = Xi * H^{ni} xor partial_i
    */
    unsigned char Xi[16] = {0};
    if (aad && aadlen > 0) {
        size_t full = (size_t)aadlen & ~(size_t)15;
        size_t rem = (size_t)aadlen & 15;
        if (full)
            gcm_ghash_avx(Xi, Htable, aad, full);
        if (rem) {
            unsigned char last[16] = {0};
            memcpy(last, aad + full, rem);
            gcm_ghash_avx(Xi, Htable, last, 16);
        }
    }
    for (int i = 0; i < nth; i++) {
        size_t ni = g_workers[i].blocks;
        if (!ni) continue;
        if (ghash_nonzero(Xi))
            mul_pow(Xi, Htable, ni);
        xor16(Xi, g_workers[i].Xi);
    }
    if (tail) {
        unsigned char last[16] = {0};
        memcpy(last, ct + blocks * 16, tail);
        gcm_ghash_avx(Xi, Htable, last, 16);
    }
    unsigned char lenblock[16] = {0};
    uint64_t aad_bits = (uint64_t)(aadlen < 0 ? 0 : aadlen) * 8;
    uint64_t pt_bits = (uint64_t)n * 8;
    for (int i = 0; i < 8; i++) {
        lenblock[i] = (unsigned char)(aad_bits >> (56 - 8 * i));
        lenblock[8 + i] = (unsigned char)(pt_bits >> (56 - 8 * i));
    }
    gcm_ghash_avx(Xi, Htable, lenblock, 16);

    unsigned char EK[16];
    aesni_encrypt(J0, EK, &aes);
    for (int i = 0; i < 16; i++)
        tag[i] = Xi[i] ^ EK[i];
    return 0;
}
