static void poly1305_init(poly1305_ctx *st, const uint8_t key[32]) {
    uint32_t t0 = load32(key+0), t1 = load32(key+4), t2 = load32(key+8), t3 = load32(key+12);
    st->r[0] = t0 & 0x3ffffff; t0 >>= 26; t0 |= t1 << 6;
    st->r[1] = t0 & 0x3ffff03; t1 >>= 20; t1 |= t2 << 12;
    st->r[2] = t1 & 0x3ffc0ff; t2 >>= 14; t2 |= t3 << 18;
    st->r[3] = t2 & 0x3f03fff; t3 >>= 8;
    st->r[4] = t3 & 0x00fffff;
    st->h[0]=st->h[1]=st->h[2]=st->h[3]=st->h[4]=0;
    st->pad[0]=load32(key+16); st->pad[1]=load32(key+20);
    st->pad[2]=load32(key+24); st->pad[3]=load32(key+28);
