#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

/* declarations of openssl internals */
void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned char key[32], const unsigned char nonce[16], uint32_t counter);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);
size_t Poly1305_ctx_size(void);

#define CHUNK (1<<20)  /* 1 MiB */

typedef struct {
    unsigned char *out;
    const unsigned char *in;
    size_t len;
    const unsigned char *key;
    unsigned char nonce[16];
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    ChaCha20_ctr32(j->out, j->in, j->len, j->key, j->nonce, 0);
    return NULL;
}

/* Encrypt pt -> ct (buffers may not alias), write 16-byte tag.
   nonce12 is 12 bytes. */
int aead_encrypt(unsigned char *ct, unsigned char tag[16],
                 const unsigned char key[32], const unsigned char nonce12[12],
                 const unsigned char *pt, size_t pt_len,
                 const unsigned char *aad, size_t aad_len,
                 void *poly_ctx, unsigned char *block0) {
    unsigned char nonce[16];
    memset(nonce, 0, 4);
    memcpy(nonce+4, nonce12, 12);
    unsigned char zero[64] = {0};
    ChaCha20_ctr32(block0, zero, 64, key, nonce, 0);

    Poly1305_Init(poly_ctx, block0);
    if (aad_len) {
        Poly1305_Update(poly_ctx, aad, aad_len);
        size_t p = (16 - (aad_len & 15)) & 15;
        if (p) {
            unsigned char z[16] = {0};
            Poly1305_Update(poly_ctx, z, p);
        }
    }

    if (pt_len) {
        /* pipeline: chacha chunk i+1 in a thread while poly hashes chunk i */
        size_t off = 0;
        size_t clen = pt_len < CHUNK ? pt_len : CHUNK;
        uint32_t counter = 1;
        nonce[0] = (unsigned char)counter;
        nonce[1] = (unsigned char)(counter >> 8);
        nonce[2] = (unsigned char)(counter >> 16);
        nonce[3] = (unsigned char)(counter >> 24);
        ChaCha20_ctr32(ct, pt, clen, key, nonce, 0);

        while (off < pt_len) {
            size_t cur = pt_len - off < CHUNK ? pt_len - off : CHUNK;
            size_t next = off + cur;
            pthread_t th;
            job_t job;
            int spawned = 0;
            if (next < pt_len) {
                size_t nlen = pt_len - next < CHUNK ? pt_len - next : CHUNK;
                uint32_t nc = counter + (uint32_t)(cur / 64);
                job.out = ct + next;
                job.in = pt + next;
                job.len = nlen;
                job.key = key;
                memcpy(job.nonce, nonce, 16);
                job.nonce[0] = (unsigned char)nc;
                job.nonce[1] = (unsigned char)(nc >> 8);
                job.nonce[2] = (unsigned char)(nc >> 16);
                job.nonce[3] = (unsigned char)(nc >> 24);
                if (pthread_create(&th, NULL, worker, &job) == 0) spawned = 1;
                else ChaCha20_ctr32(job.out, job.in, job.len, key, job.nonce, 0);
            }
            Poly1305_Update(poly_ctx, ct + off, cur);
            if (spawned) pthread_join(th, NULL);
            off = next;
            counter += (uint32_t)(cur / 64);
        }
        size_t p = (16 - (pt_len & 15)) & 15;
        if (p) {
            unsigned char z[16] = {0};
            Poly1305_Update(poly_ctx, z, p);
        }
    }
    unsigned char lens[16];
    uint64_t al = aad_len, pl = pt_len;
    memcpy(lens, &al, 8);
    memcpy(lens+8, &pl, 8);
    Poly1305_Update(poly_ctx, lens, 16);
    Poly1305_Final(poly_ctx, tag);
    return 1;
}

int main() {
    size_t N = 40ull<<20;
    unsigned char *pt = malloc(N), *ct = malloc(N);
    memset(pt, 1, N);
    unsigned char key[32]={0}, nonce[12]={0}, tag[16];
    for (int i=0;i<32;i++) key[i]=i+1;
    size_t cs = Poly1305_ctx_size();
    void *pctx = malloc(cs+64);
    unsigned char block0[64];
    unsigned char aad[32]; memset(aad, 2, 32);
    aead_encrypt(ct, tag, key, nonce, pt, N, aad, 32, pctx, block0);
    int iters=5;
    clock_t t0=clock();
    for(int i=0;i<iters;i++) aead_encrypt(ct, tag, key, nonce, pt, N, aad, 32, pctx, block0);
    double dt=(double)(clock()-t0)/CLOCKS_PER_SEC/iters;
    printf("cpu time %.4f (not wall)\n", dt);
    /* wall */
    struct timespec a,b;
    clock_gettime(CLOCK_MONOTONIC, &a);
    for(int i=0;i<iters;i++) aead_encrypt(ct, tag, key, nonce, pt, N, aad, 32, pctx, block0);
    clock_gettime(CLOCK_MONOTONIC, &b);
    double w = (b.tv_sec-a.tv_sec) + (b.tv_nsec-a.tv_nsec)/1e9;
    printf("wall %.4f s  %.1f MB/s\n", w/iters, (N/(w/iters))/1e6);
    return 0;
}
