{"command":"cat > ccbuild/aead2.c << 'EOF'
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned char key[32], const unsigned char nonce[16], uint32_t counter);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);
size_t Poly1305_ctx_size(void);

static size_t CHUNK = 1<<20;

typedef struct {
    unsigned char *out;
    const unsigned char *in;
    size_t len;
    const unsigned char *key;
    unsigned char nonce[16];
    int done;
    pthread_mutex_t mu;
    pthread_cond_t cv;
} slot_t;

static void *worker(void *arg) {
    slot_t *s = arg;
    for (;;) {
        pthread_mutex_lock(&s->mu);
        while (!s->done && s->len == 0) pthread_cond_wait(&s->cv, &s->mu);
        if (s->done) { pthread_mutex_unlock(&s->mu); break; }
        unsigned char *out = s->out; const unsigned char *in = s->in; size_t len=s->len;
        unsigned char nonce[16]; memcpy(nonce, s->nonce, 16);
        const unsigned char *key = s->key;
        s->len = 0;
        pthread_mutex_unlock(&s->mu);
        ChaCha20_ctr32(out, in, len, key, nonce, 0);
        pthread_mutex_lock(&s->mu);
        s->out = NULL; /* signal complete: out==NULL && len==0 */
        pthread_cond_signal(&s->cv);
        pthread_mutex_unlock(&s->mu);
    }
    return NULL;
}

int main() {
    size_t N = 40ull<<20;
    unsigned char *pt = malloc(N), *ct = malloc(N);
    memset(pt, 1, N);
    unsigned char key[32]={1}, nonce12[12]={2}, aad[32]; memset(aad,3,32);
    size_t cs = Poly1305_ctx_size();
    void *pctx = malloc(cs+64);
    unsigned char block0[64], tag[16], zero[64]={0};

    slot_t slot;
    memset(&slot, 0, sizeof(slot));
    pthread_mutex_init(&slot.mu, NULL);
    pthread_cond_init(&slot.cv, NULL);
    pthread_t th;
    pthread_create(&th, NULL, worker, &slot);

    size_t chunks[] = {256<<10, 512<<10, 1<<20, 2<<20, 4<<20, 8<<20};
    for (int ci=0; ci<6; ci++) {
        CHUNK = chunks[ci];
        int iters=4;
        struct timespec a,b;
        clock_gettime(CLOCK_MONOTONIC,&a);
        for (int it=0; it<iters; it++) {
            unsigned char nonce[16]={0};
            memcpy(nonce+4, nonce12, 12);
            ChaCha20_ctr32(block0, zero, 64, key, nonce, 0);
            Poly1305_Init(pctx, block0);
            Poly1305_Update(pctx, aad, 32);
            size_t off=0; uint32_t counter=1;
            /* kick first chunk on worker */
            size_t clen = N<CHUNK?N:CHUNK;
            nonce[0]=1;
            pthread_mutex_lock(&slot.mu);
            slot.out=ct; slot.in=pt; slot.len=clen; slot.key=key; memcpy(slot.nonce, nonce, 16);
            pthread_cond_signal(&slot.cv);
            pthread_mutex_unlock(&slot.mu);
            while (off < N) {
                /* wait until worker finished current (slot.out==NULL) */
                pthread_mutex_lock(&slot.mu);
                while (slot.out != NULL) pthread_cond_wait(&slot.cv, &slot.mu);
                pthread_mutex_unlock(&slot.mu);
                size_t cur = N-off<CHUNK?N-off:CHUNK;
                size_t next = off+cur;
                if (next < N) {
                    size_t nlen = N-next<CHUNK?N-next:CHUNK;
                    uint32_t nc = counter + (uint32_t)(cur/64);
                    unsigned char nn[16]; memcpy(nn, nonce, 16);
                    nn[0]=nc; nn[1]=nc>>8; nn[2]=nc>>16; nn[3]=nc>>24;
                    pthread_mutex_lock(&slot.mu);
                    slot.out=ct+next; slot.in=pt+next; slot.len=nlen; slot.key=key; memcpy(slot.nonce, nn, 16);
                    pthread_cond_signal(&slot.cv);
                    pthread_mutex_unlock(&slot.mu);
                }
                Poly1305_Update(pctx, ct+off, cur);
                off=next; counter += (uint32_t)(cur/64);
            }
            unsigned char lens[16]; uint64_t al=32, pl=N;
            memcpy(lens,&al,8); memcpy(lens+8,&pl,8);
            Poly1305_Update(pctx, lens, 16);
            Poly1305_Final(pctx, tag);
        }
        clock_gettime(CLOCK_MONOTONIC,&b);
        double w=(b.tv_sec-a.tv_sec)+(b.tv_nsec-a.tv_nsec)/1e9;
        printf("chunk %6zu KB  wall/iter %.4f s  %.1f MB/s\n", CHUNK>>10, w/iters, (N/(w/iters))/1e6);
    }
    pthread_mutex_lock(&slot.mu); slot.done=1; pthread_cond_signal(&slot.cv); pthread_mutex_unlock(&slot.mu);
    pthread_join(th, NULL);
    return 0;
}
