/* Parallel ChaCha20 + overlapped Poly1305 AEAD (RFC 8439).
 * ChaCha20_ctr32 / Poly1305_* come from libcrypto.
 */
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <pthread.h>
#include <stdlib.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned char key[32], const unsigned char nonce[16], uint32_t counter);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);
size_t Poly1305_ctx_size(void);

#define MAX_THREADS 8

typedef struct {
    unsigned char *out;
    const unsigned char *in;
    size_t off;
    size_t len;
    const unsigned char *key;
    unsigned char nonce[16];
    int ready;          /* set by worker when encryption of this chunk is done */
    pthread_mutex_t mu;
    pthread_cond_t cv;
} chunk_t;

static void *worker(void *arg) {
    chunk_t *c = arg;
    ChaCha20_ctr32(c->out + c->off, c->in + c->off, c->len, c->key, c->nonce, 0);
    pthread_mutex_lock(&c->mu);
    c->ready = 1;
    pthread_cond_signal(&c->cv);
    pthread_mutex_unlock(&c->mu);
    return NULL;
}

/* ct must have pt_len bytes. tag 16 bytes. */
void fast_aead_encrypt(
    unsigned char *ct, unsigned char tag[16],
    const unsigned char key[32], const unsigned char nonce12[12],
    const unsigned char *pt, size_t pt_len,
    const unsigned char *aad, size_t aad_len,
    void *poly_ctx, unsigned char block0[64],
    int nthreads)
{
    unsigned char nonce[16];
    memset(nonce, 0, 4);
    memcpy(nonce + 4, nonce12, 12);
    unsigned char zero[64] = {0};
    ChaCha20_ctr32(block0, zero, 64, key, nonce, 0);

    Poly1305_Init(poly_ctx, block0);
    if (aad && aad_len) {
        Poly1305_Update(poly_ctx, aad, aad_len);
        size_t p = (16 - (aad_len & 15)) & 15;
        if (p) {
            unsigned char z[16] = {0};
            Poly1305_Update(poly_ctx, z, p);
        }
    }

    if (pt_len) {
        if (nthreads < 1) nthreads = 1;
        if (nthreads > MAX_THREADS) nthreads = MAX_THREADS;
        /* split into nthreads chunks, 64-byte aligned except last */
        size_t chunk = (pt_len / nthreads) & ~(size_t)63;
        if (chunk == 0) {
            nthreads = 1;
            chunk = pt_len;
        }
        chunk_t chunks[MAX_THREADS];
        pthread_t th[MAX_THREADS];
        int spawned = 0;
        size_t off = 0;
        for (int t = 0; t < nthreads; t++) {
            size_t len = (t == nthreads - 1) ? (pt_len - off) : chunk;
            chunk_t *c = &chunks[t];
            c->out = ct; c->in = pt; c->off = off; c->len = len; c->key = key;
            memcpy(c->nonce, nonce, 16);
            uint32_t ctr = 1u + (uint32_t)(off / 64);
            c->nonce[0] = (unsigned char)ctr;
            c->nonce[1] = (unsigned char)(ctr >> 8);
            c->nonce[2] = (unsigned char)(ctr >> 16);
            c->nonce[3] = (unsigned char)(ctr >> 24);
            c->ready = 0;
            pthread_mutex_init(&c->mu, NULL);
            pthread_cond_init(&c->cv, NULL);
            if (pthread_create(&th[t], NULL, worker, c) == 0) {
                spawned++;
            } else {
                ChaCha20_ctr32(ct + off, pt + off, len, key, c->nonce, 0);
                c->ready = 1;
            }
            off += len;
        }
        /* hash chunks in order as they complete */
        for (int t = 0; t < nthreads; t++) {
            chunk_t *c = &chunks[t];
            pthread_mutex_lock(&c->mu);
            while (!c->ready) pthread_cond_wait(&c->cv, &c->mu);
            pthread_mutex_unlock(&c->mu);
            Poly1305_Update(poly_ctx, ct + c->off, c->len);
        }
        for (int t = 0; t < nthreads; t++) {
            if (chunks[t].ready) pthread_join(th[t], NULL);
            pthread_mutex_destroy(&chunks[t].mu);
            pthread_cond_destroy(&chunks[t].cv);
        }
        size_t p = (16 - (pt_len & 15)) & 15;
        if (p) {
            unsigned char z[16] = {0};
            Poly1305_Update(poly_ctx, z, p);
        }
    }

    unsigned char lens[16];
    uint64_t al = (uint64_t)aad_len, pl = (uint64_t)pt_len;
    memcpy(lens, &al, 8);
    memcpy(lens + 8, &pl, 8);
    Poly1305_Update(poly_ctx, lens, 16);
    Poly1305_Final(poly_ctx, tag);
}

#ifdef BENCH
#include <time.h>
int main() {
    size_t N = 40ull << 20;
    unsigned char *pt = malloc(N), *ct = malloc(N);
    memset(pt, 1, N);
    unsigned char key[32], nonce[12], tag[16], aad[32], block0[64];
    for (int i = 0; i < 32; i++) key[i] = i + 1;
    for (int i = 0; i < 12; i++) nonce[i] = i + 3;
    memset(aad, 9, 32);
    size_t cs = Poly1305_ctx_size();
    void *pctx = malloc(cs + 64);
    for (int T = 1; T <= 8; T *= 2) {
        int iters = 4;
        struct timespec a, b;
        clock_gettime(CLOCK_MONOTONIC, &a);
        for (int i = 0; i < iters; i++)
            fast_aead_encrypt(ct, tag, key, nonce, pt, N, aad, 32, pctx, block0, T);
        clock_gettime(CLOCK_MONOTONIC, &b);
        double w = (b.tv_sec - a.tv_sec) + (b.tv_nsec - a.tv_nsec) / 1e9;
        printf("T=%d %.4f s %.1f MB/s\n", T, w / iters, (N / (w / iters)) / 1e6);
    }
    return 0;
}
#endif
