#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned char key[32], const unsigned char nonce[16], uint32_t counter);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);
size_t Poly1305_ctx_size(void);

#define T 6

typedef struct {
    unsigned char *out;
    const unsigned char *in;
    size_t off, len;
    const unsigned char *key;
    unsigned char nonce[16];
    int go, done, quit;
    pthread_mutex_t mu;
    pthread_cond_t cv_go, cv_done;
} worker_t;

static worker_t W[T];

static void *loop(void *arg) {
    worker_t *w = arg;
    for (;;) {
        pthread_mutex_lock(&w->mu);
        while (!w->go && !w->quit) pthread_cond_wait(&w->cv_go, &w->mu);
        if (w->quit) { pthread_mutex_unlock(&w->mu); break; }
        unsigned char *out=w->out; const unsigned char *in=w->in;
        size_t off=w->off, len=w->len; const unsigned char *key=w->key;
        unsigned char nonce[16]; memcpy(nonce, w->nonce, 16);
        w->go = 0;
        pthread_mutex_unlock(&w->mu);
        ChaCha20_ctr32(out+off, in+off, len, key, nonce, 0);
        pthread_mutex_lock(&w->mu);
        w->done = 1;
        pthread_cond_signal(&w->cv_done);
        pthread_mutex_unlock(&w->mu);
    }
    return NULL;
}

static void pool_init(void) {
    static int inited=0;
    if (inited) return;
    for (int i=0;i<T;i++) {
        memset(&W[i], 0, sizeof(W[i]));
        pthread_mutex_init(&W[i].mu, NULL);
        pthread_cond_init(&W[i].cv_go, NULL);
        pthread_cond_init(&W[i].cv_done, NULL);
        pthread_t th; pthread_create(&th, NULL, loop, &W[i]);
        pthread_detach(th);
    }
    inited=1;
}

static void encrypt(unsigned char *ct, unsigned char tag[16],
                    const unsigned char key[32], const unsigned char nonce12[12],
                    const unsigned char *pt, size_t N,
                    const unsigned char *aad, size_t aad_len,
                    void *pctx) {
    pool_init();
    unsigned char nonce[16]={0}; memcpy(nonce+4, nonce12, 12);
    unsigned char block0[64], zero[64]={0};
    ChaCha20_ctr32(block0, zero, 64, key, nonce, 0);
    Poly1305_Init(pctx, block0);
    if (aad_len) Poly1305_Update(pctx, aad, aad_len);
    size_t chunk = (N / T) & ~(size_t)63;
    size_t off=0;
    for (int i=0;i<T;i++) {
        size_t len = (i==T-1)? N-off : chunk;
        worker_t *w=&W[i];
        pthread_mutex_lock(&w->mu);
        w->out=ct; w->in=pt; w->off=off; w->len=len; w->key=key;
        uint32_t ctr = 1u + (uint32_t)(off/64);
        memcpy(w->nonce, nonce, 16);
        w->nonce[0]=ctr; w->nonce[1]=ctr>>8; w->nonce[2]=ctr>>16; w->nonce[3]=ctr>>24;
        w->done=0; w->go=1;
        pthread_cond_signal(&w->cv_go);
        pthread_mutex_unlock(&w->mu);
        off += len;
    }
    for (int i=0;i<T;i++) {
        worker_t *w=&W[i];
        pthread_mutex_lock(&w->mu);
        while (!w->done) pthread_cond_wait(&w->cv_done, &w->mu);
        pthread_mutex_unlock(&w->mu);
        Poly1305_Update(pctx, ct + w->off, w->len);
    }
    unsigned char lens[16];
    uint64_t al=aad_len, pl=N;
    memcpy(lens,&al,8); memcpy(lens+8,&pl,8);
    Poly1305_Update(pctx, lens, 16);
    Poly1305_Final(pctx, tag);
}

int main() {
    size_t N=40ull<<20;
    unsigned char *pt=malloc(N), *ct=malloc(N);
    memset(pt,1,N);
    unsigned char key[32]={1}, nonce[12]={2}, aad[32]={3}, tag[16];
    void *pctx=malloc(Poly1305_ctx_size()+64);
    encrypt(ct, tag, key, nonce, pt, N, aad, 32, pctx); /* warmup */
    int iters=6;
    struct timespec a,b; clock_gettime(CLOCK_MONOTONIC,&a);
    for(int i=0;i<iters;i++) encrypt(ct, tag, key, nonce, pt, N, aad, 32, pctx);
    clock_gettime(CLOCK_MONOTONIC,&b);
    double w=(b.tv_sec-a.tv_sec)+(b.tv_nsec-a.tv_nsec)/1e9;
    printf("pool T=%d %.4f s %.1f MB/s\n", T, w/iters, (N/(w/iters))/1e6);
    return 0;
}
