/* Two-level Poly1305:
 * 1. Split message into T chunks (multiple of 16).
 * 2. Each thread computes Poly1305 state of its chunk with the SAME r (via Poly1305_Update)
 *    but we need the accumulator, not the tag. Poly1305_Final adds pad and reduces.
 *    We cannot extract h from the public API easily.
 *
 * Alternative: use Poly1305 as a black box by hashing chunk_i || zeros to a common length? No, not linear.
 *
 * Poly1305 is polynomial hash: H = m0*r^n + m1*r^(n-1) + ... + mn*r  (mod 2^130-5)
 * If we split into chunks of B blocks:
 *   H = H0 * r^(B*(T-1)) + H1 * r^(B*(T-2)) + ... + H_{T-1}
 * where Hi is the poly hash of chunk i (same as hashing chunk i alone, WITHOUT the final +s and with hibit).
 * Poly1305_Final does: fully reduce h, add s (pad), emit 128 bits.
 * If we set pad s = 0, Final emits the reduced accumulator (low 128) — BUT only if h < 2^128 after reduction,
 * which it is (fully reduced to < 2^130, then compared to 2^130-5, result < 2^128? 
 * 2^130-5 is 130 bits, fully reduced h < 2^130. Adding s=0, the emitted 128 bits may DROP the top 2 bits!
 * So s=0 final does NOT give full accumulator. Can't use black box.
 *
 * Must implement our own fast poly OR read h from ctx memory.
 * Let's dump ctx after Update and see if we can find h.
 */
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);
size_t Poly1305_ctx_size(void);

int main() {
    size_t cs = Poly1305_ctx_size();
    printf("ctx size %zu\n", cs);
    unsigned char *ctx = calloc(1, cs+16);
    unsigned char key[32]={0};
    key[0]=1; /* r = 1, easy */
    /* r must have certain bits clear. r=1 is fine (clamped still 1). */
    Poly1305_Init(ctx, key);
    unsigned char block[16]={0};
    block[0]=1; /* message block = 1, so h should become 1*r = 1 after one block? 
                   actually h = (m + 2^128) * r. With r=1, h = m + 2^128. */
    Poly1305_Update(ctx, block, 16);
    printf("ctx after 1 block:\n");
    for (size_t i=0;i<cs;i++) {
        if (ctx[i]) printf("  off %3zu = %02x\n", i, ctx[i]);
    }
    return 0;
}
EOF
