#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);
size_t Poly1305_ctx_size(void);

/* Experiment: can we feed a synthetic block that equals a chunk's accumulator
   into a fresh poly context to continue? Only if representation matches a message block.
   It doesn't (130-bit vs 128-bit + hibit). So combination must be done on h directly.
   Let's instead verify h is 3x64 at offset 0 by comparing two paths:
   - hash all
   - hash first half, snapshot h (24 bytes), ... we need multiply.
   Skip math; just time parallel independent Poly1305_Update on halves and a serial one,
   to know the parallel poly bandwidth. Combination cost is tiny. */
size_t CS;
unsigned char *buf; size_t N;
unsigned char key[32];

typedef struct { unsigned char *ctx; const unsigned char *p; size_t n; } job;
static void *worker(void *arg) {
    job *j=arg;
    Poly1305_Init(j->ctx, key);
    Poly1305_Update(j->ctx, j->p, j->n);
    return NULL;
}
int main() {
    CS=Poly1305_ctx_size();
    N=40ull<<20;
    buf=malloc(N); memset(buf, 0x5a, N);
    memset(key, 0x11, 32);
    int iters=4;
    /* serial */
    unsigned char *ctx=malloc(CS+64); unsigned char tag[16];
    struct timespec a,b;
    clock_gettime(CLOCK_MONOTONIC,&a);
    for(int i=0;i<iters;i++){ Poly1305_Init(ctx,key); Poly1305_Update(ctx,buf,N); Poly1305_Final(ctx,tag); }
    clock_gettime(CLOCK_MONOTONIC,&b);
    double w=(b.tv_sec-a.tv_sec)+(b.tv_nsec-a.tv_nsec)/1e9;
    printf("serial %.4f s %.1f MB/s\n", w/iters, (N/(w/iters))/1e6);

    for (int T=2; T<=6; T+=2) {
        unsigned char *ctxs[8];
        for(int i=0;i<T;i++) ctxs[i]=malloc(CS+64);
        clock_gettime(CLOCK_MONOTONIC,&a);
        for(int it=0; it<iters; it++) {
            pthread_t th[8]; job jobs[8];
            size_t chunk=(N/T)&~15ull;
            size_t off=0;
            for(int i=0;i<T;i++){
                size_t len=(i==T-1)?N-off:chunk;
                jobs[i]=(job){ctxs[i], buf+off, len};
                pthread_create(&th[i], NULL, worker, &jobs[i]);
                off+=len;
            }
            for(int i=0;i<T;i++) pthread_join(th[i], NULL);
        }
        clock_gettime(CLOCK_MONOTONIC,&b);
        w=(b.tv_sec-a.tv_sec)+(b.tv_nsec-a.tv_nsec)/1e9;
        printf("T=%d %.4f s %.1f MB/s\n", T, w/iters, (N/(w/iters))/1e6);
    }
    return 0;
}
