/* clean version */
static H mulmod2(H h, uint64_t r0, uint64_t r1) {
    unsigned __int128 p00 = (unsigned __int128)h.h0 * r0;
    unsigned __int128 p01 = (unsigned __int128)h.h0 * r1;
    unsigned __int128 p10 = (unsigned __int128)h.h1 * r0;
    unsigned __int128 p11 = (unsigned __int128)h.h1 * r1;
    unsigned __int128 p20 = (unsigned __int128)h.h2 * r0;
    unsigned __int128 p21 = (unsigned __int128)h.h2 * r1;

    uint64_t z0 = (uint64_t)p00;
    unsigned __int128 t = (p00 >> 64) + (uint64_t)p01 + (uint64_t)p10;
    uint64_t z1 = (uint64_t)t;
    t = (t >> 64) + (p01 >> 64) + (p10 >> 64) + p11 + p20;
    uint64_t z2 = (uint64_t)t;
    t = (t >> 64) + (p11 >> 64) + (p20 >> 64) + p21;
    uint64_t z3 = (uint64_t)t;
    uint64_t z4 = (uint64_t)(t >> 64);

    /* add (z2>>2)*5 + z3*5*2^62 + z4*5*2^126 to low 128, keep z2&3 as bit128 */
    unsigned __int128 red = (unsigned __int128)(z2 >> 2) * 5u;
    red += ((unsigned __int128)z3 * 5u) << 62;
    red += ((unsigned __int128)z4 * 5u) << 126;

    unsigned __int128 s0 = (unsigned __int128)z0 + (uint64_t)red;
    uint64_t o0 = (uint64_t)s0;
    unsigned __int128 s1 = (unsigned __int128)z1 + (red >> 64) + (s0 >> 64);
    uint64_t o1 = (uint64_t)s1;
    unsigned __int128 s2 = (unsigned __int128)(z2 & 3) + (s1 >> 64);
    uint64_t o2 = (uint64_t)s2;

