        o2 &= 3;
        unsigned __int128 ss = (unsigned __int128)o0 + f;
        o0 = (uint64_t)ss;
        unsigned __int128 ss1 = (unsigned __int128)o1 + (ss >> 64);
        o1 = (uint64_t)ss1;
        o2 += (uint64_t)(ss1 >> 64);
    }
    return (H){o0, o1, o2};
