static H add_block(H h, const unsigned char m[16], uint64_t r0, uint64_t r1) {
    uint64_t m0, m1; memcpy(&m0, m, 8); memcpy(&m1, m+8, 8);
    unsigned __int128 s = (unsigned __int128)h.h0 + m0;
    h.h0 = (uint64_t)s;
