#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
size_t Poly1305_ctx_size(void);

typedef struct { uint64_t h0,h1,h2; } H;

/* h * r mod (2^130-5), h = h0+h1*2^64+h2*2^128, r = r0+r1*2^64
   Follow openssl scalar reduction exactly:
     mask = t2 & ~3; t2 &= 3; t0 += mask + (mask>>2)
   i.e. add (t2 & ~3) * 5/4 = (t2>>2)*5, and (t2 & ~3) is t2 with low 2 bits cleared,
   which equals (t2>>2)<<2, times... let's just emulate the asm:
     rax = -4; rax &= t2;   # rax = t2 & ~3
     t2 >>= 2; rbp = t2_orig & 3
     rax += t2;             # (t2 & ~3) + (t2 >> 2) = (t2>>2)*4 + (t2>>2) = (t2>>2)*5
     h0 += rax
*/
static H mul(H h, uint64_t r0, uint64_t r1) {
    /* 5*r1 for the h2 term? In asm: r13 = r1 + (r1>>2) = r1*5/4? 
       r13 = r1>>2; r13 = r13 + r1 = r1*5/4. Then imul r13, h2. 
       That's (5/4)*r1 * h2, and h2 is the 2^128 limb. 
       (5/4)*r1 * h2 * 2^64? Let's not reverse from asm; do straightforward 130-bit reduction
       and compare. */
    unsigned __int128 p0 = (unsigned __int128)h.h0 * r0;          /* <<0 */
    unsigned __int128 p1 = (unsigned __int128)h.h0 * r1 + (unsigned __int128)h.h1 * r0; /* <<64 */
    unsigned __int128 p2 = (unsigned __int128)h.h1 * r1 + (unsigned __int128)h.h2 * r0; /* <<128 */
    unsigned __int128 p3 = (unsigned __int128)h.h2 * r1;          /* <<192 */

    uint64_t z0 = (uint64_t)p0;
    unsigned __int128 c = (p0>>64) + (uint64_t)p1;
    uint64_t z1 = (uint64_t)c;
    c = (c>>64) + (p1>>64) + (uint64_t)p2;
    uint64_t z2 = (uint64_t)c; /* <<128 */
    c = (c>>64) + (p2>>64) + (uint64_t)p3;
    uint64_t z3 = (uint64_t)c; /* <<192 */
    uint64_t z4 = (uint64_t)((p3>>64) + (c>>64));

    /* Reduce: bits >=130.
       number = z0 + z1*2^64 + (z2&3)*2^128 + (z2>>2)*2^130 + z3*2^192 + z4*2^256
       ≡ z0 + z1*2^64 + (z2&3)*2^128 + 5*(z2>>2) + 5*z3*2^62 + 5*z4*2^126
    */
    unsigned __int128 red = (unsigned __int128)(z2>>2) * 5u;
    red += ((unsigned __int128)z3 * 5u) << 62;
    red += ((unsigned __int128)z4 * 5u) << 126;
    unsigned __int128 s0 = (unsigned __int128)z0 + (uint64_t)red;
    uint64_t o0 = (uint64_t)s0;
    unsigned __int128 s1 = (unsigned __int128)z1 + (red>>64) + (s0>>64);
    uint64_t o1 = (uint64_t)s1;
    uint64_t o2 = (z2 & 3) + (uint64_t)(s1>>64);
    if (o2 >> 2) {
        uint64_t add = (o2 >> 2) * 5u;
        o2 &= 3;
        unsigned __int128 ss = (unsigned __int128)o0 + add;
        o0 = (uint64_t)ss;
        unsigned __int128 ss1 = (unsigned __int128)o1 + (ss>>64);
        o1 = (uint64_t)ss1;
        o2 += (uint64_t)(ss1>>64);
    }
    return (H){o0,o1,o2};
}

int main() {
    size_t cs=Poly1305_ctx_size();
    unsigned char *ctx=calloc(1,cs);
    unsigned char key[32]; for(int i=0;i<32;i++) key[i]=i*7+1;
    Poly1305_Init(ctx, key);
    uint64_t r0,r1; memcpy(&r0,ctx+24,8); memcpy(&r1,ctx+32,8);
    unsigned char msg[16]; for(int i=0;i<16;i++) msg[i]=i*3+1;
    uint64_t m0,m1; memcpy(&m0,msg,8); memcpy(&m1,msg+8,8);
    H h={m0, m1, 1}; /* (m + 2^128) * r */
    h = mul(h, r0, r1);
    Poly1305_Update(ctx, msg, 16);
