    unsigned __int128 s0=(unsigned __int128)z0+(uint64_t)red; uint64_t o0=(uint64_t)s0;
    unsigned __int128 s1=(unsigned __int128)z1+(red>>64)+(s0>>64); uint64_t o1=(uint64_t)s1;
