/* Fully reduce h into < 2^130 and also into canonical < p, then compare. */
static void reduce(uint64_t *h0, uint64_t *h1, uint64_t *h2) {
    /* fold h2 bits >=2 */
    for (int i=0;i<3 && (*h2>>2); i++) {
        uint64_t add = (*h2>>2)*5u; *h2 &= 3;
        unsigned __int128 s=(unsigned __int128)(*h0)+add; *h0=(uint64_t)s;
        unsigned __int128 s1=(unsigned __int128)(*h1)+(s>>64); *h1=(uint64_t)s1;
        *h2 += (uint64_t)(s1>>64);
    }
}
static int ge_p(uint64_t h0, uint64_t h1, uint64_t h2) {
    /* p = 2^130-5 = 0xfffffffffffffffb + (2^64-1)*2^64 + 3*2^128 */
    if (h2 > 3) return 1;
    if (h2 < 3) return 0;
    if (h1 != ~0ull) return h1 > ~0ull;
    return h0 >= (uint64_t)(0ull-5ull); /* 2^64-5 */
