    uint64_t a1 = (uint64_t)(p_h0r0 >> 64);
    uint64_t b0 = (uint64_t)p_h0r1;
    uint64_t b1 = (uint64_t)(p_h0r1 >> 64);
    uint64_t c0 = (uint64_t)p_h1r0;
    uint64_t c1 = (uint64_t)(p_h1r0 >> 64);
    uint64_t d0 = (uint64_t)p_h1r1;
