    t = (unsigned __int128)cary + b1 + c1 + d0 + e0; uint64_t z2=(uint64_t)t; cary=(uint64_t)(t>>64);
    t = (unsigned __int128)cary + d1 + e1 + f0;    uint64_t z3=(uint64_t)t; cary=(uint64_t)(t>>64);
