void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);
size_t Poly1305_ctx_size(void);

/* 5-limb radix 2^26 representation, done carefully, only for the (tiny) combination step. */
typedef struct { uint32_t l[5]; } L; /* value = sum l[i] * 2^(26*i), each l[i] < 2^32 during calc, reduced to < 2^26 */

static L from_h(uint64_t h0, uint64_t h1, uint64_t h2) {
    /* 130-bit-ish value. h2 should be small (<2^32) for this conversion; fold first. */
    while (h2 >> 2) {
        uint64_t add = (h2 >> 2) * 5u; h2 &= 3;
        unsigned __int128 s = (unsigned __int128)h0 + add; h0 = (uint64_t)s;
        unsigned __int128 s1 = (unsigned __int128)h1 + (s >> 64); h1 = (uint64_t)s1;
        h2 += (uint64_t)(s1 >> 64);
    }
    L r;
    r.l[0] = (uint32_t)(h0 & 0x3ffffff);
    r.l[1] = (uint32_t)((h0 >> 26) & 0x3ffffff);
    r.l[2] = (uint32_t)(((h0 >> 52) | (h1 << 12)) & 0x3ffffff);
    r.l[3] = (uint32_t)((h1 >> 14) & 0x3ffffff);
    r.l[4] = (uint32_t)(((h1 >> 40) | (h2 << 24)) & 0x3ffffff);
    /* h2 bits above 2 go to a 6th limb; we folded so h2<4, and (h1>>40) is 24 bits, plus h2<<24 is bits 24..25. fits in 26. */
    return r;
}
static void to_h(L a, uint64_t *h0, uint64_t *h1, uint64_t *h2) {
    /* reduce limbs to 26 bits */
    uint64_t c;
    c=a.l[0]>>26; a.l[0]&=0x3ffffff; a.l[1]+=(uint32_t)c;
    c=a.l[1]>>26; a.l[1]&=0x3ffffff; a.l[2]+=(uint32_t)c;
    c=a.l[2]>>26; a.l[2]&=0x3ffffff; a.l[3]+=(uint32_t)c;
    c=a.l[3]>>26; a.l[3]&=0x3ffffff; a.l[4]+=(uint32_t)c;
    c=a.l[4]>>26; a.l[4]&=0x3ffffff; a.l[0]+=(uint32_t)c*5;
    c=a.l[0]>>26; a.l[0]&=0x3ffffff; a.l[1]+=(uint32_t)c;
    *h0 = (uint64_t)a.l[0] | ((uint64_t)a.l[1]<<26) | ((uint64_t)a.l[2]<<52);
    *h1 = ((uint64_t)a.l[2]>>12) | ((uint64_t)a.l[3]<<14) | ((uint64_t)a.l[4]<<40);
    *h2 = (uint64_t)a.l[4]>>24;
}

static L mulL(L a, L b) {
    uint64_t a0=a.l[0],a1=a.l[1],a2=a.l[2],a3=a.l[3],a4=a.l[4];
    uint64_t b0=b.l[0],b1=b.l[1],b2=b.l[2],b3=b.l[3],b4=b.l[4];
    uint64_t s1=b1*5, s2=b2*5, s3=b3*5, s4=b4*5;
    uint64_t d0=a0*b0 + a1*s4 + a2*s3 + a3*s2 + a4*s1;
    uint64_t d1=a0*b1 + a1*b0 + a2*s4 + a3*s3 + a4*s2;
    uint64_t d2=a0*b2 + a1*b1 + a2*b0 + a3*s4 + a4*s3;
    uint64_t d3=a0*b3 + a1*b2 + a2*b1 + a3*b0 + a4*s4;
    uint64_t d4=a0*b4 + a1*b3 + a2*b2 + a3*b1 + a4*b0;
    uint64_t c;
    c=d0>>26; d0&=0x3ffffff; d1+=c;
    c=d1>>26; d1&=0x3ffffff; d2+=c;
    c=d2>>26; d2&=0x3ffffff; d3+=c;
    c=d3>>26; d3&=0x3ffffff; d4+=c;
    c=d4>>26; d4&=0x3ffffff; d0+=c*5;
    c=d0>>26; d0&=0x3ffffff; d1+=c;
    L r; r.l[0]=(uint32_t)d0; r.l[1]=(uint32_t)d1; r.l[2]=(uint32_t)d2; r.l[3]=(uint32_t)d3; r.l[4]=(uint32_t)d4;
    return r;
}
static L addL(L a, L b) {
    L r; uint64_t c;
    uint64_t d0=(uint64_t)a.l[0]+b.l[0];
    uint64_t d1=(uint64_t)a.l[1]+b.l[1];
    uint64_t d2=(uint64_t)a.l[2]+b.l[2];
    uint64_t d3=(uint64_t)a.l[3]+b.l[3];
    uint64_t d4=(uint64_t)a.l[4]+b.l[4];
    c=d0>>26; d0&=0x3ffffff; d1+=c;
    c=d1>>26; d1&=0x3ffffff; d2+=c;
    c=d2>>26; d2&=0x3ffffff; d3+=c;
    c=d3>>26; d3&=0x3ffffff; d4+=c;
    c=d4>>26; d4&=0x3ffffff; d0+=c*5;
    c=d0>>26; d0&=0x3ffffff; d1+=c;
    r.l[0]=(uint32_t)d0; r.l[1]=(uint32_t)d1; r.l[2]=(uint32_t)d2; r.l[3]=(uint32_t)d3; r.l[4]=(uint32_t)d4;
    return r;
}
static L powL(L base, uint64_t n) {
    L result={{1,0,0,0,0}};
    while (n) {
        if (n & 1) result = mulL(result, base);
        base = mulL(base, base);
        n >>= 1;
    }
    return result;
}

static int test_split(const unsigned char *msg, size_t N, int T, const unsigned char key[32]) {
    size_t CS=Poly1305_ctx_size();
    unsigned char *full=calloc(1,CS);
    Poly1305_Init(full, key); Poly1305_Update(full, msg, N);
    unsigned char tag1[16]; Poly1305_Final(full, tag1);
    uint64_t r0,r1; memcpy(&r0, full+24, 8); memcpy(&r1, full+32, 8);
    L r = from_h(r0, r1, 0);
    size_t chunk=(N/T)&~(size_t)15;
    L acc={{0,0,0,0,0}};
    L power={{1,0,0,0,0}};
    size_t off=N;
    for (int i=T-1;i>=0;i--) {
        size_t start = (i==0)?0 : (size_t)i*chunk;
        size_t len = off - start;
        unsigned char *ctx=calloc(1,CS);
        Poly1305_Init(ctx, key); Poly1305_Update(ctx, msg+start, len);
        uint64_t h0,h1,h2; memcpy(&h0,ctx,8); memcpy(&h1,ctx+8,8); memcpy(&h2,ctx+16,8);
        L hi=from_h(h0,h1,h2);
        acc = addL(acc, mulL(hi, power));
        power = mulL(power, powL(r, len/16));
        off = start;
        free(ctx);
    }
    uint64_t oh0,oh1,oh2; to_h(acc, &oh0, &oh1, &oh2);
    unsigned char *cx=calloc(1,CS); Poly1305_Init(cx, key);
    memcpy(cx,&oh0,8); memcpy(cx+8,&oh1,8); memcpy(cx+16,&oh2,8);
    unsigned char tag2[16]; Poly1305_Final(cx, tag2);
    int ok=memcmp(tag1, tag2, 16)==0;
    free(full); free(cx);
    return ok;
}

int main() {
    unsigned char key[32]; for(int i=0;i<32;i++) key[i]=i*7+1;
    unsigned char msg[256]; for(int i=0;i<256;i++) msg[i]=i*3+1;
    printf("32/2 %d\n", test_split(msg, 32, 2, key));
    printf("64/2 %d\n", test_split(msg, 64, 2, key));
    printf("64/4 %d\n", test_split(msg, 64, 4, key));
    printf("128/4 %d\n", test_split(msg, 128, 4, key));
    printf("256/3 %d\n", test_split(msg, 240, 3, key));
    size_t N=1<<20; unsigned char *big=malloc(N); memset(big,0x5a,N);
    printf("1MB/4 %d\n", test_split(big, N, 4, key));
    printf("1MB/6 %d\n", test_split(big, N, 6, key));
    /* uneven */
    printf("1008/6 %d\n", test_split(big, 1008, 6, key));
    return 0;
}
EOF
