static inline void mul(uint64_t *h0, uint64_t *h1, uint64_t *h2, uint64_t r0, uint64_t r1) {
    uint64_t hh0=*h0, hh1=*h1, hh2=*h2;
    unsigned __int128 p0=(unsigned __int128)hh0*r0;
    unsigned __int128 p1=(unsigned __int128)hh0*r1+(unsigned __int128)hh1*r0;
    unsigned __int128 p2=(unsigned __int128)hh1*r1+(unsigned __int128)hh2*r0;
    unsigned __int128 p3=(unsigned __int128)hh2*r1;
    uint64_t z0=(uint64_t)p0;
