    c=(c>>64)+(p1>>64)+(uint64_t)p2; uint64_t z2=(uint64_t)c;
    c=(c>>64)+(p2>>64)+(uint64_t)p3; uint64_t z3=(uint64_t)c;
    uint64_t z4=(uint64_t)((p3>>64)+(c>>64));
    unsigned __int128 red=(unsigned __int128)(z2>>2)*5u;
    red+=((unsigned __int128)z3*5u)<<62;
    red+=((unsigned __int128)z4*5u)<<126;
    unsigned __int128 s0=(unsigned __int128)z0+(uint64_t)red;
    unsigned __int128 s1=(unsigned __int128)z1+(red>>64)+(s0>>64);
    uint64_t o2=(z2&3)+(uint64_t)(s1>>64);
    uint64_t o0=(uint64_t)s0, o1=(uint64_t)s1;
    if (o2>>2){ uint64_t add=(o2>>2)*5u; o2&=3;
        unsigned __int128 ss=(unsigned __int128)o0+add; o0=(uint64_t)ss;
        unsigned __int128 ss1=(unsigned __int128)o1+(ss>>64); o1=(uint64_t)ss1; o2+=(uint64_t)(ss1>>64); }
    *h0=o0; *h1=o1; *h2=o2;
}
static void blocks(st *s, const unsigned char *m, size_t nblocks) {
    uint64_t h0=s->h0,h1=s->h1,h2=s->h2,r0=s->r0,r1=s->r1;
    for (size_t i=0;i<nblocks;i++) {
        uint64_t m0,m1; memcpy(&m0,m,8); memcpy(&m1,m+8,8);
        unsigned __int128 a=(unsigned __int128)h0+m0; h0=(uint64_t)a;
        unsigned __int128 b=(unsigned __int128)h1+m1+(a>>64); h1=(uint64_t)b;
        h2+=1+(uint64_t)(b>>64);
        mul(&h0,&h1,&h2,r0,r1);
        m+=16;
    }
    s->h0=h0; s->h1=h1; s->h2=h2;
}
/* emit tag: fully reduce h, add s */
static void finish(st *s, unsigned char tag[16]) {
    uint64_t h0=s->h0,h1=s->h1,h2=s->h2;
    /* fold h2 */
    for(int i=0;i<4 && (h2>>2);i++){
        uint64_t add=(h2>>2)*5u; h2&=3;
        unsigned __int128 a=(unsigned __int128)h0+add; h0=(uint64_t)a;
        unsigned __int128 b=(unsigned __int128)h1+(a>>64); h1=(uint64_t)b; h2+=(uint64_t)(b>>64);
    }
    /* compare with p = 2^130-5 and subtract if >= */
    uint64_t g0=h0+5; uint64_t c=(g0<h0);
    uint64_t g1=h1+c; c=(g1<h1)||(c&&g1==h1);
    /* h2 is 0..3. g2 = h2 + c. if g2>=4, h >= p */
    uint64_t g2=h2+c;
    uint64_t mask = -(uint64_t)(g2>>2); /* all-ones if >= 4 */
    h0 = (h0 & ~mask) | (g0 & mask);
    h1 = (h1 & ~mask) | (g1 & mask);
    /* add pad s */
    unsigned __int128 s0=(unsigned __int128)h0 + s->s0;
    unsigned __int128 s1=(unsigned __int128)h1 + s->s1 + (s0>>64);
    uint64_t o0=(uint64_t)s0, o1=(uint64_t)s1;
    memcpy(tag, &o0, 8); memcpy(tag+8, &o1, 8);
}

int main(){
    size_t N=40ull<<20;
    unsigned char *buf=aligned_alloc(64,N); memset(buf,0x5a,N);
    unsigned char key[32]; for(int i=0;i<32;i++) key[i]=i*7+1;
    st s; init(&s, key); blocks(&s, buf, N/16);
    unsigned char tag[16], tag2[16]; finish(&s, tag);
    size_t CS=Poly1305_ctx_size(); unsigned char *ctx=calloc(1,CS);
    Poly1305_Init(ctx, key); Poly1305_Update(ctx, buf, N); Poly1305_Final(ctx, tag2);
    printf("tag match %d\n", memcmp(tag, tag2, 16)==0);
    printf("mine "); for(int i=0;i<16;i++) printf("%02x", tag[i]); printf("\n");
    printf("ossl "); for(int i=0;i<16;i++) printf("%02x", tag2[i]); printf("\n");

    int iters=3;
    struct timespec a,b; clock_gettime(CLOCK_MONOTONIC,&a);
    for(int i=0;i<iters;i++){ init(&s,key); blocks(&s,buf,N/16); finish(&s,tag); }
    clock_gettime(CLOCK_MONOTONIC,&b);
    double w=(b.tv_sec-a.tv_sec)+(b.tv_nsec-a.tv_nsec)/1e9;
    printf("mine %.4f s %.1f MB/s\n", w/iters, (N/(w/iters))/1e6);
    clock_gettime(CLOCK_MONOTONIC,&a);
    for(int i=0;i<iters;i++){ Poly1305_Init(ctx,key); Poly1305_Update(ctx,buf,N); Poly1305_Final(ctx,tag2); }
    clock_gettime(CLOCK_MONOTONIC,&b);
    w=(b.tv_sec-a.tv_sec)+(b.tv_nsec-a.tv_nsec)/1e9;
    printf("ossl %.4f s %.1f MB/s\n", w/iters, (N/(w/iters))/1e6);
    return 0;
}
