#define MAX_T 8

typedef struct { uint32_t l[5]; } limb_t;

static limb_t from_r(uint64_t r0, uint64_t r1) {
    limb_t r;
    r.l[0] = (uint32_t)(r0 & 0x3ffffff);
    r.l[1] = (uint32_t)((r0 >> 26) & 0x3ffffff);
    r.l[2] = (uint32_t)(((r0 >> 52) | (r1 << 12)) & 0x3ffffff);
    r.l[3] = (uint32_t)((r1 >> 14) & 0x3ffffff);
    r.l[4] = (uint32_t)((r1 >> 40) & 0x3ffffff);
    return r;
}
static limb_t decode_h(const unsigned char *ctx) {
    limb_t r;
    r.l[0] = *(const uint32_t *)(ctx + 0);
    r.l[1] = *(const uint32_t *)(ctx + 4);
    r.l[2] = *(const uint32_t *)(ctx + 8);
    r.l[3] = *(const uint32_t *)(ctx + 12);
    r.l[4] = *(const uint32_t *)(ctx + 16);
    return r;
}
static limb_t mulL(limb_t a, limb_t b) {
    uint64_t a0=a.l[0],a1=a.l[1],a2=a.l[2],a3=a.l[3],a4=a.l[4];
    uint64_t b0=b.l[0],b1=b.l[1],b2=b.l[2],b3=b.l[3],b4=b.l[4];
    uint64_t s1=b1*5,s2=b2*5,s3=b3*5,s4=b4*5;
    uint64_t d0=a0*b0+a1*s4+a2*s3+a3*s2+a4*s1;
    uint64_t d1=a0*b1+a1*b0+a2*s4+a3*s3+a4*s2;
    uint64_t d2=a0*b2+a1*b1+a2*b0+a3*s4+a4*s3;
    uint64_t d3=a0*b3+a1*b2+a2*b1+a3*b0+a4*s4;
    uint64_t d4=a0*b4+a1*b3+a2*b2+a3*b1+a4*b0;
    uint64_t c;
    c=d0>>26; d0&=0x3ffffff; d1+=c;
    c=d1>>26; d1&=0x3ffffff; d2+=c;
    c=d2>>26; d2&=0x3ffffff; d3+=c;
    c=d3>>26; d3&=0x3ffffff; d4+=c;
    c=d4>>26; d4&=0x3ffffff; d0+=c*5;
    c=d0>>26; d0&=0x3ffffff; d1+=c;
    c=d1>>26; d1&=0x3ffffff; d2+=c;
    c=d2>>26; d2&=0x3ffffff; d3+=c;
    c=d3>>26; d3&=0x3ffffff; d4+=c;
    limb_t r; r.l[0]=(uint32_t)d0; r.l[1]=(uint32_t)d1; r.l[2]=(uint32_t)d2; r.l[3]=(uint32_t)d3; r.l[4]=(uint32_t)d4;
    return r;
}
static limb_t addL(limb_t a, limb_t b) {
    uint64_t d0=(uint64_t)a.l[0]+b.l[0], d1=(uint64_t)a.l[1]+b.l[1], d2=(uint64_t)a.l[2]+b.l[2];
    uint64_t d3=(uint64_t)a.l[3]+b.l[3], d4=(uint64_t)a.l[4]+b.l[4], c;
    c=d0>>26; d0&=0x3ffffff; d1+=c;
    c=d1>>26; d1&=0x3ffffff; d2+=c;
    c=d2>>26; d2&=0x3ffffff; d3+=c;
    c=d3>>26; d3&=0x3ffffff; d4+=c;
    c=d4>>26; d4&=0x3ffffff; d0+=c*5;
    c=d0>>26; d0&=0x3ffffff; d1+=c;
    c=d1>>26; d1&=0x3ffffff; d2+=c;
    limb_t r; r.l[0]=(uint32_t)d0; r.l[1]=(uint32_t)d1; r.l[2]=(uint32_t)d2; r.l[3]=(uint32_t)d3; r.l[4]=(uint32_t)d4;
    return r;
}
static limb_t powL(limb_t base, uint64_t n) {
    limb_t result = {{1,0,0,0,0}};
    while (n) {
        if (n & 1) result = mulL(result, base);
        base = mulL(base, base);
        n >>= 1;
    }
    return result;
}
static void limbs_to_h(limb_t a, uint64_t *h0, uint64_t *h1, uint64_t *h2) {
    uint64_t c;
    for (int pass = 0; pass < 3; pass++) {
        c=a.l[0]>>26; a.l[0]&=0x3ffffff; a.l[1]+=(uint32_t)c;
        c=a.l[1]>>26; a.l[1]&=0x3ffffff; a.l[2]+=(uint32_t)c;
        c=a.l[2]>>26; a.l[2]&=0x3ffffff; a.l[3]+=(uint32_t)c;
        c=a.l[3]>>26; a.l[3]&=0x3ffffff; a.l[4]+=(uint32_t)c;
        c=a.l[4]>>26; a.l[4]&=0x3ffffff; a.l[0]+=(uint32_t)c*5;
    }
    *h0 = (uint64_t)a.l[0] | ((uint64_t)a.l[1] << 26) | ((uint64_t)a.l[2] << 52);
    *h1 = ((uint64_t)a.l[2] >> 12) | ((uint64_t)a.l[3] << 14) | ((uint64_t)a.l[4] << 40);
    *h2 = (uint64_t)a.l[4] >> 24;
}

/* ---------- worker pool (persistent) ---------- */
typedef struct {
    int id;
    unsigned char *out;
    const unsigned char *in;
    size_t off, len;
    const unsigned char *key;
    unsigned char nonce[16];
    void *poly_ctx;
    const unsigned char *poly_src;
    size_t poly_len;
    const unsigned char *poly_key;
    atomic_int turn;     /* incremented to dispatch; -1 quits */
    atomic_int seen;
    atomic_int chacha_done;
    atomic_int poly_done;
} worker_t;

static worker_t W[MAX_T];
static int pool_n = 0;

static void *worker_loop(void *arg) {
    worker_t *w = arg;
    int seen = 0;
    for (;;) {
        int t;
        while ((t = atomic_load_explicit(&w->turn, memory_order_acquire)) == seen) ;
        seen = t;
        if (t < 0) break;
        if (w->len)
            ChaCha20_ctr32(w->out + w->off, w->in + w->off, w->len, w->key, w->nonce, 0);
        atomic_store_explicit(&w->chacha_done, 1, memory_order_release);
        if (w->poly_len) {
            Poly1305_Init(w->poly_ctx, w->poly_key);
            Poly1305_Update(w->poly_ctx, w->poly_src, w->poly_len);
        }
        atomic_store_explicit(&w->poly_done, 1, memory_order_release);
    }
    return NULL;
}

static void pool_init(int n, size_t ctx_size) {
    if (pool_n == n) return;
    for (int i = 0; i < n; i++) {
        memset(&W[i], 0, sizeof(W[i]));
        W[i].id = i;
        W[i].poly_ctx = calloc(1, ctx_size + 64);
        atomic_store(&W[i].turn, 0);
        pthread_t th;
        pthread_create(&th, NULL, worker_loop, &W[i]);
        pthread_detach(th);
    }
    pool_n = n;
}

/* Encrypt. ct must hold pt_len bytes. For pt_len >= 2048 uses parallel path. */
void aead_encrypt(unsigned char *ct, unsigned char tag[16],
                  const unsigned char key[32], const unsigned char nonce12[12],
                  const unsigned char *pt, size_t pt_len,
                  const unsigned char *aad, size_t aad_len) {
    unsigned char nonce[16];
    memset(nonce, 0, 4);
    memcpy(nonce + 4, nonce12, 12);
    unsigned char block0[64];
    unsigned char zero[64] = {0};
    ChaCha20_ctr32(block0, zero, 64, key, nonce, 0);

    size_t CS = Poly1305_ctx_size();

    /* small: single threaded */
    if (pt_len < 4096) {
        if (pt_len)
            nonce[0] = 1, ChaCha20_ctr32(ct, pt, pt_len, key, nonce, 0);
        void *ctx = W[0].poly_ctx ? W[0].poly_ctx : calloc(1, CS + 64);
        Poly1305_Init(ctx, block0);
        if (aad_len) {
            Poly1305_Update(ctx, aad, aad_len);
            size_t p = (16 - (aad_len & 15)) & 15;
            if (p) { unsigned char z[16]={0}; Poly1305_Update(ctx, z, p); }
        }
        if (pt_len) {
            Poly1305_Update(ctx, ct, pt_len);
            size_t p = (16 - (pt_len & 15)) & 15;
            if (p) { unsigned char z[16]={0}; Poly1305_Update(ctx, z, p); }
        }
        unsigned char lens[16];
        uint64_t al=aad_len, pl=pt_len;
        memcpy(lens, &al, 8); memcpy(lens+8, &pl, 8);
        Poly1305_Update(ctx, lens, 16);
        Poly1305_Final(ctx, tag);
        return;
    }

    int T = 6;
    pool_init(T, CS);

    /* split ciphertext into T chunks, 64-byte aligned */
    size_t chunk = (pt_len / T) & ~(size_t)63;
    size_t off = 0;
    for (int i = 0; i < T; i++) {
        size_t len = (i == T-1) ? pt_len - off : chunk;
        worker_t *w = &W[i];
        w->out = ct; w->in = pt; w->off = off; w->len = len; w->key = key;
        uint32_t ctr = 1u + (uint32_t)(off / 64);
        memcpy(w->nonce, nonce, 16);
        w->nonce[0]=ctr; w->nonce[1]=ctr>>8; w->nonce[2]=ctr>>16; w->nonce[3]=ctr>>24;
        w->poly_key = block0;
        w->poly_src = ct + off;
        w->poly_len = len;
        atomic_store_explicit(&w->chacha_done, 0, memory_order_relaxed);
        atomic_store_explicit(&w->poly_done, 0, memory_order_relaxed);
        off += len;
    }
    /* dispatch */
    for (int i = 0; i < T; i++)
        atomic_fetch_add_explicit(&W[i].turn, 1, memory_order_release);

    /* meanwhile hash AAD on a local ctx, then wait and combine poly states */
    void *head = calloc(1, CS + 64);
    Poly1305_Init(head, block0);
    if (aad_len) {
        Poly1305_Update(head, aad, aad_len);
        size_t p = (16 - (aad_len & 15)) & 15;
        if (p) { unsigned char z[16]={0}; Poly1305_Update(head, z, p); }
    }

    for (int i = 0; i < T; i++)
        while (!atomic_load_explicit(&W[i].poly_done, memory_order_acquire)) ;

    /* combine chunk poly states */
    uint64_t r0, r1;
    memcpy(&r0, block0, 8); memcpy(&r1, block0+8, 8);
    r0 &= 0x0ffffffc0fffffffULL; r1 &= 0x0ffffffc0ffffffcULL;
    limb_t r = from_r(r0, r1);
    limb_t acc = {{0,0,0,0,0}};
    limb_t power = {{1,0,0,0,0}};
    for (int i = T-1; i >= 0; i--) {
        limb_t hi = decode_h(W[i].poly_ctx);
        acc = addL(acc, mulL(hi, power));
        power = mulL(power, powL(r, W[i].poly_len / 16));
    }
    uint64_t h0,h1,h2; limbs_to_h(acc, &h0, &h1, &h2);

    /* The head ctx holds H(aad||pad). We need H(aad||pad||ct||pad||lens).
       ct length is a multiple of 64, so no ct pad. Append by writing combined h
       is wrong because head already has aad absorbed. Instead: the poly of the
       ciphertext chunks starts fresh (H(ct_chunk)), and aad was hashed separately.
       Correct composition: H_total = H_aad * r^{n_ct_blocks} + H_ct, then *r^1 for the lens block.
       We do that here, then feed the lens block by putting the combined state into a ctx and Updating lens.
    */
    size_t ct_blocks = pt_len / 16;
    limb_t haad = decode_h(head);
    limb_t r_ct = powL(r, ct_blocks);
    limb_t total = addL(mulL(haad, r_ct), acc);
    limbs_to_h(total, &h0, &h1, &h2);

    unsigned char *fin = head;
    /* re-init to restore r, pad, function pointers, then overwrite h */
    Poly1305_Init(fin, block0);
    memcpy(fin, &h0, 8);
    memcpy(fin+8, &h1, 8);
    memcpy(fin+16, &h2, 8);
    unsigned char lens[16];
    uint64_t al=aad_len, pl=pt_len;
    memcpy(lens, &al, 8); memcpy(lens+8, &pl, 8);
    Poly1305_Update(fin, lens, 16);
    Poly1305_Final(fin, tag);
    free(head);
}

#ifdef BENCH
#include <time.h>
int main() {
    size_t N = 40ull<<20;
    unsigned char *pt=malloc(N), *ct=malloc(N);
    memset(pt, 1, N);
    unsigned char key[32], nonce[12], tag[16], aad[32];
    for (int i=0;i<32;i++) key[i]=i+1;
    for (int i=0;i<12;i++) nonce[i]=i+3;
    memset(aad, 9, 32);
    aead_encrypt(ct, tag, key, nonce, pt, N, aad, 32);
    int iters=4;
    struct timespec a,b; clock_gettime(CLOCK_MONOTONIC,&a);
    for(int i=0;i<iters;i++) aead_encrypt(ct, tag, key, nonce, pt, N, aad, 32);
    clock_gettime(CLOCK_MONOTONIC,&b);
    double w=(b.tv_sec-a.tv_sec)+(b.tv_nsec-a.tv_nsec)/1e9;
    printf("%.4f s  %.1f MB/s\n", w/iters, (N/(w/iters))/1e6);
    return 0;
}
#endif
EOF
