#include <Python.h>
#include <numpy/arrayobject.h>
#include <Accelerate/Accelerate.h>
#include <stdlib.h>
#include <string.h>

static int ensure_c_contig_f64(PyObject *obj, PyArrayObject **out) {
    *out = (PyArrayObject *)PyArray_FROM_OTF(obj, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY);
    return *out != NULL;
}

static PyObject *svd_gram(PyObject *self, PyObject *args) {
    PyObject *a_obj;
    if (!PyArg_ParseTuple(args, "O", &a_obj)) return NULL;
    PyArrayObject *A = NULL;
    if (!ensure_c_contig_f64(a_obj, &A)) return NULL;

    npy_intp n = PyArray_DIM(A, 0);
    npy_intp m = PyArray_DIM(A, 1);
    double *Ad = (double *)PyArray_DATA(A);

    int tall = n >= m;
    npy_intp k = tall ? m : n;          /* gram size and number of singular values */
    npy_intp rowsU = n, colsU = k;
    npy_intp rowsV = m, colsV = k;

    npy_intp dimsU[2] = {rowsU, colsU};
    npy_intp dimsV[2] = {rowsV, colsV};
    npy_intp dimsS[1] = {k};

    PyArrayObject *U = (PyArrayObject *)PyArray_EMPTY(2, dimsU, NPY_FLOAT64, 0);
    PyArrayObject *V = (PyArrayObject *)PyArray_EMPTY(2, dimsV, NPY_FLOAT64, 0);
    PyArrayObject *S = (PyArrayObject *)PyArray_EMPTY(1, dimsS, NPY_FLOAT64, 0);
    if (!U || !V || !S) { Py_XDECREF(A); Py_XDECREF(U); Py_XDECREF(V); Py_XDECREF(S); return NULL; }

    double *Ud = (double *)PyArray_DATA(U);
    double *Vd = (double *)PyArray_DATA(V);
    double *Sd = (double *)PyArray_DATA(S);

    /* Gram matrix in column-major (Fortran) order, size k x k */
    double *G = (double *)malloc((size_t)k * (size_t)k * sizeof(double));
    if (!G) { Py_DECREF(A); Py_DECREF(U); Py_DECREF(V); Py_DECREF(S); return PyErr_NoMemory(); }

    /* CBLAS: CblasRowMajor, A is row-major.
       tall: G = A^T A = (m x n) * (n x m) but we want column-major G.
       Easiest: use CblasRowMajor dsyrk into a row-major buffer then the
       symmetric matrix is identical in either layout for the upper/lower
       we pass to LAPACK. We'll compute G row-major and tell dsyevd 'L' or 'U'
       consistently. Since G is symmetric, row-major G equals column-major G^T,
       and G^T = G, so the memory is a valid column-major symmetric matrix.
    */
    if (tall) {
        /* G = A^T * A, row-major: CblasTrans, A is n x m */
        cblas_dsyrk(CblasRowMajor, CblasUpper, CblasTrans,
                    (int)m, (int)n, 1.0, Ad, (int)m, 0.0, G, (int)m);
    } else {
        /* G = A * A^T, row-major: CblasNoTrans, A is n x m */
        cblas_dsyrk(CblasRowMajor, CblasUpper, CblasNoTrans,
                    (int)n, (int)m, 1.0, Ad, (int)m, 0.0, G, (int)n);
    }

    /* workspace query */
    int kk = (int)k;
    int lwork = -1, liwork = -1, info = 0;
    double work_query;
    int iwork_query;
    char jobz = 'V';
    char uplo = 'U';
    dsyevd_(&jobz, &uplo, &kk, G, &kk, Sd, &work_query, &lwork, &iwork_query, &liwork, &info);
    lwork = (int)work_query;
    liwork = iwork_query;
    double *work = (double *)malloc((size_t)lwork * sizeof(double));
    int *iwork = (int *)malloc((size_t)liwork * sizeof(int));
    if (!work || !iwork) {
        free(G); free(work); free(iwork);
        Py_DECREF(A); Py_DECREF(U); Py_DECREF(V); Py_DECREF(S);
        return PyErr_NoMemory();
    }
    dsyevd_(&jobz, &uplo, &kk, G, &kk, Sd, work, &lwork, iwork, &liwork, &info);
    free(work); free(iwork);

    /* G now holds eigenvectors as columns in column-major order, i.e.
       eigenvector j is G[i + j*k], corresponding to eigenvalue Sd[j] (ascending).
       For the row-major interpretation we stored, dsyevd treated memory as
       column-major. Because the matrix was symmetric this is correct, and
       eigenvectors come out column-major.
    */
    for (npy_intp j = 0; j < k; j++) {
        double sj = Sd[j];
        if (sj < 0.0) sj = 0.0;
        Sd[j] = sqrt(sj);
    }

    if (tall) {
        /* V is eigenvectors, column-major k x k. We need row-major (m x k) = (k x k).
           Copy and transpose from col-major to row-major: V[r, c] = G[r + c*k]
           row-major index r*k + c.
        */
        for (npy_intp c = 0; c < k; c++) {
            for (npy_intp r = 0; r < k; r++) {
                Vd[r * k + c] = G[r + c * k];
            }
        }
        /* U = A @ V / s   A is n x m row-major, V is m x k row-major */
        cblas_dgemm(CblasRowMajor, CblasNoTrans, CblasNoTrans,
                    (int)n, (int)k, (int)m,
                    1.0, Ad, (int)m, Vd, (int)k,
                    0.0, Ud, (int)k);
        for (npy_intp c = 0; c < k; c++) {
            double inv = 1.0 / Sd[c];
            for (npy_intp r = 0; r < n; r++) Ud[r * k + c] *= inv;
        }
    } else {
        /* U is eigenvectors k x k, k == n */
        for (npy_intp c = 0; c < k; c++) {
            for (npy_intp r = 0; r < k; r++) {
                Ud[r * k + c] = G[r + c * k];
            }
        }
        /* V = A.T @ U / s. A.T is m x n, U is n x k.
           dgemm: V = A^T * U
        */
        cblas_dgemm(CblasRowMajor, CblasTrans, CblasNoTrans,
                    (int)m, (int)k, (int)n,
                    1.0, Ad, (int)m, Ud, (int)k,
                    0.0, Vd, (int)k);
        for (npy_intp c = 0; c < k; c++) {
            double inv = 1.0 / Sd[c];
            for (npy_intp r = 0; r < m; r++) Vd[r * k + c] *= inv;
        }
    }

    free(G);
    Py_DECREF(A);
    return Py_BuildValue("NNN", U, S, V);
}

static PyMethodDef methods[] = {
    {"svd_gram", svd_gram, METH_VARARGS, "fast gram svd"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "accel_svd", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_accel_svd(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
