#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <Accelerate/Accelerate.h>
#include <stdlib.h>
#include <math.h>

static PyObject *svd_gesdd(PyObject *self, PyObject *args) {
    PyObject *a_obj;
    if (!PyArg_ParseTuple(args, "O", &a_obj)) return NULL;
    PyArrayObject *A = (PyArrayObject *)PyArray_FROM_OTF(a_obj, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY);
    if (!A) return NULL;
    npy_intp n = PyArray_DIM(A, 0);
    npy_intp m = PyArray_DIM(A, 1);
    npy_intp k = n < m ? n : m;
    double *Ad = (double *)PyArray_DATA(A);

    double *AF = (double *)malloc((size_t)n * (size_t)m * sizeof(double));
    for (npy_intp c = 0; c < m; c++)
        for (npy_intp r = 0; r < n; r++)
            AF[r + c * n] = Ad[r * m + c];

    /* Fortran arrays: U (n x k, ld n), VT (k x m, ld k), S (k) */
    npy_intp dimsU[2] = {n, k};
    npy_intp dimsVT[2] = {k, m};
    npy_intp dimsS[1] = {k};
    PyArrayObject *U = (PyArrayObject *)PyArray_EMPTY(2, dimsU, NPY_FLOAT64, 1);
    PyArrayObject *VT = (PyArrayObject *)PyArray_EMPTY(2, dimsVT, NPY_FLOAT64, 1);
    PyArrayObject *S = (PyArrayObject *)PyArray_EMPTY(1, dimsS, NPY_FLOAT64, 0);
    double *Ud = (double *)PyArray_DATA(U);
    double *VTd = (double *)PyArray_DATA(VT);
    double *Sd = (double *)PyArray_DATA(S);

    int nn = (int)n, mm = (int)m, kk = (int)k;
    int lwork = -1, info = 0;
    double work_query;
    int *iwork = (int *)malloc((size_t)(8 * kk) * sizeof(int));
    char jobz = 'S';
    dgesdd_(&jobz, &nn, &mm, AF, &nn, Sd, Ud, &nn, VTd, &kk, &work_query, &lwork, iwork, &info);
    lwork = (int)work_query;
    double *work = (double *)malloc((size_t)lwork * sizeof(double));
    dgesdd_(&jobz, &nn, &mm, AF, &nn, Sd, Ud, &nn, VTd, &kk, work, &lwork, iwork, &info);
    free(work); free(iwork); free(AF);

    /* Convert VT (k x m, col-major) to V (m x k, row-major): V[r,c] = VT[c, r] = VTd[c + r*k] */
    npy_intp dimsV[2] = {m, k};
    PyArrayObject *V = (PyArrayObject *)PyArray_EMPTY(2, dimsV, NPY_FLOAT64, 0);
    double *Vd = (double *)PyArray_DATA(V);
    for (npy_intp r = 0; r < m; r++)
        for (npy_intp c = 0; c < k; c++)
            Vd[r * k + c] = VTd[c + r * k];
    /* U col-major to row-major */
    PyArrayObject *Uc = (PyArrayObject *)PyArray_EMPTY(2, dimsU, NPY_FLOAT64, 0);
    double *Ucd = (double *)PyArray_DATA(Uc);
    for (npy_intp r = 0; r < n; r++)
        for (npy_intp c = 0; c < k; c++)
            Ucd[r * k + c] = Ud[r + c * n];

    Py_DECREF(A); Py_DECREF(U); Py_DECREF(VT);
    return Py_BuildValue("NNN", Uc, S, V);
}

static PyMethodDef methods[] = {
    {"svd_gesdd", svd_gesdd, METH_VARARGS, ""},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "accel2", NULL, -1, methods};
PyMODINIT_FUNC PyInit_accel2(void) { import_array(); return PyModule_Create(&moduledef); }
'''
