#define ACCELERATE_NEW_LAPACK
#include <Accelerate/Accelerate.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    int sizes[][2] = {{300,250},{250,350},{400,220},{220,400},{300,300}};
    int nsizes = 5;
    for (int si = 0; si < nsizes; si++) {
        int n = sizes[si][0], m = sizes[si][1];
        int k = n < m ? n : m;
        int tall = n >= m;
        double *A = malloc((size_t)n*m*sizeof(double));
        for (int i = 0; i < n*m; i++) A[i] = sin(i*0.001)+0.01*cos(i*0.013);

        /* workspace for dsyevd */
        int kk = k;
        double *G = malloc((size_t)k*k*sizeof(double));
        double *w = malloc((size_t)k*sizeof(double));
        int lwork=-1, liwork=-1, info=0;
        double wq; int iq;
        char jobz='V', uplo='U';
