            else
                cblas_dsyrk(CblasColMajor, CblasUpper, CblasTrans, n, m, 1.0, A, m, 0.0, G, n);
            dsyevd(&jobz, &uplo, &kk, G, &kk, w, work, &lwork, iwork, &liwork, &info);
        }
        double te=(now()-t0)/reps;

        /* dgesdd */
        int lwork2=-1;
        double wq2;
        int *iwork2=malloc((size_t)(8*k)*sizeof(int));
        char jobz2='S';
        double *AF=malloc((size_t)n*m*sizeof(double));
        double *U=malloc((size_t)n*k*sizeof(double));
        double *VT=malloc((size_t)k*m*sizeof(double));
        double *S=malloc((size_t)k*sizeof(double));
        int nn=n, mm=m;
        dgesdd(&jobz2, &nn, &mm, AF, &nn, S, U, &nn, VT, &kk, &wq2, &lwork2, iwork2, &info);
        lwork2=(int)wq2;
        double *work2=malloc((size_t)lwork2*sizeof(double));
        t0=now();
        for (int r=0;r<reps;r++) {
            /* A is already col-major-ish? we filled linearly, treat as col-major copy */
            memcpy(AF, A, (size_t)n*m*sizeof(double));
            dgesdd(&jobz2, &nn, &mm, AF, &nn, S, U, &nn, VT, &kk, work2, &lwork2, iwork2, &info);
        }
        double tg=(now()-t0)/reps;
        printf("%dx%d  dsyevd %.1f ms   dgesdd %.1f ms   ratio %.2f\n", n, m, te*1000, tg*1000, tg/te);

        free(A); free(G); free(w); free(work); free(iwork);
        free(iwork2); free(AF); free(U); free(VT); free(S); free(work2);
    }
    return 0;
}
