#include <math.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

static void fill(double *A, int n) {
    for (int i = 0; i < n; i++) A[i] = sin(i * 0.001) + 0.01 * cos(i * 0.013);
}

/* Gram on the smaller side, always. A is row-major n x m? We'll pass column-major
   buffer of the orientation we choose. Here A is column-major n x m (lda=n). */
static double time_gram(double *A, int n, int m, int reps) {
    int tall = n >= m;
    int k = tall ? m : n;
    double *G = malloc((size_t)k * k * sizeof(double));
    double *w = malloc((size_t)k * sizeof(double));
    int kk = k, lwork = -1, liwork = -1, info = 0;
    double wq; int iq;
    char jobz = 'V', uplo = 'U';
    dsyevd_(&jobz, &uplo, &kk, G, &kk, w, &wq, &lwork, &iq, &liwork, &info);
    lwork = (int)wq; liwork = iq;
    double *work = malloc((size_t)lwork * sizeof(double));
    int *iwork = malloc((size_t)liwork * sizeof(int));
    double t0 = now();
    for (int r = 0; r < reps; r++) {
        if (tall)
            cblas_dsyrk(CblasColMajor, CblasUpper, CblasTrans, m, n, 1.0, A, n, 0.0, G, m);
        else
            cblas_dsyrk(CblasColMajor, CblasUpper, CblasNoTrans, n, m, 1.0, A, n, 0.0, G, n);
        dsyevd_(&jobz, &uplo, &kk, G, &kk, w, work, &lwork, iwork, &liwork, &info);
    }
    double t = (now() - t0) / reps;
    free(G); free(w); free(work); free(iwork);
    return t;
}

static double time_gesdd(double *A, int n, int m, int reps) {
    int k = n < m ? n : m;
    int nn = n, mm = m, kk = k, info = 0, lwork = -1;
    double wq;
    char jobz = 'S';
    double *AF = malloc((size_t)n * m * sizeof(double));
    double *U = malloc((size_t)n * k * sizeof(double));
    double *VT = malloc((size_t)k * m * sizeof(double));
    double *S = malloc((size_t)k * sizeof(double));
    int *iwork = malloc((size_t)8 * k * sizeof(int));
    dgesdd_(&jobz, &nn, &mm, AF, &nn, S, U, &nn, VT, &kk, &wq, &lwork, iwork, &info);
    lwork = (int)wq;
    double *work = malloc((size_t)lwork * sizeof(double));
    double t0 = now();
    for (int r = 0; r < reps; r++) {
        memcpy(AF, A, (size_t)n * m * sizeof(double));
        dgesdd_(&jobz, &nn, &mm, AF, &nn, S, U, &nn, VT, &kk, work, &lwork, iwork, &info);
    }
    double t = (now() - t0) / reps;
    free(AF); free(U); free(VT); free(S); free(iwork); free(work);
    return t;
}

int main() {
    int sizes[][2] = {{300,250},{250,350},{400,220},{220,400},{300,300},{200,200},{350,280},{280,360}};
    int nsizes = 8;
    for (int si = 0; si < nsizes; si++) {
        int n = sizes[si][0], m = sizes[si][1];
        double *A = malloc((size_t)n * m * sizeof(double));
        fill(A, n * m);
        double tg = time_gram(A, n, m, 3);
        double ts = time_gesdd(A, n, m, 3);
        printf("%4dx%-4d gram %6.1f ms  gesdd %6.1f ms  ratio %5.2f\n",
               n, m, tg*1000, ts*1000, ts/tg);
        free(A);
    }
    return 0;
}
