#define ACCELERATE_NEW_LAPACK
#include <Accelerate/Accelerate.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    int sizes[][2] = {{300,250},{250,350},{300,300},{400,220},{220,400},{400,400},{350,280}};
    for (int si = 0; si < 7; si++) {
        int n = sizes[si][0], m = sizes[si][1];
        int k = n < m ? n : m;
        int tall = n >= m;
        int nn=n, mm=m, kk=k, info=0;
        double *A = malloc((size_t)n*m*sizeof(double));
        for (int i=0;i<n*m;i++) A[i]=sin(i*0.001)+0.01*cos(i*0.013);

        /* QR of the tall side. If tall, QR(A) n x m. If wide, QR(A^T) m x n,
           so we just swap and always QR a (rows>=cols) matrix. */
        int rows = tall ? n : m;
        int cols = tall ? m : n;
        double *M = malloc((size_t)rows*cols*sizeof(double));
        if (tall) memcpy(M, A, (size_t)n*m*sizeof(double));
        else {
            /* transpose A (n x m col-major) into M (m x n col-major) */
            for (int c=0;c<m;c++) for (int r=0;r<n;r++) M[c + r*(size_t)m] = A[r + c*(size_t)n];
        }
        double *tau = malloc((size_t)cols*sizeof(double));
        int lwork=-1; double wq;
        int rr=rows, cc=cols;
        dgeqrf_(&rr,&cc,M,&rr,tau,&wq,&lwork,&info);
        lwork=(int)wq;
        double *work=malloc((size_t)lwork*sizeof(double));

        int reps=3;
        double t0=now();
        for (int r=0;r<reps;r++) {
            if (tall) memcpy(M, A, (size_t)n*m*sizeof(double));
            else for (int c=0;c<m;c++) for (int r2=0;r2<n;r2++) M[c + r2*(size_t)m] = A[r2 + c*(size_t)n];
            dgeqrf_(&rr,&cc,M,&rr,tau,work,&lwork,&info);
        }
        double tqr=(now()-t0)/reps;

        /* R is cols x cols upper triangle of M. Copy to RF col-major and bidiagonalize. */
        double *RF = malloc((size_t)cols*cols*sizeof(double));
        double *d=malloc((size_t)cols*sizeof(double));
        double *e=malloc((size_t)cols*sizeof(double));
        double *tauq=malloc((size_t)cols*sizeof(double));
        double *taup=malloc((size_t)cols*sizeof(double));
        int lwork2=-1; double wq2; int ccc=cols;
        dgebrd_(&ccc,&ccc,RF,&ccc,d,e,tauq,taup,&wq2,&lwork2,&info);
        lwork2=(int)wq2;
        double *work2=malloc((size_t)lwork2*sizeof(double));
        t0=now();
        for(int r=0;r<reps;r++){
            memset(RF,0,(size_t)cols*cols*sizeof(double));
            for(int c=0;c<cols;c++) for(int r2=0;r2<=c;r2++) RF[r2 + c*(size_t)cols]=M[r2 + c*(size_t)rows];
            dgebrd_(&ccc,&ccc,RF,&ccc,d,e,tauq,taup,work2,&lwork2,&info);
        }
        double tbrd=(now()-t0)/reps;

        /* dgesdd reference */
        int lwork3=-1; double wq3; char jobz='S';
        double *AF=malloc((size_t)n*m*sizeof(double));
        double *U=malloc((size_t)n*k*sizeof(double));
        double *VT=malloc((size_t)k*m*sizeof(double));
        double *S=malloc((size_t)k*sizeof(double));
        int *iwork=malloc((size_t)8*k*sizeof(int));
        dgesdd_(&jobz,&nn,&mm,AF,&nn,S,U,&nn,VT,&kk,&wq3,&lwork3,iwork,&info);
        lwork3=(int)wq3;
        double *work3=malloc((size_t)lwork3*sizeof(double));
        t0=now();
        for(int r=0;r<reps;r++){ memcpy(AF,A,(size_t)n*m*sizeof(double)); dgesdd_(&jobz,&nn,&mm,AF,&nn,S,U,&nn,VT,&kk,work3,&lwork3,iwork,&info); }
        double tsvd=(now()-t0)/reps;

        printf("%4dx%-4d QR %6.1f  R-gebrd %6.1f  sum %6.1f  gesdd %6.1f  ratio %.2f\n",
               n,m,tqr*1000,tbrd*1000,(tqr+tbrd)*1000,tsvd*1000, tsvd/(tqr+tbrd));
        free(A);free(M);free(tau);free(work);free(RF);free(d);free(e);free(tauq);free(taup);free(work2);
        free(AF);free(U);free(VT);free(S);free(iwork);free(work3);
    }
    return 0;
}
