    PyArrayObject *V = (PyArrayObject *)PyArray_EMPTY(2, dimsV, NPY_FLOAT64, 1);
    PyArrayObject *S = (PyArrayObject *)PyArray_EMPTY(1, dimsS, NPY_FLOAT64, 0);
    if (!U || !V || !S) { Py_XDECREF(A); Py_XDECREF(U); Py_XDECREF(V); Py_XDECREF(S); return NULL; }
