    if (tall)
        cblas_dsyrk(CblasColMajor, CblasUpper, CblasNoTrans, mm, nn, 1.0, Ad, mm, 0.0, G, mm);
    else
        cblas_dsyrk(CblasColMajor, CblasUpper, CblasTrans, nn, mm, 1.0, Ad, mm, 0.0, G, nn);

    char jobz = 'V', uplo = 'U';
    int info = 0;
    if (cached_k != kk) {
        int lwork = -1, liwork = -1; double wq; int iq;
        dsyevd_(&jobz, &uplo, &kk, G, &kk, Sd, &wq, &lwork, &iq, &liwork, &info);
        cached_lwork = (int)wq;
        cached_liwork = iq;
        cached_k = kk;
        /* query overwrote G; recompute it */
        if (tall)
            cblas_dsyrk(CblasColMajor, CblasUpper, CblasNoTrans, mm, nn, 1.0, Ad, mm, 0.0, G, mm);
        else
            cblas_dsyrk(CblasColMajor, CblasUpper, CblasTrans, nn, mm, 1.0, Ad, mm, 0.0, G, nn);
    }
    double *wbuf = need_d(&work, &work_n, cached_lwork);
    int *iwbuf = need_i(&iwork, &iwork_n, cached_liwork);
    dsyevd_(&jobz, &uplo, &kk, G, &kk, Sd, wbuf, &cached_lwork, iwbuf, &cached_liwork, &info);

    /* Scale eigenvector columns by 1/s in place; G is the small factor. */
    for (int c = 0; c < kk; c++) {
        double sj = Sd[c];
        sj = sqrt(sj > 0.0 ? sj : 0.0);
        Sd[c] = sj;
        double inv = 1.0 / sj;
        double *col = G + (size_t)c * kk;
        for (int r = 0; r < kk; r++) col[r] *= inv;
    }

    if (tall) {
        /* V = eigenvectors, column-major m x k. Restore the 1/s scaling. */
        for (int c = 0; c < kk; c++) {
            double s = Sd[c];
            double *src = G + (size_t)c * kk;
            double *dst = Vd + (size_t)c * kk;
            for (int r = 0; r < kk; r++) dst[r] = src[r] * s;
        }
        /* U = A @ (V/s). A_view is m x n col-major; U_col = A_view^T * G. */
        cblas_dgemm(CblasColMajor, CblasTrans, CblasNoTrans,
                    nn, kk, mm, 1.0, Ad, mm, G, kk, 0.0, Ud, nn);
    } else {
        for (int c = 0; c < kk; c++) {
            double s = Sd[c];
            double *src = G + (size_t)c * kk;
            double *dst = Ud + (size_t)c * kk;
            for (int r = 0; r < kk; r++) dst[r] = src[r] * s;
        }
        /* V = A^T @ (U/s) = A_view * G, column-major m x k. */
        cblas_dgemm(CblasColMajor, CblasNoTrans, CblasNoTrans,
                    mm, kk, nn, 1.0, Ad, mm, G, kk, 0.0, Vd, mm);
    }

    Py_DECREF(A);
    return Py_BuildValue("NNN", U, S, V);
}

static PyMethodDef methods[] = {
    {"svd_gram", svd_gram, METH_VARARGS, ""},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "accel_svd", NULL, -1, methods};
PyMODINIT_FUNC PyInit_accel_svd(void) { import_array(); return PyModule_Create(&moduledef); }
'''
