import numpy as np, random, accel_f32

def analyze(A):
    n, m = A.shape
    Uf, sf, Vf = accel_f32.svd_f32(A)
    tall = n >= m
    k = min(n, m)
    F = np.array(Vf if tall else Uf, dtype=np.float64, order='C', copy=True)
    Q, _ = np.linalg.qr(F, mode='reduced')
    if tall:
        W = A @ Q
    else:
        W = A.T @ Q
    H = W.T @ W
    d = np.diag(H)
    off = H - np.diag(d)
    iu = np.triu_indices(k, 1)
    au = np.abs(off[iu])
    scale = np.maximum(np.abs(d[iu[0]]), np.abs(d[iu[1]]))
    rel = au / np.maximum(scale, 1e-30)
    print(f"{A.shape} off_max {au.max():.3e} rel_max {rel.max():.3e} "
          f">1e-6 {(rel>1e-6).sum()} >1e-8 {(rel>1e-8).sum()} >1e-10 {(rel>1e-10).sum()} / {len(rel)}")

random.seed(0); np.random.seed(0)
for i in range(6):
    A = np.random.randn(random.randint(200,400), random.randint(200,400))
    analyze(A)
