import ctypes

import numpy as np
import torch

# MKL's complex eigensolver is substantially faster single-threaded at this size.
torch.set_num_threads(1)

_DTYPE = torch.float64


def _np_to_torch(A):
    """Copy a complex numpy array into a complex128 torch tensor without numpy interop."""
    A = np.ascontiguousarray(A)
    shape = A.shape
    real = torch.frombuffer(
        memoryview(np.ascontiguousarray(A.real)), dtype=_DTYPE
    ).reshape(shape).clone()
    imag = torch.frombuffer(
        memoryview(np.ascontiguousarray(A.imag)), dtype=_DTYPE
    ).reshape(shape).clone()
    return torch.complex(real, imag)


def _tensor_to_np(t):
    """Copy a float64 torch tensor into a numpy array without numpy interop."""
    t = t.contiguous()
    ptr = t.data_ptr()
    arr = np.ctypeslib.as_array(
        ctypes.cast(ptr, ctypes.POINTER(ctypes.c_double)), shape=tuple(t.shape)
    )
    return np.array(arr, copy=True)


class Solver:
    def solve(self, problem, **kwargs):
        A = problem["matrix"]
        # 1x1 (and empty) handled directly; torch eig wants n >= 1 square.
        A = np.asarray(A)
        if A.ndim != 2 or A.shape[0] != A.shape[1] or A.shape[0] == 0:
            return {"sqrtm": {"X": []}}
        if A.shape[0] == 1:
            x = np.sqrt(A[0, 0] + 0j)
            if x.real < 0:
                x = -x
            return {"sqrtm": {"X": [[complex(x)]]}}

        At = _np_to_torch(A)
        w, V = torch.linalg.eig(At)
        # Principal square root: eigenvalues with non-negative real part.
        sw = torch.sqrt(w)
        sw = torch.where(sw.real < 0, -sw, sw)
        X = (V * sw) @ torch.linalg.inv(V)
        Xnp = _tensor_to_np(X.real) + 1j * _tensor_to_np(X.imag)
        return {"sqrtm": {"X": Xnp.tolist()}}

