        if A.ndim != 2 or A.shape[0] != A.shape[1] or A.shape[0] == 0:
            return {"sqrtm": {"X": []}}
        if A.shape[0] == 1:
            x = np.sqrt(A[0, 0] + 0j)
            if x.real < 0:
                x = -x
            return {"sqrtm": {"X": [[complex(x)]]}}

        At = _np_to_torch(A)
        w, V = torch.linalg.eig(At)
        # Principal square root: eigenvalues with non-negative real part.
        sw = torch.sqrt(w)
        sw = torch.where(sw.real < 0, -sw, sw)
        X = (V * sw) @ torch.linalg.inv(V)
        Xnp = _tensor_to_np(X.real) + 1j * _tensor_to_np(X.imag)
        return {"sqrtm": {"X": Xnp.tolist()}}
