#include <stdlib.h>
#include <math.h>
#include <string.h>

/* sort two arrays and compute two-sample KS statistic */
static int cmp_double(const void *a, const void *b) {
    double da = *(const double *)a;
    double db = *(const double *)b;
    return (da > db) - (da < db);
}

double ks_stat(double *a, double *b, int n1, int n2) {
    qsort(a, n1, sizeof(double), cmp_double);
    qsort(b, n2, sizeof(double), cmp_double);
    int i = 0, j = 0, c1 = 0, c2 = 0;
    double inv1 = 1.0 / n1;
    double inv2 = 1.0 / n2;
    double d = 0.0;
    while (i < n1 && j < n2) {
        if (a[i] < b[j]) {
            double v = a[i];
            while (i < n1 && a[i] == v) { i++; c1++; }
        } else if (b[j] < a[i]) {
            double v = b[j];
            while (j < n2 && b[j] == v) { j++; c2++; }
        } else {
            double v = a[i];
            while (i < n1 && a[i] == v) { i++; c1++; }
            while (j < n2 && b[j] == v) { j++; c2++; }
        }
        double diff = c1 * inv1 - c2 * inv2;
        if (diff < 0) diff = -diff;
        if (diff > d) d = diff;
    }
    return d;
}
