#include <Python.h>
#include <stdlib.h>

static int cmp_double(const void *a, const void *b) {
    double da = *(const double *)a;
    double db = *(const double *)b;
    return (da > db) - (da < db);
}

/* Convert two lists to sorted numpy-free result: returns (stat) computed inside,
   and also we can return sorted arrays as memoryviews. For speed test, compute KS stat. */
static PyObject *ks_from_lists(PyObject *self, PyObject *args) {
    PyObject *l1, *l2;
    if (!PyArg_ParseTuple(args, "OO", &l1, &l2)) return NULL;
    Py_ssize_t n1 = PyList_GET_SIZE(l1);
    Py_ssize_t n2 = PyList_GET_SIZE(l2);
    double *a = (double *)malloc(sizeof(double) * (size_t)n1);
    double *b = (double *)malloc(sizeof(double) * (size_t)n2);
    if (!a || !b) { free(a); free(b); return PyErr_NoMemory(); }
    for (Py_ssize_t i = 0; i < n1; i++) {
        PyObject *item = PyList_GET_ITEM(l1, i);
        a[i] = PyFloat_AS_DOUBLE(item);
    }
    for (Py_ssize_t i = 0; i < n2; i++) {
        PyObject *item = PyList_GET_ITEM(l2, i);
        b[i] = PyFloat_AS_DOUBLE(item);
    }
    qsort(a, (size_t)n1, sizeof(double), cmp_double);
    qsort(b, (size_t)n2, sizeof(double), cmp_double);
    Py_ssize_t i = 0, j = 0, c1 = 0, c2 = 0;
    double inv1 = 1.0 / (double)n1;
    double inv2 = 1.0 / (double)n2;
    double d = 0.0;
    while (i < n1 && j < n2) {
        double va = a[i], vb = b[j];
        if (va < vb) {
            do { i++; c1++; } while (i < n1 && a[i] == va);
        } else if (vb < va) {
            do { j++; c2++; } while (j < n2 && b[j] == vb);
        } else {
            do { i++; c1++; } while (i < n1 && a[i] == va);
            do { j++; c2++; } while (j < n2 && b[j] == vb);
        }
        double diff = c1 * inv1 - c2 * inv2;
        if (diff < 0) diff = -diff;
        if (diff > d) d = diff;
    }
    free(a); free(b);
    return PyFloat_FromDouble(d);
}

static PyMethodDef methods[] = {
    {"ks_from_lists", ks_from_lists, METH_VARARGS, NULL},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "listsort", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_listsort(void) { return PyModule_Create(&moduledef); }
