#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <stdlib.h>

/* pdqsort-like introsort for doubles */

static inline void swap_d(double *a, double *b) {
    double t = *a; *a = *b; *b = t;
}

static inline void insertion_sort(double *a, Py_ssize_t n) {
    for (Py_ssize_t i = 1; i < n; i++) {
        double v = a[i];
        Py_ssize_t j = i;
        while (j > 0 && a[j-1] > v) {
            a[j] = a[j-1];
            j--;
        }
        a[j] = v;
    }
}

static inline Py_ssize_t median3(double *a, Py_ssize_t i, Py_ssize_t j, Py_ssize_t k) {
    double ai = a[i], aj = a[j], ak = a[k];
    if (ai < aj) {
        if (aj < ak) return j;
        return (ai < ak) ? k : i;
    } else {
        if (ai < ak) return i;
        return (aj < ak) ? k : j;
    }
}

static void introsort(double *a, Py_ssize_t n, int depth) {
    while (n > 24) {
        if (depth == 0) {
            /* heapsort fallback */
            /* build heap */
            for (Py_ssize_t start = n/2 - 1; start >= 0; start--) {
                Py_ssize_t root = start;
                while (1) {
                    Py_ssize_t child = 2*root + 1;
                    if (child >= n) break;
                    if (child + 1 < n && a[child] < a[child+1]) child++;
                    if (a[root] < a[child]) {
                        swap_d(&a[root], &a[child]);
                        root = child;
                    } else break;
                }
            }
            Py_ssize_t end = n;
            while (end > 1) {
                end--;
                swap_d(&a[0], &a[end]);
                Py_ssize_t root = 0;
                while (1) {
                    Py_ssize_t child = 2*root + 1;
                    if (child >= end) break;
                    if (child + 1 < end && a[child] < a[child+1]) child++;
                    if (a[root] < a[child]) {
                        swap_d(&a[root], &a[child]);
                        root = child;
                    } else break;
                }
            }
            return;
        }
        depth--;
        Py_ssize_t m = median3(a, 0, n/2, n-1);
        swap_d(&a[m], &a[n-1]);
        double pivot = a[n-1];
        Py_ssize_t i = 0;
        for (Py_ssize_t j = 0; j < n-1; j++) {
            if (a[j] < pivot) {
                swap_d(&a[i], &a[j]);
                i++;
            }
        }
        swap_d(&a[i], &a[n-1]);
        /* recurse smaller side */
        if (i < n - i - 1) {
            introsort(a, i, depth);
            a += i + 1;
            n = n - i - 1;
        } else {
            introsort(a + i + 1, n - i - 1, depth);
            n = i;
        }
    }
    insertion_sort(a, n);
}

static int depth_limit(Py_ssize_t n) {
    int d = 0;
    while (n > 1) { n >>= 1; d++; }
    return d * 2;
}

static int read_list(PyObject *list, double **out, Py_ssize_t *n_out) {
    Py_ssize_t n = PyList_GET_SIZE(list);
    double *a = (double *)malloc(sizeof(double) * (size_t)n);
    if (!a) return -1;
    for (Py_ssize_t i = 0; i < n; i++) {
        a[i] = PyFloat_AS_DOUBLE(PyList_GET_ITEM(list, i));
    }
    *out = a;
    *n_out = n;
    return 0;
}

static PyObject *sort_list(PyObject *self, PyObject *args) {
    PyObject *list;
    if (!PyArg_ParseTuple(args, "O", &list)) return NULL;
    double *a;
    Py_ssize_t n;
    if (read_list(list, &a, &n) < 0) return PyErr_NoMemory();
    introsort(a, n, depth_limit(n));
    /* return a memoryview / bytes that numpy can wrap? We'll return a bytes object and let caller copy.
       Better: build a Python list? slow. Return bytes. */
    PyObject *b = PyBytes_FromStringAndSize((char *)a, n * (Py_ssize_t)sizeof(double));
    free(a);
    return b;
}

static PyObject *ks_from_lists(PyObject *self, PyObject *args) {
    PyObject *l1, *l2;
    if (!PyArg_ParseTuple(args, "OO", &l1, &l2)) return NULL;
    double *a, *b;
    Py_ssize_t n1, n2;
    if (read_list(l1, &a, &n1) < 0) return PyErr_NoMemory();
    if (read_list(l2, &b, &n2) < 0) { free(a); return PyErr_NoMemory(); }
    introsort(a, n1, depth_limit(n1));
    introsort(b, n2, depth_limit(n2));
    Py_ssize_t i = 0, j = 0, c1 = 0, c2 = 0;
    double inv1 = 1.0 / (double)n1;
    double inv2 = 1.0 / (double)n2;
    double d = 0.0;
    while (i < n1 && j < n2) {
        double va = a[i], vb = b[j];
        if (va < vb) {
            do { i++; c1++; } while (i < n1 && a[i] == va);
        } else if (vb < va) {
            do { j++; c2++; } while (j < n2 && b[j] == vb);
        } else {
            do { i++; c1++; } while (i < n1 && a[i] == va);
            do { j++; c2++; } while (j < n2 && b[j] == vb);
        }
        double diff = c1 * inv1 - c2 * inv2;
        if (diff < 0) diff = -diff;
        if (diff > d) d = diff;
    }
    free(a); free(b);
    return PyFloat_FromDouble(d);
}

static PyMethodDef methods[] = {
    {"ks_from_lists", ks_from_lists, METH_VARARGS, NULL},
    {"sort_list", sort_list, METH_VARARGS, NULL},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "listsort", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_listsort(void) { return PyModule_Create(&moduledef); }
