    double z8 = z4 * z4;
    double z7 = z6 * z;
    double z10 = z8 * z2;

    double qlog = -PI2 / 8.0 / z2;
    if (qlog < -708.0) return 1.0;
    double q = exp(qlog);

    double k1a = -z2;
    double k1b = PI2 / 4.0;
    double k2a = 6.0 * z6 + 2.0 * z4;
    double k2b = (2.0 * z4 - 5.0 * z2) * PI2 / 4.0;
    double k2c = PI4 * (1.0 - 2.0 * z2) / 16.0;
    double k3d = PI6 * (5.0 - 30.0 * z2) / 64.0;
    double k3c = PI4 * (-60.0 * z2 + 212.0 * z4) / 16.0;
    double k3b = PI2 * (135.0 * z4 - 96.0 * z6) / 4.0;
    double k3a = -30.0 * z6 - 90.0 * z8;

    double K0 = 0.0, K1 = 0.0, K2 = 0.0, K3 = 0.0;
    int maxk = (int)ceil(16.0 * z / PI);
    if (maxk < 1) maxk = 1;
    for (int k = maxk; k >= 1; --k) {
        double m = (double)(2 * k - 1);
        double m2 = m * m;
        double m4 = m2 * m2;
        double m6 = m4 * m2;
        double qpower = pow(q, 8.0 * (double)k);
        K0 = K0 * qpower + 1.0;
        K1 = K1 * qpower + (k1a + k1b * m2);
        K2 = K2 * qpower + (k2a + k2b * m2 + k2c * m4);
        K3 = K3 * qpower + (k3a + k3b * m2 + k3c * m4 + k3d * m6);
    }
    double s2pi = sqrt(2.0 * PI);
    double qs = q * s2pi;
    K0 *= qs; K1 *= qs; K2 *= qs; K3 *= qs;
    K0 /= z;
    K1 /= 6.0 * z4;
    K2 /= 72.0 * z7;
    K3 /= 6480.0 * z10;

    double q2 = exp(-PI2 / 2.0 / z2);
    double k2extra = 0.0, k3extra = 0.0;
    double sqrt3z = sqrt(3.0) * z;
    for (int k = maxk; k >= 1; --k) {
        double kk = (double)k * (double)k;
        double qpw = pow(q2, kk);
        k2extra += kk * qpw;
        double kspi = PI * (double)k;
        k3extra += (sqrt3z + kspi) * (sqrt3z - kspi) * kk * qpw;
    }
    K2 += k2extra * PI2 * s2pi / (-36.0 * z3);
    K3 += k3extra * PI2 * s2pi / (216.0 * z6);

    double sqrtn = sqrt(n);
    K1 /= sqrtn;
    K2 /= n;
    K3 /= n * sqrtn;

    double sf = 1.0 - (K0 + K1 + K2 + K3);
    if (sf < 0.0) sf = 0.0;
    else if (sf > 1.0) sf = 1.0;
    return sf;
}

static PyArrayObject *list_to_sorted_array(PyObject *list) {
    Py_ssize_t n = PyList_GET_SIZE(list);
    npy_intp dims[1] = {n};
    PyArrayObject *a = (PyArrayObject *)PyArray_SimpleNew(1, dims, NPY_FLOAT64);
    if (!a) return NULL;
    double *da = (double *)PyArray_DATA(a);
    for (Py_ssize_t i = 0; i < n; i++) {
        PyObject *item = PyList_GET_ITEM(list, i);
        da[i] = PyFloat_AS_DOUBLE(item);
    }
    if (PyArray_Sort(a, 0, NPY_QUICKSORT) < 0) {
        Py_DECREF(a);
        return NULL;
    }
    return a;
}

static PyObject *ks_2samp_fast(PyObject *self, PyObject *args) {
    PyObject *l1, *l2;
    if (!PyArg_ParseTuple(args, "OO", &l1, &l2)) return NULL;
    if (!PyList_Check(l1) || !PyList_Check(l2)) {
        PyErr_SetString(PyExc_TypeError, "expected two lists");
        return NULL;
    }
    PyArrayObject *a = list_to_sorted_array(l1);
    if (!a) return PyErr_NoMemory();
    PyArrayObject *b = list_to_sorted_array(l2);
    if (!b) { Py_DECREF(a); return PyErr_NoMemory(); }
    Py_ssize_t n1 = PyArray_SIZE(a);
    Py_ssize_t n2 = PyArray_SIZE(b);
    double d = ks_stat((double *)PyArray_DATA(a), (double *)PyArray_DATA(b), n1, n2);
    double en = round(((double)n1 * (double)n2) / ((double)n1 + (double)n2));
    double sf = ks_sf_pelz(en, d);
    Py_DECREF(a);
    Py_DECREF(b);
    return Py_BuildValue("(dd)", d, sf);
}

static PyMethodDef methods[] = {
    {"ks_2samp_fast", ks_2samp_fast, METH_VARARGS, NULL},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "ksfast", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_ksfast(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
