// Jonker-Volgenant shortest augmenting path assignment (dense)
// Based on the classic LAPJV algorithm.
#include <vector>
#include <cmath>
#include <limits>
#include <cstdint>
#include <algorithm>
#include <cstring>

extern "C" {

// Solve min-cost assignment for n x n cost matrix (row-major).
// col_for_row[i] = assigned column for row i
// returns 0 on success
int lapjv(const double* cost, int n, int* col_for_row) {
    const double INF = 1e100;
    // dual variables
    std::vector<double> u(n, 0.0), v(n, 0.0);
    // assignment: row_of_col[j] = row assigned to column j, -1 if free
    std::vector<int> row_of_col(n, -1);
    std::vector<int> pred(n);
    std::vector<double> dist(n);
    std::vector<char> seen(n);

    for (int i = 0; i < n; ++i) {
        // shortest augmenting path from free row i
        int free_row = i;
        std::fill(pred.begin(), pred.end(), -1);
        std::fill(seen.begin(), seen.end(), 0);
        for (int j = 0; j < n; ++j) {
            dist[j] = cost[(size_t)free_row * n + j] - u[free_row] - v[j];
        }
        int j_cur = -1;
        int sink = -1;
        while (true) {
            // find unscanned column with minimum dist
            double dmin = INF;
            j_cur = -1;
            for (int j = 0; j < n; ++j) {
                if (!seen[j] && dist[j] < dmin) {
                    dmin = dist[j];
                    j_cur = j;
                }
            }
            if (j_cur < 0) return 1; // failure
            seen[j_cur] = 1;
            int i_matched = row_of_col[j_cur];
            if (i_matched < 0) {
                sink = j_cur;
                // update duals along the way: for scanned columns
                // We'll do dual update after finding sink using dmin of scanned
                break;
            }
            // update dual potential of matched row and relax
            // The reduction: dist to other columns via this matched row
            double ui = cost[(size_t)i_matched * n + j_cur] - v[j_cur] - dmin;
            // Actually standard formulation:
            // u[i_matched] should be updated later. For relaxation:
            const double* crow = cost + (size_t)i_matched * n;
            for (int j = 0; j < n; ++j) {
                if (seen[j]) continue;
                double nd = crow[j] - ui - v[j];
                // wait, ui computed as crow[j_cur] - v[j_cur] - dmin, and
                // reduced cost of (i_matched, j) relative to path cost dmin is:
                // crow[j] - v[j] - ui = crow[j] - v[j] - (crow[j_cur] - v[j_cur] - dmin)
                // = crow[j] - v[j] - crow[j_cur] + v[j_cur] + dmin
