// Dense Jonker-Volgenant / LAPJV shortest-augmenting-path assignment.
// Returns column index assigned to each row.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cstring>
#include <cmath>

extern "C" {

int lapjv(const double* cost, int n, int* col_for_row) {
    const double INF = 1e300;

    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> row_of_col(n, -1);   // matching: column -> row
    std::vector<int> pred(n, -1);         // predecessor column on shortest path
    std::vector<int> scan_list(n);
    std::vector<double> dist(n);
    std::vector<char> seen(n, 0);

    // Column reduction: initialize a partial matching and dual v
    // (Jonker-Volgenant column reduction + reduction transfer)
    std::vector<int> free_rows;
    free_rows.reserve(n);
    std::vector<char> row_matched(n, 0);

    // For each column, find minimum cost row (two smallest)
    for (int j = n - 1; j >= 0; --j) {
        double min1 = INF, min2 = INF;
        int imin = 0;
        for (int i = 0; i < n; ++i) {
            double c = cost[(size_t)i * n + j];
            if (c < min1) {
                min2 = min1;
                min1 = c;
                imin = i;
            } else if (c < min2) {
                min2 = c;
            }
        }
        v[j] = min1;
        if (row_matched[imin]) {
            // already matched: this column stays free for now, but transfer reduction
            // find the column currently matched to imin and compare
            int j_old = -1;
            for (int jj = j + 1; jj < n; ++jj) {
                if (row_of_col[jj] == imin) { j_old = jj; break; }
            }
            if (j_old >= 0) {
                double c_old = cost[(size_t)imin * n + j_old] - v[j_old];
                double c_new = cost[(size_t)imin * n + j] - v[j];
                if (c_new < c_old) {
                    row_of_col[j] = imin;
                    row_of_col[j_old] = -1;
                    v[j] = min1; // already
                } else {
                    v[j] = min2; // reduction transfer: raise v so reduced cost stays
                    // actually standard transfer sets v[j] = min1 - (c_old difference)...
                    // Keep simple: leave unmatched, v[j]=min1 is fine (feasible dual not required yet)
                }
            }
        } else {
            row_of_col[j] = imin;
            row_matched[imin] = 1;
        }
    }
    for (int i = 0; i < n; ++i) if (!row_matched[i]) free_rows.push_back(i);

    // Set row duals for matched rows: u[i] = cost[i, j] - v[j]
    for (int j = 0; j < n; ++j) {
        int i = row_of_col[j];
        if (i >= 0) u[i] = cost[(size_t)i * n + j] - v[j];
    }

    // Augment free rows with Dijkstra shortest augmenting paths
    std::vector<int> still_free;
    still_free.reserve(free_rows.size());

    for (int free_row : free_rows) {
        std::fill(seen.begin(), seen.end(), 0);
        std::fill(pred.begin(), pred.end(), -1);

        int scanned = 0;
        for (int j = 0; j < n; ++j) {
            dist[j] = cost[(size_t)free_row * n + j] - u[free_row] - v[j];
        }

        int sink = -1;
        int last_scanned_count_at_sink = 0;
        double dmin_sink = 0.0;

        while (true) {
            // pick unscanned column with smallest dist
            double dmin = INF;
            int jmin = -1;
            for (int j = 0; j < n; ++j) {
                if (!seen[j] && dist[j] < dmin) {
                    dmin = dist[j];
                    jmin = j;
                }
            }
            if (jmin < 0) { sink = -1; break; }

            seen[jmin] = 1;
            scan_list[scanned++] = jmin;

            int i_matched = row_of_col[jmin];
            if (i_matched < 0) {
                sink = jmin;
                dmin_sink = dmin;
                last_scanned_count_at_sink = scanned;
                break;
            }

            // relax edges out of the matched row
            const double* crow = cost + (size_t)i_matched * n;
            double u_i = u[i_matched];
            // reduced cost offset: path cost to reach this row is dmin,
            // edge reduced cost is crow[j] - u_i - v[j]
            for (int j = 0; j < n; ++j) {
                if (seen[j]) continue;
                double nd = dmin + crow[j] - u_i - v[j];
                if (nd < dist[j]) {
                    dist[j] = nd;
                    pred[j] = jmin;
                }
            }
        }

        if (sink < 0) return 1;

        // Dual update:
        // For every scanned column except the sink, dist[j] is the shortest path cost
        // to that column, and it is <= dmin_sink. Raise v and u to keep reduced costs nonnegative.
        // u[free_row] += dmin_sink
        // for scanned columns j (including sink): v[j] += dist[j] - dmin_sink  (dist[sink] == dmin_sink so v unchanged for sink? )
        // Standard (Burkard/Jonker):
        //   u[i0] = u[i0] + dmin_sink
        //   for each scanned column j != sink: v[j] = v[j] - (dist[j] - dmin_sink)  i.e. v decreases by (dmin_sink - dist[j])? 
        // Let's use the formulation that preserves complementary slackness:
        // After augmentation, for scanned columns j (pred path), we set
        //   v[j] := v[j] - (dmin_sink - dist[j])     so reduced costs of scanned tight edges stay tight
        //   and u of rows whose matched column was scanned increases accordingly.
        //
        // Concrete invariant we want: for the unique tight matching edges and the augmenting path edges,
        // reduced cost cost - u - v == 0.
        //
        // Path cost to column j (scanned) is dist[j], and dist[j] <= dmin_sink.
        // The row matched to a scanned column j (j != sink) has a tight edge.
        // Updating:
        //   v[j] -= (dmin_sink - dist[j]) for all scanned j including sink (sink delta = 0)
        //   u[i] += (dmin_sink - dist[j]) for row i matched to scanned column j
        //   u[free_row] += dmin_sink
        // This keeps previously tight edges tight (both ends adjusted equally) and
        // makes augmenting-path edges tight.

        u[free_row] += dmin_sink;
        for (int k = 0; k < scanned; ++k) {
            int j = scan_list[k];
            double delta = dmin_sink - dist[j];
            v[j] -= delta;
            int i_matched = row_of_col[j];
            if (i_matched >= 0) u[i_matched] += delta;
        }

        // Augment along pred links
        int j = sink;
        while (true) {
            int j_pred = pred[j];
            int i_prev;
            if (j_pred < 0) {
                // edge from free_row
                row_of_col[j] = free_row;
                break;
            } else {
                // the matched row of j_pred moves to j
                i_prev = row_of_col[j_pred];
                row_of_col[j] = i_prev;
                j = j_pred;
            }
        }
    }

    for (int j = 0; j < n; ++j) {
        int i = row_of_col[j];
        if (i < 0) return 2;
        col_for_row[i] = j;
    }
    return 0;
}

} // extern C
