// Fast dense LAPJV (Jonker-Volgenant) for the square assignment problem.
//
// Column-reduction initialization + Dijkstra shortest augmenting paths,
// with an O(n) argmin scan (fine for n=600; the constant factors matter).
#include <cstdint>
#include <cstring>
#include <algorithm>
#include <cmath>

extern "C" {

int lapjv(const double* __restrict cost, int n, int* __restrict col_for_row) {
    const double INF = 1e300;

    // Allocate one contiguous scratch buffer
    // u[n], v[n], dist[n]  as double
    // row_of_col[n], pred[n], free_rows[n], scan[n] as int
    // seen[n] as char, row_matched[n] as char
    double* u = new double[n];
    double* v = new double[n];
    double* dist = new double[n];
    int* row_of_col = new int[n];
    int* pred = new int[n];
    int* free_rows = new int[n];
    int* scan = new int[n];
    char* seen = new char[n];
    char* row_matched = new char[n];

    for (int i = 0; i < n; ++i) {
        u[i] = 0.0;
        row_matched[i] = 0;
    }
    for (int j = 0; j < n; ++j) {
        row_of_col[j] = -1;
        v[j] = 0.0;
    }

    // ---------- Column reduction ----------
    // Process columns from right to left. Assign each column to its cheapest
    // currently free row; if that row is taken, transfer the reduction when beneficial.
    int nfree = 0;
    for (int j = n - 1; j >= 0; --j) {
        double min1 = INF, min2 = INF;
        int imin = 0;
        const double* base = cost + j; // column j, stride n
        for (int i = 0; i < n; ++i) {
            double c = base[(size_t)i * n];
            if (c < min1) {
                min2 = min1;
                min1 = c;
                imin = i;
            } else if (c < min2) {
                min2 = c;
            }
        }
        v[j] = min1;
