            double u_i = u[i_matched];
            double base = dmin - u_i;
            for (int j = 0; j < n; ++j) {
                if (seen[j]) continue;
                double nd = base + crow[j] - v[j];
                if (nd < dist[j]) {
                    dist[j] = nd;
                    pred[j] = jmin;
                }
            }
        }

        if (sink < 0) {
            delete[] u; delete[] v; delete[] dist;
            delete[] row_of_col; delete[] pred; delete[] free_rows; delete[] scan;
            delete[] seen; delete[] row_matched;
            return 1;
        }

        // Dual update
        u[free_row] = u_free + dmin_sink;
        for (int k = 0; k < scanned; ++k) {
            int j = scan[k];
            double delta = dmin_sink - dist[j];
            v[j] -= delta;
            int im = row_of_col[j];
            if (im >= 0) u[im] += delta;
        }

        // Augment
        int j = sink;
        int i_to_place = free_row;
        // Walk pred chain. pred[j] is the previous column; the row currently
        // matched to pred[j] should move to j. The free row enters at the
        // start of the chain (pred == -1).
        while (true) {
            int j_pred = pred[j];
            if (j_pred < 0) {
                row_of_col[j] = free_row;
                break;
            }
            row_of_col[j] = row_of_col[j_pred];
            j = j_pred;
        }
        (void)i_to_place;
    }

    for (int j = 0; j < n; ++j) {
        int i = row_of_col[j];
        if (i < 0 || i >= n) {
            delete[] u; delete[] v; delete[] dist;
            delete[] row_of_col; delete[] pred; delete[] free_rows; delete[] scan;
            delete[] seen; delete[] row_matched;
            return 2;
        }
        col_for_row[i] = j;
    }

    delete[] u; delete[] v; delete[] dist;
    delete[] row_of_col; delete[] pred; delete[] free_rows; delete[] scan;
    delete[] seen; delete[] row_matched;
    return 0;
}

} // extern C
