// Hungarian algorithm, O(n^3), dense. Minimization.
// Dual-based implementation (Kuhn-Munkres) that is numerically stable for float costs.
#include <cstdint>
#include <cstring>
#include <algorithm>

extern "C" {

int lapjv(const double* cost, int n, int* col_for_row) {
    const double INF = 1e300;

    double* u = new double[n + 1];
    double* v = new double[n + 1];
    int* p = new int[n + 1];       // p[j] = row matched to column j (1-indexed rows), p[0] unused matching-wise
    int* way = new int[n + 1];
    double* minv = new double[n + 1];
    char* used = new char[n + 1];

    for (int i = 0; i <= n; ++i) { u[i] = 0; v[i] = 0; p[i] = 0; }

    for (int i = 1; i <= n; ++i) {
        p[0] = i;
        int j0 = 0;
        for (int j = 0; j <= n; ++j) { minv[j] = INF; used[j] = 0; }

        do {
            used[j0] = 1;
            int i0 = p[j0];
            double delta = INF;
            int j1 = 0;
            const double* crow = cost + (size_t)(i0 - 1) * n;
            double ui = u[i0];
            for (int j = 1; j <= n; ++j) {
                if (used[j]) continue;
                double cur = crow[j - 1] - ui - v[j];
                if (cur < minv[j]) {
                    minv[j] = cur;
                    way[j] = j0;
                }
                if (minv[j] < delta) {
                    delta = minv[j];
                    j1 = j;
                }
            }
            for (int j = 0; j <= n; ++j) {
                if (used[j]) {
                    u[p[j]] += delta;
                    v[j] -= delta;
                } else {
                    minv[j] -= delta;
                }
            }
            j0 = j1;
        } while (p[j0] != 0);

        // augment
        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0 != 0);
    }

    for (int j = 1; j <= n; ++j) {
        if (p[j] == 0) {
            delete[] u; delete[] v; delete[] p; delete[] way; delete[] minv; delete[] used;
            return 1;
        }
        col_for_row[p[j] - 1] = j - 1;
    }

    delete[] u; delete[] v; delete[] p; delete[] way; delete[] minv; delete[] used;
    return 0;
}

}
