// Kuhn-Munkres / Hungarian minimization, dense, 1-indexed dual formulation.
// Optimized inner loop: separate the min-tracking scan from the dual update.
#include <cstdint>
#include <cstring>
#include <algorithm>

extern "C" {

int lapjv(const double* __restrict cost, int n, int* __restrict col_for_row) {
    const double INF = 1e300;

    double* u = (double*)aligned_alloc(64, sizeof(double) * (n + 1));
    double* v = (double*)aligned_alloc(64, sizeof(double) * (n + 1));
    double* minv = (double*)aligned_alloc(64, sizeof(double) * (n + 1));
    int* p = (int*)aligned_alloc(64, sizeof(int) * (n + 1));
    int* way = (int*)aligned_alloc(64, sizeof(int) * (n + 1));
    char* used = (char*)aligned_alloc(64, (n + 1));

    std::memset(u, 0, sizeof(double) * (n + 1));
    std::memset(v, 0, sizeof(double) * (n + 1));
    std::memset(p, 0, sizeof(int) * (n + 1));

    for (int i = 1; i <= n; ++i) {
        p[0] = i;
        int j0 = 0;
        std::memset(used, 0, n + 1);
        for (int j = 0; j <= n; ++j) minv[j] = INF;

        do {
            used[j0] = 1;
            int i0 = p[j0];
            const double* __restrict crow = cost + (size_t)(i0 - 1) * n;
            double ui = u[i0];

            double delta = INF;
            int j1 = -1;

            // j from 1..n
            for (int j = 1; j <= n; ++j) {
                if (used[j]) continue;
                double cur = crow[j - 1] - ui - v[j];
                double mv = minv[j];
                if (cur < mv) {
                    mv = cur;
                    minv[j] = cur;
                    way[j] = j0;
                }
                if (mv < delta) {
                    delta = mv;
                    j1 = j;
                }
            }

            // dual update
            for (int j = 0; j <= n; ++j) {
                if (used[j]) {
                    u[p[j]] += delta;
                    v[j] -= delta;
                } else {
                    minv[j] -= delta;
                }
            }
            j0 = j1;
        } while (p[j0] != 0);

        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0 != 0);
    }

    for (int j = 1; j <= n; ++j) {
        col_for_row[p[j] - 1] = j - 1;
    }

    free(u); free(v); free(minv); free(p); free(way); free(used);
    return 0;
}

}
