// Bertsekas auction algorithm for the dense assignment problem (minimization).
// epsilon-scaling. Returns a feasible assignment; for small enough final epsilon
// it is optimal for costs separated by more than n*eps.
#include <cstdint>
#include <cstring>
#include <cmath>
#include <algorithm>
#include <vector>

extern "C" {

int auction(const double* cost, int n, int* col_for_row, double eps_final, double eps_factor) {
    // prices, bids
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);          // column -> row
    std::vector<int> assign(n, -1);         // row -> column
    std::vector<int> unassigned(n);

    // start with a large epsilon and scale down
    // estimate cost scale
    double cmax = 0.0;
    // sample a subset for scale
    int step = std::max(1, n / 32);
    for (int i = 0; i < n; i += step)
        for (int j = 0; j < n; j += step)
            cmax = std::max(cmax, cost[(size_t)i * n + j]);
    double eps = std::max(cmax / 4.0, eps_final);

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        int nfree = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;

        // bidding rounds until all assigned (epsilon-CS assignment always terminates
        // for positive epsilon on a complete bipartite graph)
        int guard = 0;
        int guard_max = n * 40;
        while (nfree > 0 && guard < guard_max) {
            ++guard;
            // each unassigned row bids for its best column
            // To avoid concurrent bid conflicts we process rows one at a time
            // (Gauss-Seidel auction), which converges faster in practice.
            int new_nfree = 0;
            for (int k = 0; k < nfree; ++k) {
                int i = unassigned[k];
                const double* crow = cost + (size_t)i * n;
                // find best and second best value: value = -cost - price? 
                // minimization auction: profit_j = -cost_ij - price_j
                // We maximize profit.
                double best = -1e300, second = -1e300;
                int bestj = 0;
                for (int j = 0; j < n; ++j) {
                    double val = -crow[j] - price[j];
                    if (val > best) {
                        second = best;
                        best = val;
                        bestj = j;
                    } else if (val > second) {
                        second = val;
                    }
                }
                // bid: raise price so this column's profit equals second best - eps
                // best - price_increase = second - eps
                // price_increase = best - second + eps
                double bid_inc = best - second + eps;
                price[bestj] += bid_inc;
                int prev = owner[bestj];
                owner[bestj] = i;
                assign[i] = bestj;
                if (prev >= 0) {
                    assign[prev] = -1;
                    unassigned[new_nfree++] = prev;
                }
            }
            nfree = new_nfree;
        }
        if (nfree > 0) {
            // failed to converge at this epsilon; try smaller step by reducing eps slower
            // Fall through and still scale down; mark failure if final
            if (eps <= eps_final * 1.0001) return 1;
        }
        if (eps <= eps_final * 1.0001) break;
        eps = std::max(eps * eps_factor, eps_final);
        // keep prices as warm start (standard epsilon scaling)
        // but reset assignment and re-bid; prices carry over
        // The loop above resets owner/assign but we want prices to persist.
        // Currently prices persist because we don't reset them. Good.
        // However the while(true) restarts the assignment phase with current prices. Good.
        // BUG: we reset owner at start of each phase but the first iteration also
        // wants a fresh assignment. That's correct for epsilon scaling.
    }

    for (int j = 0; j < n; ++j) {
        int i = owner[j];
        if (i < 0) return 2;
        col_for_row[i] = j;
    }
    return 0;
}

}
