// Forward auction with epsilon scaling (Bertsekas), Gauss-Seidel.
// Prices are kept across scaling phases (not reset), which is the standard
// and much faster formulation.
#include <cstdint>
#include <cstring>
#include <cmath>
#include <algorithm>
#include <vector>
#include <cstdio>

extern "C" {

int auction(const double* cost, int n, int* col_for_row, double eps_final, double eps_factor) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> unassigned(n);

    double cmax = 0.0;
    int step = std::max(1, n / 16);
    for (int i = 0; i < n; i += step)
        for (int j = 0; j < n; j += step)
            cmax = std::max(cmax, std::abs(cost[(size_t)i * n + j]));

    double eps = cmax;
    long long scans = 0;
    int phases = 0;

    while (true) {
        ++phases;
        // A person is "happy" if they hold an object within eps of their best.
        // We re-check everyone at the start of a phase because eps dropped,
        // but we keep prices and the current assignment.
        int nfree = 0;
        // mark rows that currently own something
        std::vector<char> has(n, 0);
        for (int j = 0; j < n; ++j) if (owner[j] >= 0) has[owner[j]] = 1;
        for (int i = 0; i < n; ++i) if (!has[i]) unassigned[nfree++] = i;

        int guard = 0;
        const int guard_max = n * 100;
        while (nfree > 0 && guard < guard_max) {
            ++guard;
            int new_nfree = 0;
            for (int k = 0; k < nfree; ++k) {
                int i = unassigned[k];
                const double* crow = cost + (size_t)i * n;
                double best = -1e300, second = -1e300;
                int bestj = 0;
                ++scans;
                for (int j = 0; j < n; ++j) {
                    double val = -crow[j] - price[j];
                    if (val > best) {
                        second = best;
                        best = val;
                        bestj = j;
                    } else if (val > second) {
                        second = val;
                    }
                }
                double bid = price[bestj] + (best - second) + eps;
                // bid is the new price
                int prev = owner[bestj];
                price[bestj] = bid;
                if (prev == i) {
                    // already ours; nothing
                    continue;
                }
                owner[bestj] = i;
                if (prev >= 0) unassigned[new_nfree++] = prev;
            }
            nfree = new_nfree;
        }
        if (nfree > 0) {
            std::fprintf(stderr, "FAILED phase %d eps %g nfree %d scans %lld\n", phases, eps, nfree, scans);
            return 1;
        }
        if (eps <= eps_final * 1.0001) break;
        double next = eps * eps_factor;
        if (next < eps_final) next = eps_final;
        eps = next;
    }

    std::fprintf(stderr, "phases=%d scans=%lld per_row=%.2f\n", phases, scans, (double)scans / n);
    for (int j = 0; j < n; ++j) {
        if (owner[j] < 0) return 2;
        col_for_row[owner[j]] = j;
    }
    return 0;
}

}
