// Epsilon-scaling forward auction with price-and-assignment warm start.
// Only bidders who violate epsilon-CS are re-auctioned after each scaling step.
#include <cstdint>
#include <cstring>
#include <cmath>
#include <algorithm>
#include <vector>
#include <cstdio>

extern "C" {

struct AuctionStats {
    int phases;
    long long scans;
    int rc;
};

static int run_auction(const double* cost, int n, int* col_for_row,
                       double eps_final, double eps_factor, AuctionStats* stats) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);     // column -> row
    std::vector<int> assign(n, -1);    // row -> column
    std::vector<int> unassigned(n);
    std::vector<char> mark(n, 0);

    double cmax = 0.0;
    int step = std::max(1, n / 16);
    for (int i = 0; i < n; i += step)
        for (int j = 0; j < n; j += step)
            cmax = std::max(cmax, std::abs(cost[(size_t)i * n + j]));
    if (cmax == 0.0) cmax = 1.0;

    double eps = cmax;
    long long scans = 0;
    int phases = 0;

    auto consider_free = [&](double eps_now, int& nfree) {
        nfree = 0;
        for (int i = 0; i < n; ++i) {
            int j_star = assign[i];
            if (j_star < 0) {
                unassigned[nfree++] = i;
                continue;
            }
            const double* crow = cost + (size_t)i * n;
            double profit_star = -crow[j_star] - price[j_star];
            double best = profit_star;
            ++scans;
            for (int j = 0; j < n; ++j) {
                double val = -crow[j] - price[j];
                if (val > best) best = val;
            }
            // unhappy if assigned profit is more than eps below the best
            if (profit_star < best - eps_now) {
                owner[j_star] = -1;
                assign[i] = -1;
                unassigned[nfree++] = i;
            }
        }
    };

    while (true) {
        ++phases;
        int nfree = 0;
        consider_free(eps, nfree);

        int guard = 0;
        const int guard_max = n * 200;
        while (nfree > 0 && guard < guard_max) {
            ++guard;
            int new_nfree = 0;
            for (int k = 0; k < nfree; ++k) {
                int i = unassigned[k];
                const double* crow = cost + (size_t)i * n;
                double best = -1e300, second = -1e300;
                int bestj = 0;
                ++scans;
                for (int j = 0; j < n; ++j) {
                    double val = -crow[j] - price[j];
                    if (val > best) {
                        second = best;
                        best = val;
                        bestj = j;
                    } else if (val > second) {
                        second = val;
                    }
                }
                double new_price = price[bestj] + (best - second) + eps;
                int prev = owner[bestj];
                price[bestj] = new_price;
                owner[bestj] = i;
                assign[i] = bestj;
                if (prev >= 0 && prev != i) {
                    assign[prev] = -1;
                    unassigned[new_nfree++] = prev;
                }
            }
            nfree = new_nfree;
        }
        if (nfree > 0) {
            if (stats) { stats->phases = phases; stats->scans = scans; stats->rc = 1; }
            return 1;
        }
        if (eps <= eps_final * 1.0001) break;
        double next = eps * eps_factor;
        if (next < eps_final) next = eps_final;
        if (next >= eps) break;
        eps = next;
    }

    if (stats) { stats->phases = phases; stats->scans = scans; stats->rc = 0; }
    for (int j = 0; j < n; ++j) {
        if (owner[j] < 0) return 2;
        col_for_row[owner[j]] = j;
    }
    return 0;
}

int auction(const double* cost, int n, int* col_for_row, double eps_final, double eps_factor) {
    AuctionStats st;
    int rc = run_auction(cost, n, col_for_row, eps_final, eps_factor, &st);
    std::fprintf(stderr, "phases=%d scans=%lld per_row=%.2f rc=%d\n",
                 st.phases, st.scans, (double)st.scans / n, rc);
    return rc;
}

}
