#include <cstdint>
#include <algorithm>
#include <vector>
#include <cmath>
#include <cstring>

extern "C" {

// cost is float (n*n). Assignment written to col_for_row (int32).
int auction_f(const float* cost, int n, int* col_for_row, float eps_final, int n_phases) {
    std::vector<float> price(n, 0.f);
    std::vector<int> owner(n);
    std::vector<int> unassigned(n);

    float cmax = 0.f;
    int step = std::max(1, n / 32);
    for (int i = 0; i < n; i += step)
        for (int j = 0; j < n; j += step)
            cmax = std::max(cmax, cost[(size_t)i * n + j]);
    float eps0 = cmax * 0.5f;
    float factor = 1.f;
    if (n_phases > 1) factor = std::pow(eps_final / eps0, 1.f / (n_phases - 1));
    float eps = eps0;

    for (int phase = 0; phase < n_phases; ++phase) {
        if (phase == n_phases - 1) eps = eps_final;
        for (int i = 0; i < n; ++i) { owner[i] = -1; unassigned[i] = i; }
        int nfree = n;
        int guard = 0;
        while (nfree > 0 && guard < n * 100) {
            ++guard;
            int new_nfree = 0;
            for (int kk = 0; kk < nfree; ++kk) {
                int i = unassigned[kk];
                const float* crow = cost + (size_t)i * n;
                float best = -1e30f, second = -1e30f;
                int bestj = 0;
                int j = 0;
                // unroll by 4
                for (; j + 3 < n; j += 4) {
                    float v0 = -crow[j] - price[j];
                    float v1 = -crow[j+1] - price[j+1];
                    float v2 = -crow[j+2] - price[j+2];
                    float v3 = -crow[j+3] - price[j+3];
                    #define CONSIDER(v, jj) \
                        if (v > best) { second = best; best = v; bestj = jj; } \
                        else if (v > second) { second = v; }
                    CONSIDER(v0, j)
                    CONSIDER(v1, j+1)
                    CONSIDER(v2, j+2)
                    CONSIDER(v3, j+3)
                    #undef CONSIDER
                }
                for (; j < n; ++j) {
                    float v = -crow[j] - price[j];
                    if (v > best) { second = best; best = v; bestj = j; }
                    else if (v > second) second = v;
                }
                price[bestj] += best - second + eps;
                int prev = owner[bestj];
                owner[bestj] = i;
                if (prev >= 0) unassigned[new_nfree++] = prev;
            }
            nfree = new_nfree;
        }
        if (nfree > 0) return 1;
        eps *= factor;
    }
    for (int j = 0; j < n; ++j) {
        int i = owner[j];
        if (i < 0) return 2;
        col_for_row[i] = j;
    }
    return 0;
}

}
