#include <cstdint>
#include <algorithm>
#include <cmath>
#include <vector>
#include <arm_neon.h>

// Find best and second-best of -(cost + price) over a row, NEON.
// Returns best, second, best index.
static inline void best_second(const double* __restrict crow,
                               const double* __restrict price,
                               int n, double& best, double& second, int& bestj) {
    // Process 2 doubles at a time (NEON float64x2).
    float64x2_t bestv = vdupq_n_f64(-1e300);
    float64x2_t secondv = vdupq_n_f64(-1e300);
    // We still need the index, so a pure vector max loses the argmax.
    // Use vectorized compare to skip, but argmax is inherently serial-ish.
    // Unrolled scalar with manual prefetch is often as fast. Do 4-way scalar
    // software pipelining instead, which clang schedules well.
    best = -1e300;
    second = -1e300;
    bestj = 0;
    int j = 0;
    for (; j + 4 <= n; j += 4) {
        double v0 = -crow[j] - price[j];
        double v1 = -crow[j+1] - price[j+1];
        double v2 = -crow[j+2] - price[j+2];
        double v3 = -crow[j+3] - price[j+3];
        // update in a branch-light way
        #define UPD(v, jj) \
            if (v > best) { second = best; best = v; bestj = jj; } \
            else if (v > second) { second = v; }
        UPD(v0, j) UPD(v1, j+1) UPD(v2, j+2) UPD(v3, j+3)
        #undef UPD
    }
