#include <cstdint>
#include <algorithm>
#include <cmath>
#include <vector>

static int run_phase(const double* cost, int n, std::vector<double>& price,
                     std::vector<int>& owner, std::vector<int>& assign,
                     std::vector<int>& unassigned, double eps, bool warm) {
    int nfree = 0;
    if (!warm) {
        for (int i = 0; i < n; ++i) { owner[i] = -1; assign[i] = -1; unassigned[nfree++] = i; }
    } else {
        for (int i = 0; i < n; ++i) {
            int js = assign[i];
            if (js < 0) { unassigned[nfree++] = i; continue; }
            const double* row = cost + (size_t)i * n;
            double profit = -row[js] - price[js];
            double best = profit;
            for (int j = 0; j < n; ++j) {
                double val = -row[j] - price[j];
                if (val > best) best = val;
            }
            if (profit < best - eps) {
                owner[js] = -1;
                assign[i] = -1;
                unassigned[nfree++] = i;
            }
        }
    }
    int guard = 0;
    const int limit = n * 400;
    while (nfree > 0 && guard < limit) {
        ++guard;
        int new_nfree = 0;
        for (int kk = 0; kk < nfree; ++kk) {
            int i = unassigned[kk];
            const double* row = cost + (size_t)i * n;
            double best = -1e300, second = -1e300;
            int bestj = 0;
            for (int j = 0; j < n; ++j) {
                double val = -row[j] - price[j];
                if (val > best) { second = best; best = val; bestj = j; }
                else if (val > second) second = val;
            }
            price[bestj] = price[bestj] + (best - second) + eps;
            int prev = owner[bestj];
            owner[bestj] = i;
            assign[i] = bestj;
            if (prev >= 0 && prev != i) {
                assign[prev] = -1;
                unassigned[new_nfree++] = prev;
            }
        }
        nfree = new_nfree;
    }
    return nfree; // 0 if converged
}

extern "C" int auction_solve(const double* cost, int n, int* col_for_row) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), assign(n, -1), unassigned(n);

    double cmax = 0.0;
    for (int i = 0; i < n; i += 4)
        for (int j = 0; j < n; j += 4)
            cmax = std::max(cmax, cost[(size_t)i * n + j]);
    if (cmax <= 0.0) cmax = 1.0;

    // 6 coarse phases down to 1e-5, warm-started, then up to 3 repair phases at 1e-9
    const int n_phases = 6;
    const double eps_final = 1e-5;
    double eps0 = std::max(cmax * 0.25, eps_final);
    double factor = std::pow(eps_final / eps0, 1.0 / (n_phases - 1));
    double eps = eps0;
    for (int phase = 0; phase < n_phases; ++phase) {
        if (phase == n_phases - 1) eps = eps_final;
        int left = run_phase(cost, n, price, owner, assign, unassigned, eps, /*warm=*/phase > 0);
        if (left > 0) return 1;
        eps *= factor;
    }
    for (int rnd = 0; rnd < 3; ++rnd) {
        int left = run_phase(cost, n, price, owner, assign, unassigned, 1e-9, /*warm=*/true);
        if (left > 0) return 2;
        // if nobody was unhappy, run_phase returns 0 immediately
        // detect a clean round: all assigned and no release happened. We can't see that
        // here, so just do a fixed 3 rounds; they're cheap when already happy.
    }
    for (int i = 0; i < n; ++i) {
        int j = assign[i];
        if (j < 0 || j >= n) return 3;
        col_for_row[i] = j;
    }
    return 0;
}
