// points: (n, d) row-major float32
// queries: (q, d) row-major float32

static inline float hsum256(__m256 v) {
    __m128 lo = _mm256_castps256_ps128(v);
    __m128 hi = _mm256_extractf128_ps(v, 1);
    lo = _mm_add_ps(lo, hi);
    __m128 sh = _mm_movehdup_ps(lo);
    lo = _mm_add_ps(lo, sh);
    sh = _mm_movehl_ps(sh, lo);
    lo = _mm_add_ss(lo, sh);
    return _mm_cvtss_f32(lo);
}

void knn(const float* points, int n, int d,
         const float* queries, int nq, int k,
         int32_t* out_idx, float* out_dist) {
    // blocked: for a panel of points, compute distances to a panel of queries
    const int QB = 32;
    const int PB = 256;
    std::vector<float> dist(QB * PB);
    std::vector<int> cand_count(nq, 0);
    // We'll keep a heap of size k per query: store worst distance and indices
    // Simple approach: accumulate all? too big. Use per-query max-heap of size k.
    struct Item { float d; int32_t i; };
    std::vector<Item> heaps(nq * k);
    std::vector<int> hsize(nq, 0);

    auto heap_up = [&](int q, int pos) {
        Item* h = &heaps[q * k];
        while (pos > 0) {
            int parent = (pos - 1) / 2;
            if (h[parent].d >= h[pos].d) break;
            std::swap(h[parent], h[pos]);
            pos = parent;
        }
    };
    auto heap_down = [&](int q, int pos, int sz) {
        Item* h = &heaps[q * k];
        while (true) {
            int l = pos*2+1, r = l+1, largest = pos;
            if (l < sz && h[l].d > h[largest].d) largest = l;
            if (r < sz && h[r].d > h[largest].d) largest = r;
            if (largest == pos) break;
            std::swap(h[pos], h[largest]);
            pos = largest;
        }
    };
    auto consider = [&](int q, float distv, int32_t idx) {
        int sz = hsize[q];
        Item* h = &heaps[q * k];
        if (sz < k) {
            h[sz] = {distv, idx};
            hsize[q] = sz + 1;
            heap_up(q, sz);
        } else if (distv < h[0].d) {
            h[0] = {distv, idx};
            heap_down(q, 0, k);
        }
    };

    for (int ps = 0; ps < n; ps += PB) {
        int pb = std::min(PB, n - ps);
        for (int qs = 0; qs < nq; qs += QB) {
            int qb = std::min(QB, nq - qs);
            // compute distances
            for (int qi = 0; qi < qb; ++qi) {
                const float* qv = queries + (qs + qi) * d;
                float* row = dist.data() + qi * PB;
                int pi = 0;
                // scalar for simplicity first? let's do a decent version
                for (; pi < pb; ++pi) {
                    const float* pv = points + (ps + pi) * d;
                    __m256 acc = _mm256_setzero_ps();
                    int di = 0;
                    for (; di + 8 <= d; di += 8) {
                        __m256 a = _mm256_loadu_ps(qv + di);
                        __m256 b = _mm256_loadu_ps(pv + di);
                        __m256 diff = _mm256_sub_ps(a, b);
                        acc = _mm256_fmadd_ps(diff, diff, acc);
                    }
                    float s = hsum256(acc);
                    for (; di < d; ++di) {
                        float diff = qv[di] - pv[di];
                        s += diff * diff;
                    }
                    row[pi] = s;
                }
            }
            // update heaps
            for (int qi = 0; qi < qb; ++qi) {
                float* row = dist.data() + qi * PB;
                int q = qs + qi;
                for (int pi = 0; pi < pb; ++pi) {
                    consider(q, row[pi], ps + pi);
                }
            }
