#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <immintrin.h>

typedef struct {
    const float* P;
    const float* Q;
    int n, d, nq, k;
    int q0, q1;
    int32_t* idx;
    float* dist;
} Job;

static inline float hsum(__m256 v) {
    __m128 lo = _mm256_castps256_ps128(v);
    __m128 hi = _mm256_extractf128_ps(v, 1);
    lo = _mm_add_ps(lo, hi);
    __m128 sh = _mm_movehdup_ps(lo);
    lo = _mm_add_ps(lo, sh);
    sh = _mm_movehl_ps(sh, lo);
    lo = _mm_add_ss(lo, sh);
    return _mm_cvtss_f32(lo);
}

static void insert(float* bd, int32_t* bi, int k, float s, int32_t id) {
    if (s >= bd[k-1]) return;
    int pos = k - 1;
    while (pos > 0 && s < bd[pos-1]) {
        bd[pos] = bd[pos-1];
        bi[pos] = bi[pos-1];
        pos--;
    }
    bd[pos] = s;
    bi[pos] = id;
}

static void* worker(void* arg) {
    Job* job = (Job*)arg;
    const float* P = job->P;
    const float* Q = job->Q;
    int n = job->n, d = job->d, k = job->k;
    int d8 = d & ~7;

    for (int q = job->q0; q < job->q1; ++q) {
        const float* qv = Q + (size_t)q * d;
        float bd[64];
        int32_t bi[64];
        for (int t = 0; t < k; ++t) { bd[t] = 1e30f; bi[t] = -1; }
        for (int i = 0; i < n; ++i) {
            const float* pv = P + (size_t)i * d;
            __m256 acc = _mm256_setzero_ps();
            int j = 0;
            for (; j < d8; j += 8) {
                __m256 diff = _mm256_sub_ps(_mm256_loadu_ps(qv + j), _mm256_loadu_ps(pv + j));
                acc = _mm256_fmadd_ps(diff, diff, acc);
            }
            float s = hsum(acc);
            for (; j < d; ++j) {
                float diff = qv[j] - pv[j];
                s += diff * diff;
            }
            insert(bd, bi, k, s, i);
        }
        for (int t = 0; t < k; ++t) {
            job->idx[(size_t)q * k + t] = bi[t];
            job->dist[(size_t)q * k + t] = bd[t];
        }
    }
    return NULL;
}

// 4-query worker
static void* worker4(void* arg) {
    Job* job = (Job*)arg;
    const float* P = job->P;
    const float* Q = job->Q;
    int n = job->n, d = job->d, k = job->k;
    int d8 = d & ~7;

    int q = job->q0;
    for (; q + 3 < job->q1; q += 4) {
        const float* q0 = Q + (size_t)(q+0) * d;
        const float* q1 = Q + (size_t)(q+1) * d;
        const float* q2 = Q + (size_t)(q+2) * d;
        const float* q3 = Q + (size_t)(q+3) * d;
        float bd[4][64];
        int32_t bi[4][64];
        for (int qi = 0; qi < 4; ++qi)
            for (int t = 0; t < k; ++t) { bd[qi][t] = 1e30f; bi[qi][t] = -1; }
        for (int i = 0; i < n; ++i) {
            const float* pv = P + (size_t)i * d;
            __m256 a0 = _mm256_setzero_ps();
            __m256 a1 = _mm256_setzero_ps();
            __m256 a2 = _mm256_setzero_ps();
            __m256 a3 = _mm256_setzero_ps();
            int j = 0;
            for (; j < d8; j += 8) {
                __m256 p = _mm256_loadu_ps(pv + j);
                __m256 d0 = _mm256_sub_ps(_mm256_loadu_ps(q0 + j), p);
                __m256 d1 = _mm256_sub_ps(_mm256_loadu_ps(q1 + j), p);
                __m256 d2 = _mm256_sub_ps(_mm256_loadu_ps(q2 + j), p);
                __m256 d3 = _mm256_sub_ps(_mm256_loadu_ps(q3 + j), p);
                a0 = _mm256_fmadd_ps(d0, d0, a0);
                a1 = _mm256_fmadd_ps(d1, d1, a1);
                a2 = _mm256_fmadd_ps(d2, d2, a2);
                a3 = _mm256_fmadd_ps(d3, d3, a3);
            }
            float s0 = hsum(a0), s1 = hsum(a1), s2 = hsum(a2), s3 = hsum(a3);
            for (; j < d; ++j) {
                float pvj = pv[j];
                float t0 = q0[j] - pvj; s0 += t0*t0;
                float t1 = q1[j] - pvj; s1 += t1*t1;
                float t2 = q2[j] - pvj; s2 += t2*t2;
                float t3 = q3[j] - pvj; s3 += t3*t3;
