    int q0, q1;
    int32_t* idx;
    float* dist;
    int variant;
} Job;

/* Variant A: 8 queries, accumulate 8 points in registers, sweep all dims. */
static void knn_vA(Job* job) {
    const int B = 8;
    const int n = job->n, d = job->d, d_pad = job->d_pad, n_pad = job->n_pad, k = job->k;
    const float* PT = job->PT;
    const float* Q = job->Q;

    for (int qs = job->q0; qs < job->q1; ) {
        int qb = job->q1 - qs;
        if (qb > B) qb = B;
        float bd[8][64];
        int32_t bi[8][64];
        for (int qi = 0; qi < qb; ++qi)
