                __m256 acc2 = _mm256_setzero_ps();
                __m256 acc3 = _mm256_setzero_ps();
                __m256 acc4 = _mm256_setzero_ps();
                __m256 acc5 = _mm256_setzero_ps();
                __m256 acc6 = _mm256_setzero_ps();
                __m256 acc7 = _mm256_setzero_ps();
                for (int j = 0; j < d; ++j) {
                    __m256 p = _mm256_loadu_ps(PT + (size_t)j * n_pad + pi);
                    __m256 q0 = _mm256_set1_ps(Q[(size_t)(qs + 0) * d + j]);
                    __m256 q1 = _mm256_set1_ps(Q[(size_t)(qs + 1) * d + j]);
                    __m256 q2 = _mm256_set1_ps(Q[(size_t)(qs + 2) * d + j]);
                    __m256 q3 = _mm256_set1_ps(Q[(size_t)(qs + 3) * d + j]);
                    __m256 q4 = _mm256_set1_ps(Q[(size_t)(qs + 4) * d + j]);
                    __m256 q5 = _mm256_set1_ps(Q[(size_t)(qs + 5) * d + j]);
                    __m256 q6 = _mm256_set1_ps(Q[(size_t)(qs + 6) * d + j]);
                    __m256 q7 = _mm256_set1_ps(Q[(size_t)(qs + 7) * d + j]);
                    __m256 d0 = _mm256_sub_ps(q0, p);
                    __m256 d1 = _mm256_sub_ps(q1, p);
                    __m256 d2 = _mm256_sub_ps(q2, p);
                    __m256 d3 = _mm256_sub_ps(q3, p);
                    __m256 d4 = _mm256_sub_ps(q4, p);
                    __m256 d5 = _mm256_sub_ps(q5, p);
                    __m256 d6 = _mm256_sub_ps(q6, p);
                    __m256 d7 = _mm256_sub_ps(q7, p);
                    acc0 = _mm256_fmadd_ps(d0, d0, acc0);
                    acc1 = _mm256_fmadd_ps(d1, d1, acc1);
                    acc2 = _mm256_fmadd_ps(d2, d2, acc2);
                    acc3 = _mm256_fmadd_ps(d3, d3, acc3);
                    acc4 = _mm256_fmadd_ps(d4, d4, acc4);
                    acc5 = _mm256_fmadd_ps(d5, d5, acc5);
                    acc6 = _mm256_fmadd_ps(d6, d6, acc6);
                    acc7 = _mm256_fmadd_ps(d7, d7, acc7);
                }
                float s[8][8];
                _mm256_storeu_ps(s[0], acc0);
                _mm256_storeu_ps(s[1], acc1);
                _mm256_storeu_ps(s[2], acc2);
                _mm256_storeu_ps(s[3], acc3);
                _mm256_storeu_ps(s[4], acc4);
                _mm256_storeu_ps(s[5], acc5);
                _mm256_storeu_ps(s[6], acc6);
                _mm256_storeu_ps(s[7], acc7);
                for (int qi = 0; qi < 8; ++qi)
                    for (int t = 0; t < 8 && pi + t < n; ++t)
                        insert_sorted(bd[qi], bi[qi], k, s[qi][t], pi + t);
            }
        } else {
            /* scalar tail queries */
            for (int qi = 0; qi < qb; ++qi) {
                const float* qv = Q + (size_t)(qs + qi) * d;
                for (int i = 0; i < n; ++i) {
                    float s = 0.f;
                    for (int j = 0; j < d; ++j) {
                        float diff = qv[j] - PT[(size_t)j * n_pad + i];
                        s += diff * diff;
                    }
                    insert_sorted(bd[qi], bi[qi], k, s, i);
                }
            }
        }
        for (int qi = 0; qi < qb; ++qi) {
            for (int t = 0; t < k; ++t) {
                job->idx[(size_t)(qs + qi) * k + t] = bi[qi][t];
                job->dist[(size_t)(qs + qi) * k + t] = bd[qi][t];
            }
        }
        qs += qb;
    }
}

/* Variant B: L1-resident acc, B queries x PB points, sweep dims then update heaps. */
static void knn_vB(Job* job, int B, int PB) {
    const int n = job->n, d = job->d, n_pad = job->n_pad, k = job->k;
    const float* PT = job->PT;
    const float* Q = job->Q;
    float* acc = (float*)malloc((size_t)B * PB * sizeof(float));

    for (int qs = job->q0; qs < job->q1; ) {
        int qb = job->q1 - qs;
        if (qb > B) qb = B;
        float bd[64][64];
        int32_t bi[64][64];
        for (int qi = 0; qi < qb; ++qi)
            for (int t = 0; t < k; ++t) { bd[qi][t] = 1e30f; bi[qi][t] = -1; }

        for (int ps = 0; ps < n; ps += PB) {
            int pb = n - ps;
            if (pb > PB) pb = PB;
            memset(acc, 0, (size_t)qb * PB * sizeof(float));
            for (int j = 0; j < d; ++j) {
                const float* prow = PT + (size_t)j * n_pad + ps;
                for (int qi = 0; qi < qb; ++qi) {
                    __m256 qv = _mm256_set1_ps(Q[(size_t)(qs + qi) * d + j]);
                    float* a = acc + (size_t)qi * PB;
                    int ii = 0;
                    for (; ii + 8 <= pb; ii += 8) {
                        __m256 p = _mm256_loadu_ps(prow + ii);
                        __m256 diff = _mm256_sub_ps(qv, p);
                        __m256 cur = _mm256_loadu_ps(a + ii);
                        cur = _mm256_fmadd_ps(diff, diff, cur);
                        _mm256_storeu_ps(a + ii, cur);
                    }
                    float qvs = Q[(size_t)(qs + qi) * d + j];
                    for (; ii < pb; ++ii) {
                        float diff = qvs - prow[ii];
                        a[ii] += diff * diff;
                    }
                }
            }
            for (int qi = 0; qi < qb; ++qi) {
                float* a = acc + (size_t)qi * PB;
                for (int ii = 0; ii < pb; ++ii)
                    insert_sorted(bd[qi], bi[qi], k, a[ii], ps + ii);
            }
        }
        for (int qi = 0; qi < qb; ++qi)
            for (int t = 0; t < k; ++t) {
                job->idx[(size_t)(qs + qi) * k + t] = bi[qi][t];
                job->dist[(size_t)(qs + qi) * k + t] = bd[qi][t];
            }
        qs += qb;
    }
    free(acc);
}

static void* worker(void* arg) {
    Job* job = (Job*)arg;
    if (job->variant == 0) knn_vA(job);
    else if (job->variant == 1) knn_vB(job, 16, 256);
    else if (job->variant == 2) knn_vB(job, 32, 128);
    else if (job->variant == 3) knn_vB(job, 8, 512);
    else if (job->variant == 4) knn_vB(job, 16, 128);
    else if (job->variant == 5) knn_vB(job, 32, 256);
    else if (job->variant == 6) knn_vB(job, 64, 64);
    return NULL;
}

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main(int argc, char** argv) {
    int n = 19800, nq = 1980, d = 99, k = 10;
    int nthreads = argc > 1 ? atoi(argv[1]) : 6;
    int variant = argc > 2 ? atoi(argv[2]) : 0;

    int d_pad = (d + 7) & ~7;
    int n_pad = (n + 7) & ~7;

    float *P = NULL, *Q = NULL, *PT = NULL;
    posix_memalign((void**)&P, 64, (size_t)n * d * sizeof(float));
    posix_memalign((void**)&Q, 64, (size_t)nq * d * sizeof(float));
    posix_memalign((void**)&PT, 64, (size_t)d_pad * n_pad * sizeof(float));
    int32_t* idx = (int32_t*)malloc((size_t)nq * k * sizeof(int32_t));
    float* dist = (float*)malloc((size_t)nq * k * sizeof(float));
    srand(1);
    for (size_t i = 0; i < (size_t)n * d; ++i) P[i] = (float)rand() / RAND_MAX;
    for (size_t i = 0; i < (size_t)nq * d; ++i) Q[i] = (float)rand() / RAND_MAX;
    memset(PT, 0, (size_t)d_pad * n_pad * sizeof(float));
    double ttr = now();
    for (int j = 0; j < d; ++j)
        for (int i = 0; i < n; ++i)
            PT[(size_t)j * n_pad + i] = P[(size_t)i * d + j];
    double ttr1 = now();

    pthread_t th[32];
    Job jobs[32];
    int chunk = (nq + nthreads - 1) / nthreads;
    /* align chunk */
    int align = (variant == 0) ? 8 : 16;
    if (chunk % align) chunk += align - chunk % align;

    double t0 = now();
    int nt = 0;
    for (int q = 0; q < nq; q += chunk) {
        int q1 = q + chunk;
        if (q1 > nq) q1 = nq;
        jobs[nt] = (Job){PT, Q, n, d, d_pad, n_pad, k, q, q1, idx, dist, variant};
        pthread_create(&th[nt], NULL, worker, &jobs[nt]);
        nt++;
    }
    for (int i = 0; i < nt; ++i) pthread_join(th[i], NULL);
    printf("var %d threads %d transpose %.4f search %.4f checksum ", variant, nt, ttr1 - ttr, now() - t0);
    double s = 0;
    for (int i = 0; i < nq * k; i += 97) s += dist[i];
    printf("%f\n", s);
    return 0;
}
