#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <immintrin.h>

static inline void ins(float* bd, int32_t* bi, int k, float s, int32_t id) {
    if (s >= bd[k-1]) return;
    int pos = k-1;
    while (pos > 0 && s < bd[pos-1]) { bd[pos]=bd[pos-1]; bi[pos]=bi[pos-1]; --pos; }
    bd[pos]=s; bi[pos]=id;
}

/* P is row-major (n, d). Each thread owns a query range and scans point panels.
   For a panel of PB points and B queries, distances are accumulated with the
   point panel kept in L2 and the query block in L1. */

typedef struct {
    const float* P;
    const float* Q;
    int n, d, k, q0, q1, PB;
    int32_t* idx;
    float* dist;
} Job;

static void* worker(void* arg) {
    Job* job = (Job*)arg;
    int n = job->n, d = job->d, k = job->k, PB = job->PB;
    int B = 16; /* queries per inner tile */
    int qbase = job->q0;
    int nq_local = job->q1 - job->q0;

    float* bd = (float*)malloc((size_t)nq_local * k * sizeof(float));
    int32_t* bi = (int32_t*)malloc((size_t)nq_local * k * sizeof(int32_t));
    for (int i = 0; i < nq_local * k; ++i) { bd[i] = 1e30f; bi[i] = -1; }

    float* panel = (float*)malloc((size_t)PB * d * sizeof(float)); /* optional copy */
    float* acc = (float*)malloc((size_t)B * PB * sizeof(float));

    for (int ps = 0; ps < n; ps += PB) {
        int pb = n - ps; if (pb > PB) pb = PB;
        const float* Ppanel = job->P + (size_t)ps * d;
        for (int qs = 0; qs < nq_local; qs += B) {
            int qb = nq_local - qs; if (qb > B) qb = B;
            memset(acc, 0, (size_t)qb * PB * sizeof(float));
            for (int qi = 0; qi < qb; ++qi) {
                const float* qv = job->Q + (size_t)(qbase + qs + qi) * d;
                float* a = acc + (size_t)qi * PB;
                for (int pi = 0; pi < pb; ++pi) {
                    const float* pv = Ppanel + (size_t)pi * d;
                    __m256 accv = _mm256_setzero_ps();
                    int j = 0;
                    int d8 = d & ~7;
                    for (; j < d8; j += 8) {
                        __m256 diff = _mm256_sub_ps(_mm256_loadu_ps(qv + j), _mm256_loadu_ps(pv + j));
                        accv = _mm256_fmadd_ps(diff, diff, accv);
                    }
                    __m128 lo = _mm256_castps256_ps128(accv);
                    __m128 hi = _mm256_extractf128_ps(accv, 1);
                    lo = _mm_add_ps(lo, hi);
                    __m128 sh = _mm_movehdup_ps(lo);
                    lo = _mm_add_ps(lo, sh);
                    sh = _mm_movehl_ps(sh, lo);
                    lo = _mm_add_ss(lo, sh);
                    float s = _mm_cvtss_f32(lo);
                    for (; j < d; ++j) { float df = qv[j] - pv[j]; s += df * df; }
                    a[pi] = s;
                }
            }
            for (int qi = 0; qi < qb; ++qi) {
                float* a = acc + (size_t)qi * PB;
                float* bdr = bd + (size_t)(qs + qi) * k;
                int32_t* bir = bi + (size_t)(qs + qi) * k;
                for (int pi = 0; pi < pb; ++pi) ins(bdr, bir, k, a[pi], ps + pi);
            }
        }
    }
    for (int qi = 0; qi < nq_local; ++qi) {
        int q = qbase + qi;
        for (int t = 0; t < k; ++t) {
            job->idx[(size_t)q * k + t] = bi[(size_t)qi * k + t];
            job->dist[(size_t)q * k + t] = bd[(size_t)qi * k + t];
        }
    }
    free(bd); free(bi); free(panel); free(acc);
    return NULL;
}

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

int main(int argc, char** argv) {
    int n=19800,nq=1980,d=99,k=10;
    int nthreads=argc>1?atoi(argv[1]):6;
    int PB=argc>2?atoi(argv[2]):64;
    float *P=NULL,*Q=NULL;
    posix_memalign((void**)&P,64,(size_t)n*d*4);
    posix_memalign((void**)&Q,64,(size_t)nq*d*4);
    int32_t* idx=malloc((size_t)nq*k*4);
    float* dist=malloc((size_t)nq*k*4);
    srand(1);
    for(size_t i=0;i<(size_t)n*d;++i) P[i]=(float)rand()/RAND_MAX;
    for(size_t i=0;i<(size_t)nq*d;++i) Q[i]=(float)rand()/RAND_MAX;
    pthread_t th[32]; Job jobs[32];
    int chunk=(nq+nthreads-1)/nthreads;
    double t0=now(); int nt=0;
    for(int q=0;q<nq;q+=chunk){
        int q1=q+chunk; if(q1>nq) q1=nq;
        jobs[nt]=(Job){P,Q,n,d,k,q,q1,PB,idx,dist};
        pthread_create(&th[nt],NULL,worker,&jobs[nt]); nt++;
    }
    for(int i=0;i<nt;++i) pthread_join(th[i],NULL);
    double s=0; for(int i=0;i<nq*k;i+=97) s+=dist[i];
    printf("threads %d PB %d time %.4f checksum %f\n", nt, PB, now()-t0, s);
}
