    for (; q+1<job->q1; q+=2) {
        /* build LUTs for 2 queries: lut[j*256 + c] */
        float* lut0 = (float*)malloc((size_t)d*256*4);
        float* lut1 = (float*)malloc((size_t)d*256*4);
        const float* q0 = job->Q + (size_t)q*d;
        const float* q1 = job->Q + (size_t)(q+1)*d;
        for (int j=0;j<d;++j) {
            float qv0=q0[j], qv1=q1[j];
            float* L0=lut0+(size_t)j*256;
            float* L1=lut1+(size_t)j*256;
            for (int c=0;c<256;++c) {
                float pv = bias + c*scale;
                float d0=qv0-pv; L0[c]=d0*d0;
                float d1=qv1-pv; L1[c]=d1*d1;
            }
