#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <immintrin.h>

static inline float hsum(__m256 v) {
    __m128 lo = _mm256_castps256_ps128(v);
    __m128 hi = _mm256_extractf128_ps(v, 1);
    lo = _mm_add_ps(lo, hi);
    __m128 sh = _mm_movehdup_ps(lo);
    lo = _mm_add_ps(lo, sh);
    sh = _mm_movehl_ps(sh, lo);
    lo = _mm_add_ss(lo, sh);
    return _mm_cvtss_f32(lo);
}

static inline void insert_sorted(float* bd, int32_t* bi, int k, float s, int32_t id) {
    if (s >= bd[k - 1]) return;
    int pos = k - 1;
    while (pos > 0 && s < bd[pos - 1]) {
        bd[pos] = bd[pos - 1];
        bi[pos] = bi[pos - 1];
        --pos;
    }
    bd[pos] = s;
    bi[pos] = id;
}

typedef struct {
    const float* P;
    const float* Q;
    int n, d, k, q0, q1;
    int32_t* idx;
    float* dist;
} Job;

static void process_one(Job* job, int q) {
    const float* qv = job->Q + (size_t)q * job->d;
    int n = job->n, d = job->d, k = job->k;
    int d8 = d & ~7;
    float bd[64];
    int32_t bi[64];
    for (int t = 0; t < k; ++t) { bd[t] = 1e30f; bi[t] = -1; }
    for (int i = 0; i < n; ++i) {
        const float* pv = job->P + (size_t)i * d;
        __m256 acc = _mm256_setzero_ps();
        int j = 0;
        for (; j < d8; j += 8) {
            __m256 diff = _mm256_sub_ps(_mm256_loadu_ps(qv + j), _mm256_loadu_ps(pv + j));
            acc = _mm256_fmadd_ps(diff, diff, acc);
        }
        float s = hsum(acc);
        for (; j < d; ++j) {
            float diff = qv[j] - pv[j];
            s += diff * diff;
        }
        insert_sorted(bd, bi, k, s, i);
    }
    for (int t = 0; t < k; ++t) {
        job->idx[(size_t)q * k + t] = bi[t];
        job->dist[(size_t)q * k + t] = bd[t];
    }
}

/* Four queries share each loaded point. k must be <= 64. */
static void* worker4(void* arg) {
    Job* job = (Job*)arg;
    const float* P = job->P;
    const float* Q = job->Q;
    int n = job->n, d = job->d, k = job->k;
    int d8 = d & ~7;
    int q = job->q0;
    for (; q + 3 < job->q1; q += 4) {
        const float* q0 = Q + (size_t)(q + 0) * d;
        const float* q1 = Q + (size_t)(q + 1) * d;
        const float* q2 = Q + (size_t)(q + 2) * d;
        const float* q3 = Q + (size_t)(q + 3) * d;
        float bd0[64], bd1[64], bd2[64], bd3[64];
        int32_t bi0[64], bi1[64], bi2[64], bi3[64];
        for (int t = 0; t < k; ++t) {
            bd0[t] = bd1[t] = bd2[t] = bd3[t] = 1e30f;
            bi0[t] = bi1[t] = bi2[t] = bi3[t] = -1;
        }
        for (int i = 0; i < n; ++i) {
            const float* pv = P + (size_t)i * d;
            __m256 a0 = _mm256_setzero_ps();
            __m256 a1 = _mm256_setzero_ps();
            __m256 a2 = _mm256_setzero_ps();
            __m256 a3 = _mm256_setzero_ps();
            int j = 0;
            for (; j < d8; j += 8) {
                __m256 p = _mm256_loadu_ps(pv + j);
                __m256 d0 = _mm256_sub_ps(_mm256_loadu_ps(q0 + j), p);
                __m256 d1 = _mm256_sub_ps(_mm256_loadu_ps(q1 + j), p);
                __m256 d2 = _mm256_sub_ps(_mm256_loadu_ps(q2 + j), p);
                __m256 d3 = _mm256_sub_ps(_mm256_loadu_ps(q3 + j), p);
                a0 = _mm256_fmadd_ps(d0, d0, a0);
                a1 = _mm256_fmadd_ps(d1, d1, a1);
                a2 = _mm256_fmadd_ps(d2, d2, a2);
                a3 = _mm256_fmadd_ps(d3, d3, a3);
            }
            float s0 = hsum(a0), s1 = hsum(a1), s2 = hsum(a2), s3 = hsum(a3);
            for (; j < d; ++j) {
                float pvj = pv[j];
                float t0 = q0[j] - pvj; s0 += t0 * t0;
                float t1 = q1[j] - pvj; s1 += t1 * t1;
                float t2 = q2[j] - pvj; s2 += t2 * t2;
                float t3 = q3[j] - pvj; s3 += t3 * t3;
            }
            insert_sorted(bd0, bi0, k, s0, i);
            insert_sorted(bd1, bi1, k, s1, i);
            insert_sorted(bd2, bi2, k, s2, i);
            insert_sorted(bd3, bi3, k, s3, i);
        }
        for (int t = 0; t < k; ++t) {
            job->idx[(size_t)(q + 0) * k + t] = bi0[t];
            job->idx[(size_t)(q + 1) * k + t] = bi1[t];
            job->idx[(size_t)(q + 2) * k + t] = bi2[t];
            job->idx[(size_t)(q + 3) * k + t] = bi3[t];
            job->dist[(size_t)(q + 0) * k + t] = bd0[t];
            job->dist[(size_t)(q + 1) * k + t] = bd1[t];
            job->dist[(size_t)(q + 2) * k + t] = bd2[t];
            job->dist[(size_t)(q + 3) * k + t] = bd3[t];
        }
    }
    for (; q < job->q1; ++q) process_one(job, q);
    return NULL;
}

void knn_l2(const float* P, const float* Q, int n, int nq, int d, int k,
            int32_t* idx, float* dist, int nthreads) {
    if (nq <= 0 || k <= 0 || n <= 0) return;
    if (k > 64) k = 64;
    if (nthreads < 1) nthreads = 1;
    if (nthreads > 32) nthreads = 32;
    if (nthreads > nq) nthreads = nq;

    pthread_t th[32];
    Job jobs[32];
    int chunk = (nq + nthreads - 1) / nthreads;
    if (chunk % 4) chunk += 4 - (chunk % 4);
    int nt = 0;
    for (int q = 0; q < nq; q += chunk) {
        int q1 = q + chunk;
        if (q1 > nq) q1 = nq;
        jobs[nt] = (Job){P, Q, n, d, k, q, q1, idx, dist};
        nt++;
    }
    for (int i = 1; i < nt; ++i) pthread_create(&th[i], NULL, worker4, &jobs[i]);
    worker4(&jobs[0]);
    for (int i = 1; i < nt; ++i) pthread_join(th[i], NULL);
}
