#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <immintrin.h>

static inline void ins(float* bd, int32_t* bi, int k, float s, int32_t id) {
    if (s >= bd[k-1]) return;
    int pos = k-1;
    while (pos > 0 && s < bd[pos-1]) { bd[pos]=bd[pos-1]; bi[pos]=bi[pos-1]; --pos; }
    bd[pos]=s; bi[pos]=id;
}

static inline int hsum_epi32(__m256i v) {
    __m128i lo = _mm256_castsi256_si128(v);
    __m128i hi = _mm256_extracti128_si256(v, 1);
    lo = _mm_add_epi32(lo, hi);
    lo = _mm_add_epi32(lo, _mm_shuffle_epi32(lo, 0x4e));
    lo = _mm_add_epi32(lo, _mm_shuffle_epi32(lo, 0xb1));
    return _mm_cvtsi128_si32(lo);
}

/* Squared L2 over uint8 via (a-b)^2 = a^2 + b^2 - 2ab, with a,b in 0..255.
   For a fixed query, q2 = sum q[j]^2 is constant. p2 can be precomputed.
   ab = sum q[j]*p[j]. Then dist = q2 + p2 - 2*ab.
   Dot product of uint8: use pmaddubsw? q and p both unsigned. 
   _mm256_maddubs_epi16 treats a as unsigned, b as signed. So store query as int8? values up to 255 don't fit in int8.
   Use pmaddwd on unpacked 16-bit. 16-bit unpack of 16 bytes -> 2 ymm. */

typedef struct {
    const uint8_t* P;
    const uint8_t* Q;
    const int32_t* p2; /* sum of squares per point */
    int n, d, k, q0, q1;
    int32_t* idx;
    float* dist;
} Job;

static void* worker(void* arg) {
    Job* job=(Job*)arg;
    int n=job->n, d=job->d, k=job->k;
    int d16 = d & ~15;
    int q = job->q0;
    for (; q+1 < job->q1; q+=2) {
        const uint8_t* q0 = job->Q + (size_t)q*d;
        const uint8_t* q1 = job->Q + (size_t)(q+1)*d;
        int q2_0=0, q2_1=0;
        for (int j=0;j<d;++j){ q2_0 += q0[j]*q0[j]; q2_1 += q1[j]*q1[j]; }
        float bd0[64], bd1[64];
        int32_t bi0[64], bi1[64];
        for (int t=0;t<k;++t){ bd0[t]=bd1[t]=1e30f; bi0[t]=bi1[t]=-1; }
        for (int i=0;i<n;++i) {
            const uint8_t* pv = job->P + (size_t)i*d;
            __m256i dot0 = _mm256_setzero_si256();
            __m256i dot1 = _mm256_setzero_si256();
            int j=0;
            for (; j<d16; j+=16) {
                __m128i p8 = _mm_loadu_si128((const __m128i*)(pv+j));
                __m128i a8 = _mm_loadu_si128((const __m128i*)(q0+j));
                __m128i b8 = _mm_loadu_si128((const __m128i*)(q1+j));
                __m256i p16 = _mm256_cvtepu8_epi16(p8);
                __m256i a16 = _mm256_cvtepu8_epi16(a8);
                __m256i b16 = _mm256_cvtepu8_epi16(b8);
                __m256i pa = _mm256_madd_epi16(p16, a16);
                __m256i pb = _mm256_madd_epi16(p16, b16);
                dot0 = _mm256_add_epi32(dot0, pa);
                dot1 = _mm256_add_epi32(dot1, pb);
            }
            int ab0 = hsum_epi32(dot0);
