static void* worker(void* arg) {
    Job* job=(Job*)arg;
    int n=job->n, d=job->d, k=job->k;
    int d8=d & ~7;
    int q=job->q0;
    for (; q+3<job->q1; q+=4) {
        const float* qv[4];
        for (int qi=0; qi<4; ++qi) qv[qi]=job->Q+(size_t)(q+qi)*d;
        float bd[4][16]; int32_t bi[4][16];
        for (int qi=0; qi<4; ++qi) for (int t=0;t<k;++t){ bd[qi][t]=1e30f; bi[qi][t]=-1; }
        for (int i=0;i<n;++i) {
            const uint16_t* pv=job->P+(size_t)i*d;
            __m256 a0=_mm256_setzero_ps(), a1=_mm256_setzero_ps(), a2=_mm256_setzero_ps(), a3=_mm256_setzero_ps();
            int j=0;
            for (; j<d8; j+=8) {
                __m128i h=_mm_loadu_si128((const __m128i*)(pv+j));
                __m256 p=_mm256_cvtph_ps(h);
                __m256 d0=_mm256_sub_ps(_mm256_loadu_ps(qv[0]+j), p);
                __m256 d1=_mm256_sub_ps(_mm256_loadu_ps(qv[1]+j), p);
                __m256 d2=_mm256_sub_ps(_mm256_loadu_ps(qv[2]+j), p);
                __m256 d3=_mm256_sub_ps(_mm256_loadu_ps(qv[3]+j), p);
