    lo = _mm_add_epi32(lo, _mm_shuffle_epi32(lo, 0xb1));
    return _mm_cvtsi128_si32(lo);
}

/* For each query keep an unsorted top-C buffer + max. */
#define C 32
#define B 16

typedef struct {
    const uint8_t* P;
    const uint8_t* Q;
    const int32_t* p2;
    int n, d, q0, q1;
    int32_t* idx; /* (nq, C) */
} Job;

static inline void consider(int32_t* bi, int32_t* bd, int* worst, int* worst_pos, int s, int id) {
    if (s >= *worst) return;
    bd[*worst_pos] = s;
    bi[*worst_pos] = id;
    int w = bd[0], wp = 0;
    for (int t = 1; t < C; ++t) if (bd[t] > w) { w = bd[t]; wp = t; }
    *worst = w; *worst_pos = wp;
}

static void* worker(void* arg) {
    Job* job = (Job*)arg;
    int n = job->n, d = job->d;
    int d16 = d & ~15;
    int nq_local = job->q1 - job->q0;

    int32_t* best_d = (int32_t*)malloc((size_t)nq_local * C * sizeof(int32_t));
    int32_t* best_i = (int32_t*)malloc((size_t)nq_local * C * sizeof(int32_t));
    int* worst = (int*)malloc((size_t)nq_local * sizeof(int));
    int* worst_pos = (int*)malloc((size_t)nq_local * sizeof(int));
    for (int i = 0; i < nq_local * C; ++i) { best_d[i] = 0x7fffffff; best_i[i] = -1; }
    for (int i = 0; i < nq_local; ++i) { worst[i] = 0x7fffffff; worst_pos[i] = 0; }

    int32_t q2[4096];
    for (int qi = 0; qi < nq_local; ++qi) {
        const uint8_t* qv = job->Q + (size_t)(job->q0 + qi) * d;
        int s = 0;
        for (int j = 0; j < d; ++j) s += qv[j] * qv[j];
        q2[qi] = s;
    }

    for (int qs = 0; qs < nq_local; qs += B) {
        int qb = nq_local - qs; if (qb > B) qb = B;
        const uint8_t* qv[B];
        for (int qi = 0; qi < qb; ++qi) qv[qi] = job->Q + (size_t)(job->q0 + qs + qi) * d;

        for (int i = 0; i < n; ++i) {
            const uint8_t* pv = job->P + (size_t)i * d;
            __m256i dot[B];
            for (int qi = 0; qi < qb; ++qi) dot[qi] = _mm256_setzero_si256();
            int j = 0;
            for (; j < d16; j += 16) {
                __m256i p16 = _mm256_cvtepu8_epi16(_mm_loadu_si128((const __m128i*)(pv + j)));
                for (int qi = 0; qi < qb; ++qi) {
                    __m256i a16 = _mm256_cvtepu8_epi16(_mm_loadu_si128((const __m128i*)(qv[qi] + j)));
                    dot[qi] = _mm256_add_epi32(dot[qi], _mm256_madd_epi16(p16, a16));
                }
            }
            int ab[B];
            for (int qi = 0; qi < qb; ++qi) ab[qi] = hsum_epi32(dot[qi]);
            for (; j < d; ++j) {
                int p = pv[j];
                for (int qi = 0; qi < qb; ++qi) ab[qi] += p * qv[qi][j];
            }
            int p2 = job->p2[i];
            for (int qi = 0; qi < qb; ++qi) {
                int s = q2[qs + qi] + p2 - 2 * ab[qi];
                consider(best_i + (qs + qi) * C, best_d + (qs + qi) * C,
                         &worst[qs + qi], &worst_pos[qs + qi], s, i);
            }
        }
    }
    for (int qi = 0; qi < nq_local; ++qi)
        for (int t = 0; t < C; ++t)
            job->idx[(size_t)(job->q0 + qi) * C + t] = best_i[qi * C + t];
    free(best_d); free(best_i); free(worst); free(worst_pos);
    return NULL;
}

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

int main(int argc, char** argv) {
    int n=19800, nq=1980, d=99, nthreads=argc>1?atoi(argv[1]):12;
    uint8_t *P=malloc((size_t)n*d), *Q=malloc((size_t)nq*d);
