#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <immintrin.h>

static inline float hsum(__m256 v) {
    __m128 lo=_mm256_castps256_ps128(v);
    __m128 hi=_mm256_extractf128_ps(v,1);
    lo=_mm_add_ps(lo,hi);
    __m128 sh=_mm_movehdup_ps(lo);
    lo=_mm_add_ps(lo,sh);
    sh=_mm_movehl_ps(sh,lo);
    lo=_mm_add_ss(lo,sh);
    return _mm_cvtss_f32(lo);
}
static inline void ins(float* bd, int32_t* bi, int cap, float s, int32_t id) {
    if (s >= bd[cap-1]) return;
    int pos=cap-1;
    while (pos>0 && s<bd[pos-1]) { bd[pos]=bd[pos-1]; bi[pos]=bi[pos-1]; --pos; }
    bd[pos]=s; bi[pos]=id;
}

typedef struct {
    const float* P; const float* Q;
    int n,d,k,q0,q1,m,cap;
    int32_t* idx; float* dist;
} Job;

static void* worker(void* arg) {
    Job* job=(Job*)arg;
    int n=job->n, d=job->d, k=job->k, m=job->m, cap=job->cap;
    int m8=m & ~7;
    int d8=d & ~7;
    int q=job->q0;
    for (; q+3<job->q1; q+=4) {
        const float* qv[4];
        for (int qi=0; qi<4; ++qi) qv[qi]=job->Q+(size_t)(q+qi)*d;
        float cbd[4][256];
        int32_t cbi[4][256];
        for (int qi=0; qi<4; ++qi) for (int t=0;t<cap;++t){ cbd[qi][t]=1e30f; cbi[qi][t]=-1; }

        /* pass 1: partial distance over first m dims, keep cap */
        for (int i=0;i<n;++i) {
            const float* pv=job->P+(size_t)i*d;
            __m256 a0=_mm256_setzero_ps(),a1=_mm256_setzero_ps(),a2=_mm256_setzero_ps(),a3=_mm256_setzero_ps();
            int j=0;
            for (; j<m8; j+=8) {
                __m256 p=_mm256_loadu_ps(pv+j);
                __m256 d0=_mm256_sub_ps(_mm256_loadu_ps(qv[0]+j),p);
                __m256 d1=_mm256_sub_ps(_mm256_loadu_ps(qv[1]+j),p);
                __m256 d2=_mm256_sub_ps(_mm256_loadu_ps(qv[2]+j),p);
                __m256 d3=_mm256_sub_ps(_mm256_loadu_ps(qv[3]+j),p);
                a0=_mm256_fmadd_ps(d0,d0,a0); a1=_mm256_fmadd_ps(d1,d1,a1);
                a2=_mm256_fmadd_ps(d2,d2,a2); a3=_mm256_fmadd_ps(d3,d3,a3);
            }
            float s0=hsum(a0),s1=hsum(a1),s2=hsum(a2),s3=hsum(a3);
            for (; j<m; ++j) {
                float pvj=pv[j];
                float t; t=qv[0][j]-pvj; s0+=t*t; t=qv[1][j]-pvj; s1+=t*t;
                t=qv[2][j]-pvj; s2+=t*t; t=qv[3][j]-pvj; s3+=t*t;
            }
            ins(cbd[0],cbi[0],cap,s0,i);
            ins(cbd[1],cbi[1],cap,s1,i);
            ins(cbd[2],cbi[2],cap,s2,i);
            ins(cbd[3],cbi[3],cap,s3,i);
        }
        /* pass 2: full distance on candidates */
        float bd[4][16]; int32_t bi[4][16];
        for (int qi=0; qi<4; ++qi) for (int t=0;t<k;++t){ bd[qi][t]=1e30f; bi[qi][t]=-1; }
        for (int qi=0; qi<4; ++qi) {
            for (int c=0; c<cap; ++c) {
                int i=cbi[qi][c];
                if (i<0) continue;
                const float* pv=job->P+(size_t)i*d;
                __m256 acc=_mm256_setzero_ps();
                int j=0;
                for (; j<d8; j+=8) {
                    __m256 diff=_mm256_sub_ps(_mm256_loadu_ps(qv[qi]+j), _mm256_loadu_ps(pv+j));
                    acc=_mm256_fmadd_ps(diff,diff,acc);
                }
