                for (; j<d; ++j) { float t=qv[qi][j]-pv[j]; s+=t*t; }
                ins(bd[qi], bi[qi], k, s, i);
            }
        }
        for (int qi=0; qi<4; ++qi) for (int t=0;t<k;++t) {
            job->idx[(size_t)(q+qi)*k+t]=bi[qi][t];
            job->dist[(size_t)(q+qi)*k+t]=bd[qi][t];
        }
    }
    return NULL;
}
