import numpy as np, faiss
np.random.seed(0)
n, nq, d, k = 19800, 200, 99, 10
P = np.random.uniform(0,1,(n,d)).astype(np.float32)
Q = np.random.uniform(0,1,(nq,d)).astype(np.float32)
index = faiss.IndexFlatL2(d); index.add(P)
D, I = index.search(Q, k)

def recall(m, cap):
    # partial distance on first m dims
    part = np.sum((Q[:, None, :m] - P[None, :, :m])**2, axis=2)
    sel = np.argpartition(part, cap-1, axis=1)[:, :cap]
    # fraction of true neighbors contained
    contained = 0
    for q in range(nq):
        contained += np.isin(I[q], sel[q]).sum()
    return contained / (nq*k)

for m in (16, 24, 32, 40, 48, 64):
    for cap in (32, 64, 128, 256, 512, 1024, 2048):
        r = recall(m, cap)
        if r >= 0.99:
            print(f"m={m:2d} cap={cap:4d} recall={r:.4f}")
            break
    else:
        print(f"m={m:2d} no cap<=2048 reaches 0.99, best {recall(m,2048):.4f}")
