    const uint8_t* PT; /* (d, n_pad) */
    const int16_t* Q16;
    const int32_t* p2;
    const int32_t* q2;
    int n, n_pad, d, q0, q1;
    int32_t* idx;
} Job;

static void* worker(void* arg) {
    Job* job=(Job*)arg;
    int n=job->n, d=job->d, n_pad=job->n_pad;
    int q=job->q0;
    /* one query at a time but 16 points per inner step, vectorized over points */
    for (; q < job->q1; ++q) {
        const int16_t* qv = job->Q16 + (size_t)q * d;
        int32_t qq = job->q2[q];
        int32_t bd[K]; int32_t bi[K];
        for (int t=0;t<K;++t){ bd[t]=0x7fffffff; bi[t]=-1; }
        for (int ps=0; ps<n; ps+=PB) {
            int32_t acc[PB];
            for (int t=0;t<PB;++t) acc[t]=0;
            for (int j=0;j<d;++j) {
                int qj = qv[j];
                const uint8_t* row = job->PT + (size_t)j * n_pad + ps;
                /* scalar 16-wide, compiler should vectorize */
                for (int t=0;t<PB;++t) acc[t] += qj * row[t];
            }
            int pe = ps + PB; if (pe > n) pe = n;
            for (int t=0; t<pe-ps; ++t) {
                int s = qq + job->p2[ps+t] - 2*acc[t];
                ins(bd, bi, K, s, ps+t);
            }
        }
        for (int t=0;t<K;++t) job->idx[(size_t)q*K+t] = bi[t];
    }
    return NULL;
}

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

int main(int argc, char** argv){
    int n=19800, nq=1980, d=99, nthreads=argc>1?atoi(argv[1]):12;
    int n_pad = (n + PB - 1) / PB * PB;
    uint8_t* P = malloc((size_t)n*d);
    int16_t* Q16 = malloc((size_t)nq*d*2);
    int32_t* p2 = malloc((size_t)n*4);
    int32_t* q2 = malloc((size_t)nq*4);
    uint8_t* PT = calloc((size_t)d * n_pad, 1);
    srand(1);
    for (size_t i=0;i<(size_t)n*d;++i) P[i]=rand()&255;
    for (size_t i=0;i<(size_t)nq*d;++i) Q16[i]=rand()&255;
    for (int i=0;i<n;++i){int s=0; for(int j=0;j<d;++j){ s+=P[(size_t)i*d+j]*P[(size_t)i*d+j]; PT[(size_t)j*n_pad+i]=P[(size_t)i*d+j]; } p2[i]=s;}
    for (int i=0;i<nq;++i){int s=0; for(int j=0;j<d;++j) s+=Q16[(size_t)i*d+j]*Q16[(size_t)i*d+j]; q2[i]=s;}
    int32_t* idx=malloc((size_t)nq*K*4);
    pthread_t th[32]; Job jobs[32];
    int chunk=(nq+nthreads-1)/nthreads;
    double t0=now(); int nt=0;
    for (int q=0;q<nq;q+=chunk){
        int q1=q+chunk; if(q1>nq)q1=nq;
        jobs[nt]=(Job){PT,Q16,p2,q2,n,n_pad,d,q,q1,idx};
        pthread_create(&th[nt],NULL,worker,&jobs[nt]); nt++;
    }
    for(int i=0;i<nt;++i) pthread_join(th[i],NULL);
    printf("threads %d time %.4f\n", nt, now()-t0);
}
EOF
