#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <immintrin.h>

static inline float hsum(__m256 v) {
    __m128 lo=_mm256_castps256_ps128(v);
    __m128 hi=_mm256_extractf128_ps(v,1);
    lo=_mm_add_ps(lo,hi);
    __m128 sh=_mm_movehdup_ps(lo);
    lo=_mm_add_ps(lo,sh);
    sh=_mm_movehl_ps(sh,lo);
    lo=_mm_add_ss(lo,sh);
    return _mm_cvtss_f32(lo);
}
static inline void ins(float* bd, int32_t* bi, int k, float s, int32_t id) {
    if (s >= bd[k-1]) return;
    int pos=k-1;
    while (pos>0 && s<bd[pos-1]) { bd[pos]=bd[pos-1]; bi[pos]=bi[pos-1]; --pos; }
    bd[pos]=s; bi[pos]=id;
}

#define B 4
#define G 8   /* points per horizontal-sum batch */

typedef struct {
    const float* P; const float* Q;
    int n,d,k,q0,q1;
    int32_t* idx; float* dist;
} Job;

static void* worker(void* arg) {
    Job* job=(Job*)arg;
    int n=job->n, d=job->d, k=job->k, d8=d&~7;
    int q=job->q0;
    for (; q+B-1<job->q1; q+=B) {
        const float* qv[B];
        for (int qi=0; qi<B; ++qi) qv[qi]=job->Q+(size_t)(q+qi)*d;
        float bd[B][16]; int32_t bi[B][16];
        for (int qi=0; qi<B; ++qi) for (int t=0;t<k;++t){ bd[qi][t]=1e30f; bi[qi][t]=-1; }

        int i=0;
        for (; i+G-1<n; i+=G) {
            __m256 acc[B][G];
            for (int qi=0; qi<B; ++qi) for (int g=0; g<G; ++g) acc[qi][g]=_mm256_setzero_ps();
            for (int j=0; j<d8; j+=8) {
                __m256 qq[B];
                for (int qi=0; qi<B; ++qi) qq[qi]=_mm256_loadu_ps(qv[qi]+j);
                for (int g=0; g<G; ++g) {
                    __m256 p=_mm256_loadu_ps(job->P+(size_t)(i+g)*d+j);
                    for (int qi=0; qi<B; ++qi) {
                        __m256 diff=_mm256_sub_ps(qq[qi], p);
                        acc[qi][g]=_mm256_fmadd_ps(diff, diff, acc[qi][g]);
                    }
                }
            }
            float s[B][G];
            for (int qi=0; qi<B; ++qi) for (int g=0; g<G; ++g) s[qi][g]=hsum(acc[qi][g]);
            if (d8 < d) {
                for (int g=0; g<G; ++g) {
                    const float* pv=job->P+(size_t)(i+g)*d;
                    for (int j=d8; j<d; ++j) {
                        float pvj=pv[j];
                        for (int qi=0; qi<B; ++qi) { float t=qv[qi][j]-pvj; s[qi][g]+=t*t; }
                    }
                }
            }
            for (int g=0; g<G; ++g)
                for (int qi=0; qi<B; ++qi)
                    ins(bd[qi], bi[qi], k, s[qi][g], i+g);
        }
        for (int qi=0; qi<B; ++qi) for (int t=0;t<k;++t) {
            job->idx[(size_t)(q+qi)*k+t]=bi[qi][t];
            job->dist[(size_t)(q+qi)*k+t]=bd[qi][t];
        }
    }
    return NULL;
}
static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}
int main(int argc, char** argv){
    int n=19800,nq=1980,d=99,k=10,nthreads=argc>1?atoi(argv[1]):12;
    float *P=NULL,*Q=NULL;
    posix_memalign((void**)&P,64,(size_t)n*d*4);
    posix_memalign((void**)&Q,64,(size_t)nq*d*4);
    srand(1);
