#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <immintrin.h>

static inline void ins(float* bd, int32_t* bi, int k, float s, int32_t id) {
    if (s >= bd[k-1]) return;
    int pos=k-1;
    while (pos>0 && s<bd[pos-1]) { bd[pos]=bd[pos-1]; bi[pos]=bi[pos-1]; --pos; }
    bd[pos]=s; bi[pos]=id;
}

/* PT: (d, n_pad) float, row per dimension.
   Each thread handles a query block. For a panel of PB points, accumulate
   B queries x PB points with the point-panel streamed once per dimension. */

#define B 4
#define PB 64

typedef struct {
    const float* PT; /* (d, n_pad) */
    const float* Q;
    int n, n_pad, d, k, q0, q1;
    int32_t* idx; float* dist;
} Job;

static void* worker(void* arg) {
    Job* job=(Job*)arg;
    int n=job->n, d=job->d, k=job->k, n_pad=job->n_pad;
    int nq_local = job->q1 - job->q0;
    float* bd = malloc((size_t)nq_local * k * 4);
    int32_t* bi = malloc((size_t)nq_local * k * 4);
    for (int i=0;i<nq_local*k;++i){ bd[i]=1e30f; bi[i]=-1; }

    for (int ps=0; ps<n; ps+=PB) {
        int pb = n-ps; if (pb>PB) pb=PB;
        for (int qs=0; qs<nq_local; qs+=B) {
            int qb = nq_local-qs; if (qb>B) qb=B;
            float acc[B][PB];
            memset(acc, 0, sizeof(acc));
            if (qb==B && pb==PB) {
                for (int j=0;j<d;++j) {
                    const float* row = job->PT + (size_t)j*n_pad + ps;
                    float q0=job->Q[(size_t)(job->q0+qs+0)*d+j];
                    float q1=job->Q[(size_t)(job->q0+qs+1)*d+j];
                    float q2=job->Q[(size_t)(job->q0+qs+2)*d+j];
                    float q3=job->Q[(size_t)(job->q0+qs+3)*d+j];
                    int t=0;
                    for (; t+8<=PB; t+=8) {
                        __m256 p=_mm256_loadu_ps(row+t);
                        __m256 d0=_mm256_sub_ps(_mm256_set1_ps(q0), p);
                        __m256 d1=_mm256_sub_ps(_mm256_set1_ps(q1), p);
                        __m256 d2=_mm256_sub_ps(_mm256_set1_ps(q2), p);
                        __m256 d3=_mm256_sub_ps(_mm256_set1_ps(q3), p);
                        __m256 a0=_mm256_loadu_ps(&acc[0][t]);
                        __m256 a1=_mm256_loadu_ps(&acc[1][t]);
                        __m256 a2=_mm256_loadu_ps(&acc[2][t]);
                        __m256 a3=_mm256_loadu_ps(&acc[3][t]);
                        a0=_mm256_fmadd_ps(d0,d0,a0);
                        a1=_mm256_fmadd_ps(d1,d1,a1);
                        a2=_mm256_fmadd_ps(d2,d2,a2);
                        a3=_mm256_fmadd_ps(d3,d3,a3);
                        _mm256_storeu_ps(&acc[0][t], a0);
                        _mm256_storeu_ps(&acc[1][t], a1);
                        _mm256_storeu_ps(&acc[2][t], a2);
                        _mm256_storeu_ps(&acc[3][t], a3);
                    }
                }
                for (int qi=0; qi<B; ++qi) {
                    float* bdr = bd + (qs+qi)*k;
                    int32_t* bir = bi + (qs+qi)*k;
                    for (int t=0;t<PB && ps+t<n; ++t) ins(bdr, bir, k, acc[qi][t], ps+t);
                }
            } else {
                for (int j=0;j<d;++j) {
                    const float* row = job->PT + (size_t)j*n_pad + ps;
                    for (int qi=0; qi<qb; ++qi) {
                        float qv = job->Q[(size_t)(job->q0+qs+qi)*d+j];
                        for (int t=0;t<pb;++t) {
                            float diff=qv-row[t];
                            acc[qi][t]+=diff*diff;
                        }
                    }
                }
                for (int qi=0; qi<qb; ++qi) {
                    float* bdr = bd + (qs+qi)*k;
                    int32_t* bir = bi + (qs+qi)*k;
                    for (int t=0;t<pb;++t) ins(bdr, bir, k, acc[qi][t], ps+t);
                }
            }
        }
    }
    for (int qi=0; qi<nq_local; ++qi) for (int t=0;t<k;++t) {
        job->idx[(size_t)(job->q0+qi)*k+t]=bi[qi*k+t];
        job->dist[(size_t)(job->q0+qi)*k+t]=bd[qi*k+t];
    }
    free(bd); free(bi);
    return NULL;
}
static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}
int main(int argc, char** argv){
    int n=19800,nq=1980,d=99,k=10,nthreads=argc>1?atoi(argv[1]):6;
    int n_pad=(n+7)&~7;
    float *P=NULL,*Q=NULL,*PT=NULL;
    posix_memalign((void**)&P,64,(size_t)n*d*4);
    posix_memalign((void**)&Q,64,(size_t)nq*d*4);
    posix_memalign((void**)&PT,64,(size_t)d*n_pad*4);
    srand(1);
    for(size_t i=0;i<(size_t)n*d;++i) P[i]=(float)rand()/RAND_MAX;
    for(size_t i=0;i<(size_t)nq*d;++i) Q[i]=(float)rand()/RAND_MAX;
    memset(PT,0,(size_t)d*n_pad*4);
    for(int j=0;j<d;++j) for(int i=0;i<n;++i) PT[(size_t)j*n_pad+i]=P[(size_t)i*d+j];
    int32_t* idx=malloc((size_t)nq*k*4);
    float* dist=malloc((size_t)nq*k*4);
    pthread_t th[32]; Job jobs[32];
    int chunk=(nq+nthreads-1)/nthreads; if(chunk%B) chunk+=B-chunk%B;
    double t0=now(); int nt=0;
    for(int q=0;q<nq;q+=chunk){
        int q1=q+chunk; if(q1>nq)q1=nq;
        jobs[nt]=(Job){PT,Q,n,n_pad,d,k,q,q1,idx,dist};
        pthread_create(&th[nt],NULL,worker,&jobs[nt]); nt++;
    }
    for(int i=0;i<nt;++i) pthread_join(th[i],NULL);
    double s=0; for(int i=0;i<nq*k;i+=97) s+=dist[i];
    printf("threads %d time %.4f checksum %f\n", nt, now()-t0, s);
}
